export type LogCategory = 'TRANSCRIPTION' | 'API_KEY' | 'REPORT' | 'ANALYSIS' | 'SYSTEM';
export type LogStatus = 'SUCCESS' | 'ERROR' | 'WARNING' | 'INFO';

export interface SystemLogItem {
  id: string;
  timestamp: string;
  category: LogCategory;
  status: LogStatus;
  message: string;
  details?: string;
}

export const logSystemActivity = async (
  category: LogCategory,
  status: LogStatus,
  message: string,
  details: string = ''
) => {
  const logEntry: SystemLogItem = {
    id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
    timestamp: new Date().toISOString(),
    category,
    status,
    message,
    details
  };

  try {
    await addToStore(STORES.SYSTEM_ACTIVITY_LOGS, logEntry);
    console.log(`[SystemLog] ${category}: ${message}`);
  } catch (error) {
    console.error("Failed to save system log:", error);
  }
};

