import React, { useState, useRef, useEffect } from 'react';

declare var html2pdf: any;

interface DownloadMenuProps {
  transcript: string;
  fileName: string;
  activeColors: any;
  t: any;
  searchTerm?: string;
  addToast: (message: string, type: 'success' | 'error' | 'info' | 'warning') => void;
}

export const DownloadMenu: React.FC<DownloadMenuProps> = ({ transcript, fileName, activeColors, t, searchTerm, addToast }) => {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const downloadFile = (content: Blob, ext: string) => {
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileName.split('.')[0]}_transcript.${ext}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    setIsOpen(false);
    addToast(`${ext.toUpperCase()} ফাইল ডাউনলোড শুরু হয়েছে`, 'success');
  };

  const exportTxt = () => {
    const blob = new Blob([transcript], { type: 'text/plain;charset=utf-8' });
    downloadFile(blob, 'txt');
  };

  const exportWord = () => {
    const header = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><title>Transcript</title><style>body { font-family: "Hind Siliguri", sans-serif; }</style></head><body>`;
    const footer = "</body></html>";
    const sourceHTML = header + transcript.replace(/\n/g, '<br>') + footer;
    const blob = new Blob(['\ufeff', sourceHTML], { type: 'application/msword' });
    downloadFile(blob, 'doc');
  };

  const exportPDF = async () => {
    setIsOpen(false);
    addToast('PDF ফাইল জেনারেট হচ্ছে...', 'info');

    const element = document.createElement('div');
    element.style.padding = '40px';
    element.style.color = '#1e293b';
    element.style.backgroundColor = '#ffffff';
    element.style.fontFamily = "'Hind Siliguri', 'Inter', sans-serif";

    const headerHtml = `
      <div style="border-bottom: 2px solid #6366f1; padding-bottom: 20px; margin-bottom: 30px; display: flex; justify-content: space-between; align-items: center;">
        <div>
          <h1 style="margin: 0; font-size: 24px; font-weight: 900; color: #4338ca;">LI CELL STUDIO</h1>
          <p style="margin: 5px 0 0 0; font-size: 10px; font-weight: 900; color: #64748b; letter-spacing: 2px;">TRANSCRIPTION EXPORT ${searchTerm ? '(SEARCH HIGHLIGHTED)' : ''}</p>
        </div>
        <div style="text-align: right;">
          <p style="margin: 0; font-size: 10px; font-weight: 700; color: #94a3b8;">DATE: ${new Date().toLocaleDateString()}</p>
          <p style="margin: 5px 0 0 0; font-size: 10px; font-weight: 700; color: #94a3b8;">FILE: ${fileName}</p>
        </div>
      </div>
    `;

    const highlightText = (text: string) => {
      if (!searchTerm) return text;
      const regex = new RegExp(`(${searchTerm})`, 'gi');
      return text.replace(regex, '<mark style="background-color: #f97316; color: white; padding: 0 2px; border-radius: 2px;">$1</mark>');
    };

    const contentHtml = transcript.split('\n').map(line => {
      let processedLine = line;
      if (processedLine.trim().startsWith('**')) {
        processedLine = processedLine.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #4338ca; font-weight: 700;">$1</strong>');
      }
      const finalLine = highlightText(processedLine);
      return `<p style="margin-bottom: 15px; line-height: 1.6; font-size: 13px;">${finalLine}</p>`;
    }).join('');

    element.innerHTML = headerHtml + contentHtml;

    const options = {
      margin: [15, 15, 15, 15],
      filename: `${fileName.split('.')[0]}_transcript.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    try {
      await html2pdf().from(element).set(options).save();
      addToast('PDF ডাউনলোড সম্পন্ন হয়েছে', 'success');
    } catch (e) {
      addToast('PDF জেনারেশন ব্যর্থ হয়েছে', 'error');
    }
  };

  const exportSRT = () => {
    let srtContent = "";
    const lines = transcript.split('\n').filter(l => l.trim() !== "");
    lines.forEach((line, index) => {
      const timeMatch = line.match(/\[(\d{2}:\d{2})\]/);
      const startTimeStr = timeMatch ? timeMatch[1] : "00:00";
      srtContent += `${index + 1}\n`;
      srtContent += `00:${startTimeStr}:00,000 --> 00:${startTimeStr}:05,000\n`;
      srtContent += `${line.replace(/\*\*.*?\*\*:/, '').trim()}\n\n`;
    });
    const blob = new Blob([srtContent], { type: 'text/srt;charset=utf-8' });
    downloadFile(blob, 'srt');
  };

  return (
    <div className="relative" ref={menuRef}>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center px-8 py-3.5 bg-white text-slate-900 rounded-full text-sm font-black uppercase tracking-widest hover:brightness-95 transition-all shadow-xl active:scale-95 shrink-0 group ${isOpen ? 'ring-4 ring-indigo-500/20' : ''}`}
      >
        <svg className={`w-5 h-5 mr-3 transition-transform duration-500 ${isOpen ? 'rotate-180' : 'group-hover:scale-125'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
        </svg>
        {t.download}
        <svg className={`w-4 h-4 ml-2 transition-transform ${isOpen ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {isOpen && (
        <div className="absolute right-0 top-full mt-3 w-64 bg-slate-900/95 backdrop-blur-2xl border border-white/10 rounded-[2rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.6)] overflow-hidden z-[100] animate-in fade-in slide-in-from-top-4 duration-300 ring-1 ring-white/5">
          <div className="p-3 space-y-1.5">
            <button onClick={exportTxt} className="w-full flex items-center gap-4 px-5 py-4 text-white hover:bg-white/10 transition-all rounded-2xl group text-left active:scale-[0.97]">
              <div className="w-10 h-10 bg-blue-500/20 text-blue-400 rounded-xl flex items-center justify-center group-hover:scale-110 group-hover:bg-blue-500 group-hover:text-white transition-all shadow-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
              </div>
              <div className="flex flex-col">
                <span className="text-[11px] font-black tracking-widest uppercase">Notepad</span>
                <span className="text-[9px] text-white/40 font-bold uppercase">Plain Text File</span>
              </div>
            </button>

            <button onClick={exportWord} className="w-full flex items-center gap-4 px-5 py-4 text-white hover:bg-white/10 transition-all rounded-2xl group text-left active:scale-[0.97]">
              <div className="w-10 h-10 bg-indigo-500/20 text-indigo-400 rounded-xl flex items-center justify-center group-hover:scale-110 group-hover:bg-indigo-500 group-hover:text-white transition-all shadow-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253"/></svg>
              </div>
              <div className="flex flex-col">
                <span className="text-[11px] font-black tracking-widest uppercase">Word Document</span>
                <span className="text-[9px] text-white/40 font-bold uppercase">Editable MS Word</span>
              </div>
            </button>

            <button onClick={exportSRT} className="w-full flex items-center gap-4 px-5 py-4 text-white hover:bg-white/10 transition-all rounded-2xl group text-left active:scale-[0.97]">
              <div className="w-10 h-10 bg-amber-500/20 text-amber-400 rounded-xl flex items-center justify-center group-hover:scale-110 group-hover:bg-amber-500 group-hover:text-white transition-all shadow-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z"/></svg>
              </div>
              <div className="flex flex-col">
                <span className="text-[11px] font-black tracking-widest uppercase">Subtitle SRT</span>
                <span className="text-[9px] text-white/40 font-bold uppercase">Captions with Time</span>
              </div>
            </button>

            <button onClick={exportPDF} className="w-full flex items-center gap-4 px-5 py-4 text-white hover:bg-white/10 transition-all rounded-2xl group text-left active:scale-[0.97]">
              <div className="w-10 h-10 bg-rose-500/20 text-rose-400 rounded-xl flex items-center justify-center group-hover:scale-110 group-hover:bg-rose-500 group-hover:text-white transition-all shadow-lg">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
              </div>
              <div className="flex flex-col">
                <span className="text-[11px] font-black tracking-widest uppercase">PDF Document</span>
                <span className="text-[9px] text-white/40 font-bold uppercase">Ready to Print</span>
              </div>
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { YouTubeInput } from '../tools/YouTubeInput.tsx';

interface SidebarProps {
  t: any;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (v: boolean) => void;
  sidebarSide: 'left' | 'right';
  bgColor: string;
  activeColors: any;
  cardBg: string;
  cardBorder: string;
  isDark: boolean;
  subTextColor: string;
  fileInputRef: React.RefObject<HTMLInputElement>;
  handleFileChange: (e: any, autoStart?: boolean) => void;
  fileUrl: string | null;
  resetAll: () => void;
  fileMeta: any;
  audioRef: React.RefObject<HTMLAudioElement>;
  processTranscription: () => void;
  status: string;
  history: any[];
  setIsHistoryFullscreen: (v: boolean) => void;
  groupHistory: (items: any[]) => any;
  loadHistoryItem: (item: any) => void;
  appLang: string;
  // Recording Props
  isRecording: boolean;
  recordingTime: number;
  onStartRecording: () => void;
  onStopRecording: () => void;
  // New Props
  activeHistoryId?: string | null;
  onDeleteHistoryItem?: (id: string) => void;
}

// Sub-component for individual history items to handle long-press logic cleanly
const HistoryItemCard = ({ 
  item, 
  activeHistoryId, 
  loadHistoryItem, 
  onDeleteHistoryItem, 
  isDark, 
  activeColors, 
  appLang, 
  getSensitiveMatch 
}: any) => {
  const sensitiveMatch = getSensitiveMatch(item.transcript);
  const isSensitive = !!sensitiveMatch;
  const isActive = activeHistoryId === item.id;

  const timerRef = useRef<number | null>(null);
  const isLongPressTriggered = useRef(false);

  const handleStart = () => {
    isLongPressTriggered.current = false;
    timerRef.current = window.setTimeout(() => {
      isLongPressTriggered.current = true;
      if (onDeleteHistoryItem) {
        onDeleteHistoryItem(item.id);
        if (navigator.vibrate) navigator.vibrate(200); // Haptic feedback
      }
    }, 3000); // 3 Seconds Long Press
  };

  const handleEnd = () => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  };

  const handleClick = (e: React.MouseEvent) => {
    // If long press triggered, don't load the item
    if (!isLongPressTriggered.current) {
      loadHistoryItem(item);
    }
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    handleEnd();
    // Allow click event to fire for navigation unless long press happened
  };

  // Determine classes based on state
  let itemClass = "";

  if (isActive) {
      // ACTIVE STATE: Light Green as requested
      itemClass = isDark 
          ? 'bg-green-900/20 border-green-500/50 shadow-[0_0_15px_rgba(34,197,94,0.1)]' 
          : 'bg-green-50 border-green-400 shadow-md';
  } else if (isSensitive) {
      // Sensitive State
      itemClass = isDark 
          ? 'bg-red-900/10 border-red-500/30 hover:bg-red-900/20 hover:border-red-500/50' 
          : 'bg-red-50 border-red-100 hover:bg-red-100 hover:border-red-200';
  } else {
      // Default State
      itemClass = isDark 
          ? 'bg-white/5 border-white/10 hover:bg-white/10 hover:border-indigo-400/50' 
          : 'bg-white border-slate-100 hover:bg-indigo-50 hover:border-indigo-200';
  }

  return (
    <div 
      onMouseDown={handleStart}
      onMouseUp={handleEnd}
      onMouseLeave={handleEnd}
      onTouchStart={handleStart}
      onTouchEnd={handleTouchEnd}
      onClick={handleClick}
      className={`p-4 border rounded-2xl transition-all group relative active:scale-[0.98] cursor-pointer shadow-sm hover:shadow-xl select-none ${itemClass}`}
    >
      <div className="flex justify-between items-start mb-2 gap-2">
          <p className={`text-[11px] font-bold ${isActive ? (isDark ? 'text-green-400' : 'text-green-800') : (isDark ? 'text-white/90' : 'text-slate-700')} truncate font-stylish-bn transition-colors group-hover:text-indigo-500`}>
            {item.fileName}
          </p>
          {isActive && (
             <span className={`shrink-0 px-1.5 py-0.5 text-[8px] font-black rounded uppercase tracking-wider ${isDark ? 'bg-green-500/20 text-green-400' : 'bg-green-100 text-green-700'}`}>
                 LOADED
             </span>
          )}
          {sensitiveMatch && !isActive && (
              <span className="shrink-0 px-1.5 py-0.5 bg-red-600 text-white text-[8px] font-black rounded uppercase tracking-wider animate-pulse">
                  {sensitiveMatch}
              </span>
          )}
      </div>

      <div className={`flex flex-col gap-2 text-[9px] ${isActive ? (isDark ? 'text-green-200/60' : 'text-green-700/60') : (isDark ? 'text-white/40' : 'text-slate-400')} font-black uppercase tracking-wider`}>
        {/* Date & Time Row */}
        <div className="flex items-center gap-1.5" title="Creation Date">
            <svg className="w-3 h-3 transition-transform group-hover:scale-125" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            <span>{new Date(item.date).toLocaleTimeString(appLang === 'bn' ? 'bn-BD' : 'en-US', { timeStyle: 'short' })}</span>
        </div>

        {/* Processing Time & Duration Row */}
        <div className={`flex items-center justify-between border-t border-dashed pt-1.5 mt-0.5 ${isActive ? (isDark ? 'border-green-500/30' : 'border-green-300') : 'border-current/20'}`}>
            <span className="opacity-70 group-hover:opacity-100 transition-opacity flex items-center gap-1" title="File Duration">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                {item.duration}
            </span>
            <span className={`${isActive ? (isDark ? 'text-green-300' : 'text-green-600') : activeColors.text} flex items-center gap-1`} title="Processing Time">
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
              {item.timeTaken}
            </span>
        </div>
      </div>
    </div>
  );
};

export const Sidebar: React.FC<SidebarProps> = ({
  t, isSidebarOpen, setIsSidebarOpen, sidebarSide, bgColor, activeColors,
  cardBg, cardBorder, isDark, subTextColor, fileInputRef, handleFileChange,
  fileUrl, resetAll, fileMeta, audioRef, processTranscription, status,
  history = [], setIsHistoryFullscreen, groupHistory, loadHistoryItem, appLang,
  isRecording, recordingTime, onStartRecording, onStopRecording,
  activeHistoryId, onDeleteHistoryItem
}) => {
  const [activeTab, setActiveTab] = useState<'upload' | 'record' | 'youtube' | 'facebook'>('upload');
  const [playbackRate, setPlaybackRate] = useState(1);

  const SENSITIVE_KEYWORDS = [
    'বিজিবি', 'bgb', 'বিডিআর', 'বিডিয়ার', 'bdr', 'dg bgb', 'dg bdr',
    'বিজিবি মহাপরিচালক', 'সীমান্ত', 'বিজিবি সিও', 'বিজিবি অধিনায়ক',
    'বর্ডার গার্ড', 'বর্ডার গার্ড বাংলাদেশ', 'বিএসএফ', 'বিএসএফ ডিজি', 'বিএসএফ মহাপরিচালক'
  ];

  const getSensitiveMatch = (text: string) => {
    if (!text) return null;
    const lower = text.toLowerCase();
    return SENSITIVE_KEYWORDS.find(kw => lower.includes(kw));
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleYouTubeSuccess = (blob: Blob, fileName: string, mode: 'download' | 'transcribe') => {
      // 1. Trigger Download to PC (Always fallback to client download)
      try {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        // Note: We don't immediately revoke if transcribing, to allow rendering
      } catch (e) {
        console.error("Download failed", e);
      }

      // 2. Trigger Auto Transcription ONLY if mode is 'transcribe'
      if (mode === 'transcribe') {
          const file = new File([blob], fileName, { type: blob.type || 'audio/mp3' });
          handleFileChange({ target: { files: [file] } }, true);
      }
  };

  const changePlaybackRate = (rate: number) => {
    if (audioRef.current) {
        audioRef.current.playbackRate = rate;
    }
    setPlaybackRate(rate);
  };

  const skipTime = (seconds: number) => {
    if (audioRef.current) {
        audioRef.current.currentTime += seconds;
    }
  };

  const getHeaderTitle = () => {
      if (isRecording) return appLang === 'bn' ? "রেকর্ডিং চলছে..." : "Recording...";
      if (activeTab === 'youtube') return 'YOUTUBE LINK';
      if (activeTab === 'facebook') return 'FACEBOOK LINK';
      return t.audioVideoFile;
  };

  return (
    <aside 
      className={`h-full ${bgColor} z-[60] transition-all duration-500 ease-in-out transform flex flex-col overflow-hidden absolute md:relative
        ${isSidebarOpen ? 'w-full md:w-[400px] p-0 shadow-[25px_0_70px_-15px_rgba(0,0,0,0.5)]' : 'w-0 p-0'}
        ${sidebarSide === 'left' ? 'left-0 border-r border-slate-200/20' : 'right-0 border-l border-slate-200/20 shadow-[-25px_0_70px_-15px_rgba(0,0,0,0.5)]'}`}
    >
      <div className="flex flex-col h-full w-full md:w-[400px] overflow-hidden relative">

        {/* Mobile Close Button */}
        <div className="md:hidden absolute top-4 right-4 z-50">
           <button 
             onClick={() => setIsSidebarOpen(false)}
             className="p-3 bg-red-500 text-white rounded-full shadow-lg active:scale-95 transition-transform"
           >
             <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
           </button>
        </div>

        {/* Main Scrolling Container */}
        <div className="flex-1 overflow-y-auto custom-scrollbar flex flex-col">

          {/* Audio/Video Input Section */}
          <div className="px-6 pt-6 shrink-0 mt-8 md:mt-0">
            <div className="flex items-center gap-3 bg-slate-950 px-5 py-3 rounded-2xl shadow-[0_15px_35px_rgba(0,0,0,0.4)] border border-white/10 mb-4 h-[52px]">
                <div className={`w-2.5 h-2.5 rounded-full ${isRecording ? 'bg-red-500 animate-ping' : (activeColors?.primary || 'bg-indigo-600')} shadow-[0_0_12px_rgba(255,255,255,0.4)] shrink-0`}></div>
                <span className="text-[12px] font-black uppercase tracking-[0.15em] text-white truncate">
                  {getHeaderTitle()}
                </span>
            </div>

            <div className={`${cardBg} p-1 rounded-3xl border ${cardBorder} shadow-[0_25px_50px_rgba(0,0,0,0.2)] overflow-hidden transition-all hover:translate-y-[-2px]`}>

              {!isRecording ? (
                <div className={`rounded-2xl p-4 flex flex-col gap-4 transition-all duration-300`}>

                  {/* Input Type Selector Icons */}
                  <div className="flex justify-center gap-3 mb-2">
                      <button 
                        onClick={() => { setActiveTab('upload'); fileInputRef.current?.click(); }}
                        className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-md group ${activeTab === 'upload' ? activeColors.primary + ' text-white ring-2 ring-offset-2 ring-indigo-200' : 'bg-white hover:bg-slate-50 text-slate-400'}`}
                        title="Upload File"
                      >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0l-4 4m4-4v12" /></svg>
                      </button>

                      <button 
                        onClick={() => { setActiveTab('record'); onStartRecording(); }}
                        className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-md group ${activeTab === 'record' ? 'bg-red-500 text-white ring-2 ring-offset-2 ring-red-200' : 'bg-white hover:bg-slate-50 text-slate-400'}`}
                        title="Record Audio"
                      >
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                      </button>

                      <button 
                        onClick={() => setActiveTab('youtube')}
