                        title="YouTube Link"
                      >
                          <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M23.498 6.186a3.016 3.016 0 0 0-2.122-2.136C19.505 3.545 12 3.545 12 3.545s-7.505 0-9.377.505A3.017 3.017 0 0 0 .502 6.186C0 8.07 0 12 0 12s0 3.93.502 5.814a3.016 3.016 0 0 0 2.122 2.136c1.871.505 9.376.505 9.376.505s7.505 0 9.377-.505a3.015 3.015 0 0 0 2.122-2.136C24 15.93 24 12 24 12s0-3.93-.502-5.814zM9.545 15.568V8.432L15.818 12l-6.273 3.568z"/></svg>
                      </button>

                      <button 
                        onClick={() => setActiveTab('facebook')}
                        className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-md group ${activeTab === 'facebook' ? 'bg-blue-600 text-white ring-2 ring-offset-2 ring-blue-200' : 'bg-white hover:bg-slate-50 text-slate-400'}`}
                        title="Facebook Link"
                      >
                          <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24"><path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/></svg>
                      </button>
                  </div>

                  {/* Hidden Input for File Upload */}
                  <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="audio/*,video/*" />

                  {/* Contextual Area based on Selection */}
                  {activeTab === 'upload' && (
                      <p className="text-[10px] text-center font-bold opacity-40 uppercase tracking-widest">{t.clickToUpload}</p>
                  )}

                  {(activeTab === 'youtube' || activeTab === 'facebook') && (
                      <div className="animate-in fade-in slide-in-from-top-2">
                          <YouTubeInput 
                              onSuccess={handleYouTubeSuccess}
                              isDark={isDark}
                              activeColors={activeColors}
                              appLang={appLang}
                              platform={activeTab}
                              onFolderOpen={() => fileInputRef.current?.click()}
                              showFormats={false} 
                          />
                      </div>
                  )}

                </div>
              ) : (
                // Active Recording Mode
                <div className={`border-[4px] border-dashed border-red-500/30 bg-red-500/5 rounded-2xl p-8 flex flex-col items-center justify-center transition-all duration-300`}>
                   <div className="relative mb-4">
                      <div className="w-16 h-16 rounded-full bg-red-500 animate-ping absolute inset-0 opacity-20"></div>
                      <div className="w-16 h-16 rounded-full bg-red-500 flex items-center justify-center text-white shadow-xl shadow-red-500/40 relative z-10">
                         <svg className="w-8 h-8 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                      </div>
                   </div>
                   <div className="text-3xl font-black text-red-500 tabular-nums tracking-tight mb-6">
                      {formatTime(recordingTime)}
                   </div>
                   <button 
                     onClick={onStopRecording}
                     className="px-8 py-3 bg-red-500 hover:bg-red-600 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.2em] shadow-lg transition-all active:scale-95 flex items-center gap-2"
                   >
                     <div className="w-2 h-2 bg-white rounded-sm"></div>
                     {appLang === 'bn' ? "বন্ধ করুন" : "STOP"}
                   </button>
                </div>
              )}

            </div>
          </div>

          {/* File Info Section */}
          {fileUrl && !isRecording && (
            <div className="px-6 py-6 animate-in fade-in slide-in-from-top-2 shrink-0">
              <div className="flex items-center gap-3 bg-slate-950 px-5 py-3 rounded-2xl shadow-[0_15px_35px_rgba(0,0,0,0.4)] border border-white/10 mb-4 h-[52px]">
                <div className={`w-2 h-2 rounded-full bg-indigo-400 shadow-[0_0_10px_rgba(129,140,248,0.4)] shrink-0 animate-pulse`}></div>
                <span className="text-[12px] font-black uppercase tracking-[0.15em] text-white truncate">{t.fileInfo}</span>
                <button onClick={resetAll} className="ml-auto text-red-400 hover:text-red-500 transition-all shrink-0 p-1 group"><svg className="w-4 h-4 transition-transform group-hover:scale-150 group-hover:rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg></button>
              </div>
              <div className={`${cardBg} p-5 rounded-3xl border ${cardBorder} shadow-[0_25px_50px_rgba(0,0,0,0.2)] space-y-4 hover:translate-y-[-2px] transition-all`}>
                <div className={`${isDark ? 'bg-white/5 border-white/10' : 'bg-slate-50 border-slate-100'} p-4 rounded-2xl border text-xs font-bold ${subTextColor} space-y-3`}>
                  <div className="flex justify-between items-center gap-4">
                    <span className="opacity-60 shrink-0">{t.nameLabel}</span> 
                    <span className={`${isDark ? 'text-white' : 'text-slate-900'} truncate font-black bg-white/5 px-2 py-1 rounded-lg flex-1 text-right`}>{fileMeta?.name}</span>
                  </div>
                  <div className="flex justify-between items-center"><span className="opacity-60">{t.sizeLabel}</span> <span className={isDark ? 'text-white' : 'text-slate-900'}>{fileMeta?.size}</span></div>
                  <div className="flex justify-between items-center"><span className="opacity-60">{t.durationLabel}</span> <span className={`${isDark ? 'text-indigo-300' : (activeColors?.text || 'text-indigo-600')} font-black`}>{fileMeta?.duration}</span></div>
                </div>

                {/* Audio Player with Seek & Speed Control */}
                <div className="space-y-2">
                    <audio ref={audioRef} src={fileUrl} controls className="w-full h-10 bg-slate-50 rounded-lg p-1" />

                    <div className="flex items-center justify-between gap-2 px-1">
                        {/* SEEK BUTTONS */}
                        <div className="flex gap-2">
                            <button 
                                onClick={() => skipTime(-5)} 
                                className={`px-2 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all shadow-sm active:scale-95 flex items-center gap-1 ${isDark ? 'bg-white/10 hover:bg-white/20 text-white' : 'bg-slate-100 hover:bg-slate-200 text-slate-600'}`}
                                title="Rewind 5s"
                            >
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12.5 8l-5 4 5 4M7.5 8l-5 4 5 4" /></svg>
                                -5s
                            </button>
                            <button 
                                onClick={() => skipTime(5)} 
                                className={`px-2 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all shadow-sm active:scale-95 flex items-center gap-1 ${isDark ? 'bg-white/10 hover:bg-white/20 text-white' : 'bg-slate-100 hover:bg-slate-200 text-slate-600'}`}
                                title="Forward 5s"
                            >
                                +5s
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11.5 8l5 4-5 4M16.5 8l5 4-5 4" /></svg>
                            </button>
                        </div>

                        {/* SPEED CONTROL */}
                        <div className="flex gap-1 overflow-x-auto custom-scrollbar pb-1 sm:pb-0">
                            {[0.5, 1, 1.25, 1.5, 2].map(rate => (
                                <button 
                                    key={rate}
                                    onClick={() => changePlaybackRate(rate)}
                                    className={`px-1.5 py-1 rounded text-[9px] font-black transition-all ${
                                        playbackRate === rate 
                                        ? (activeColors?.primary || 'bg-indigo-500') + ' text-white scale-110 shadow-sm' 
                                        : 'bg-slate-200/50 hover:bg-slate-200 text-slate-500'
                                    }`}
                                >
                                    {rate}x
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <button onClick={() => { processTranscription(); setIsSidebarOpen(false); }} disabled={status === 'processing'} className={`w-full py-4 ${activeColors?.primary || 'bg-indigo-600'} text-white rounded-xl text-xs font-black uppercase tracking-[0.2em] shadow-2xl hover:brightness-110 disabled:opacity-50 transition-all flex items-center justify-center gap-2 active:scale-95 group`}>
                  {status === 'processing' ? t.processingTranscribe : <><svg className="w-4 h-4 transition-transform group-hover:rotate-12 group-hover:scale-125" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>{t.startTranscribe}</>}
                </button>
              </div>
            </div>
          )}

          {/* History Section */}
          <div className="flex flex-col">
            <div className="px-6 pt-4 sticky top-0 z-20 bg-inherit shrink-0">
              <div className="flex items-center gap-3 bg-slate-950 px-4 py-3 rounded-2xl shadow-[0_15px_35px_rgba(0,0,0,0.4)] border border-white/10 mb-2 h-[52px]">
                <div className={`w-2.5 h-2.5 rounded-full bg-amber-400 shadow-[0_0_12px_rgba(251,191,36,0.5)] shrink-0 animate-pulse`}></div>
                <span className="text-[12px] font-black uppercase tracking-[0.15em] text-white truncate">{t.history}</span>
                <span className={`text-[9px] font-black px-2 py-0.5 rounded-full bg-white/10 text-white/60 border border-white/5 shrink-0`}>{(history?.length || 0)}</span>

                <button 
                  onClick={(e) => { e.stopPropagation(); setIsHistoryFullscreen(true); }} 
                  className="ml-auto w-8 h-8 flex items-center justify-center text-white/40 hover:text-white bg-white/5 hover:bg-white/10 rounded-lg transition-all border border-white/5 shadow-inner shrink-0 group" 
                  title={t.expand}
                >
                  <svg className="w-4 h-4 transition-transform group-hover:scale-150" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
                  </svg>
                </button>
              </div>
            </div>

            {/* History content */}
            <div className="px-6 pb-6 pt-1">
              {!history || history.length === 0 ? (
                <div className="h-40 flex flex-col items-center justify-center opacity-30 text-slate-400 group cursor-default">
                  <svg className="w-10 h-10 mb-2 transition-transform duration-700 group-hover:rotate-180 group-hover:scale-110" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                  <p className="text-[10px] font-bold uppercase tracking-widest">{t.empty}</p>
                </div>
              ) : (
                <div className={`${cardBg} p-5 rounded-3xl border ${cardBorder} shadow-[0_30px_60px_rgba(0,0,0,0.25)] transition-all mb-4`}>
                  {Object.entries(groupHistory(history)).map(([group, items], groupIndex) => (
                    <div key={group} className="relative">
                      {/* Sticky Date Header - Updated top position to create gap */}
                      <div className="sticky top-20 z-30 flex justify-center py-2 pointer-events-none">
                         <span className="bg-slate-900/90 backdrop-blur-md text-white text-[10px] font-black px-4 py-1.5 rounded-full border border-white/10 shadow-lg uppercase tracking-widest">
                           {group}
                         </span>
                      </div>

                      <div className="space-y-3 pb-6">
                        {(items as any[]).map(item => (
                          <HistoryItemCard 
                            key={item.id}
                            item={item}
                            activeHistoryId={activeHistoryId}
                            loadHistoryItem={loadHistoryItem}
                            onDeleteHistoryItem={onDeleteHistoryItem}
                            isDark={isDark}
                            activeColors={activeColors}
                            appLang={appLang}
                            getSensitiveMatch={getSensitiveMatch}
                          />
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </aside>
  );
};

import React, { useState } from 'react';

interface ExpandedHistoryProps {
  t: any;
  isDark: boolean;
  setIsHistoryFullscreen: (v: boolean) => void;
  histSearch: string;
  setHistSearch: (v: string) => void;
  histDateFilter: string;
  setHistDateFilter: (v: string) => void;
  filteredHistory: any[];
  loadHistoryItem: (item: any) => void;
  activeColors: any;
}

export const ExpandedHistory: React.FC<ExpandedHistoryProps> = ({
  t, isDark, setIsHistoryFullscreen, histSearch, setHistSearch,
  histDateFilter, setHistDateFilter, filteredHistory, loadHistoryItem, activeColors
}) => {
  const [hoveredCardId, setHoveredCardId] = useState<string | null>(null);

  const SENSITIVE_KEYWORDS = [
    'বিজিবি', 'bgb', 'বিডিআর', 'বিডিয়ার', 'bdr', 'dg bgb', 'dg bdr',
    'বিজিবি মহাপরিচালক', 'সীমান্ত', 'বিজিবি সিও', 'বিজিবি অধিনায়ক',
    'বর্ডার গার্ড', 'বর্ডার গার্ড বাংলাদেশ', 'বিএসএফ', 'বিএসএফ ডিজি', 'বিএসএফ মহাপরিচালক'
  ];

  const getSensitiveMatch = (text: string) => {
    if (!text) return null;
    const lower = text.toLowerCase();
    return SENSITIVE_KEYWORDS.find(kw => lower.includes(kw));
  };

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center bg-slate-950/40 backdrop-blur-xl animate-in fade-in zoom-in-95 duration-300">
      <div className={`w-[96vw] h-[94vh] rounded-[3rem] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.6)] border overflow-hidden flex flex-col ${isDark ? 'bg-[#877E7C] border-white/20' : 'bg-white border-white/20'}`}>

        {/* Expanded Header with Dynamic Theme Glass Effect */}
        <header className="px-10 py-8 bg-slate-950/95 backdrop-blur-3xl border-b border-white/10 flex flex-wrap items-center justify-between shrink-0 gap-6 shadow-2xl z-10 relative">
          <div className="flex items-center gap-6 group cursor-default">
            <div className={`w-16 h-16 ${activeColors.primary} rounded-3xl flex items-center justify-center text-white shadow-2xl shadow-black/40 ring-1 ring-white/20 transition-all duration-500 group-hover:scale-110 group-hover:rotate-6`}>
              <svg className="w-8 h-8 transition-transform group-hover:scale-110" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            </div>
            <div className="space-y-1">
              <h2 className="text-3xl font-black text-white uppercase tracking-wider leading-none font-stylish-bn group-hover:text-white transition-colors text-white/90">{t.history}</h2>
              <p className={`text-[10px] font-black ${activeColors.text.replace('text-', 'text-opacity-80 text-')} tracking-[0.3em] uppercase`}>{filteredHistory.length} {t.itemsLogged}</p>
            </div>
          </div>

          <div className="flex-1 max-w-2xl flex items-center justify-end gap-4">
            {/* Stable History Search Bar */}
            <div 
              className={`relative flex items-center bg-white/5 border border-white/10 rounded-full p-1.5 transition-all duration-300 shadow-inner w-full max-w-[400px] focus-within:bg-white/10 focus-within:ring-2 focus-within:ring-white/10 group/search`}
            >
               <div className={`w-9 h-9 flex items-center justify-center shrink-0 transition-all duration-300 group-hover/search:scale-125 ${histSearch ? activeColors.text : 'text-white/40'}`}>
                  <svg className="w-5 h-5 transition-transform group-hover/search:rotate-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
               </div>
               <input 
                type="text" 
                placeholder={t.searchHist}
                value={histSearch}
                onChange={(e) => setHistSearch(e.target.value)}
                className="bg-transparent border-none outline-none focus:outline-none focus:ring-0 text-sm font-bold text-white placeholder:text-white/20 flex-1 px-3"
               />
               {histSearch && (
                 <button onClick={() => setHistSearch('')} className="p-1.5 bg-white/10 rounded-full text-white/40 hover:text-white transition-all mr-1 hover:scale-125 hover:rotate-90">
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>
                 </button>
               )}
            </div>

            <div className="w-48 relative group/date">
               <input 
                type="date" 
                value={histDateFilter}
                onChange={(e) => setHistDateFilter(e.target.value)}
                className={`w-full bg-white/5 border border-white/10 rounded-full py-4 px-6 text-xs font-bold text-white outline-none focus:ring-4 ${activeColors.ring.replace('ring-', 'ring-opacity-20 ring-')} transition-all color-scheme-dark shadow-inner cursor-pointer group-hover/date:bg-white/10`}
               />
            </div>
          </div>

          <button 
            onClick={() => setIsHistoryFullscreen(false)} 
            className={`group flex items-center gap-4 ${activeColors.primary} hover:brightness-110 text-white px-10 py-4 rounded-2xl transition-all active:scale-95 shadow-xl border border-white/10`}
          >
            <span className="text-xs font-black uppercase tracking-widest">{t.close}</span>
            <svg className="w-5 h-5 transition-transform duration-500 group-hover:rotate-180 group-hover:scale-150" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </header>

        <div className={`flex-1 overflow-y-auto custom-scrollbar p-12 ${isDark ? 'bg-black/20' : 'bg-[#F1F3F5]'}`}>
           {filteredHistory.length === 0 ? (
             <div className="h-full flex flex-col items-center justify-center opacity-20 group/empty">
                <svg className="w-40 h-40 mb-8 transition-all duration-1000 group-hover/empty:scale-110 group-hover/empty:rotate-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 01-7 7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                <p className="text-3xl font-black uppercase tracking-widest">No Results Found</p>
             </div>
           ) : (
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 gap-8">
              {filteredHistory.map(item => {
                const sensitiveMatch = getSensitiveMatch(item.transcript);
                const isSensitive = !!sensitiveMatch;

                const cardBgClass = isSensitive 
                    ? (isDark ? 'bg-red-900/10 border-red-500/30' : 'bg-red-50 border-red-100')
                    : (isDark ? 'bg-white/10 border-white/20' : 'bg-white border-slate-200');

                const innerBorderClass = isSensitive
                    ? (isDark ? 'border-red-500/30 hover:border-red-400' : 'border-red-100 hover:border-red-300')
                    : (isDark ? 'border-white/20 hover:border-indigo-400/50' : 'border-slate-200 hover:border-indigo-300');

                return (
                <div 
                  key={item.id} 
                  className={`relative rounded-[3rem] transition-all duration-500 group overflow-hidden ${cardBgClass}`}
                  onMouseEnter={() => setHoveredCardId(item.id)}
                  onMouseLeave={() => setHoveredCardId(null)}
                >
                  <div 
                    onClick={() => loadHistoryItem(item)} 
                    className={`p-8 border h-full flex flex-col cursor-pointer ${innerBorderClass}`}
                  >
                    <div className={`absolute top-0 right-0 w-32 h-32 ${activeColors.soft.replace('bg-', 'bg-opacity-10 bg-')} blur-3xl opacity-0 group-hover:opacity-100 transition-opacity`}></div>
                    <div className="mb-6 flex items-start justify-between relative z-10">
                       <div className="flex gap-2 items-center">
                           <div className={`px-3 py-1 ${activeColors.soft} ${activeColors.text} rounded-lg text-[8px] font-black uppercase tracking-widest ring-1 ${activeColors.border.replace('border-', 'border-opacity-20 border-')} transition-transform group-hover:scale-110 group-hover:-rotate-3`}>
                               {item.extension || 'FILE'}
                           </div>
                           {/* Sensitive Match Pill */}
                           {sensitiveMatch && (
                               <div className="px-3 py-1 bg-red-600 text-white rounded-lg text-[8px] font-black uppercase tracking-widest ring-1 ring-red-500 shadow-lg shadow-red-500/20 animate-pulse">
                                   {sensitiveMatch}
                               </div>
                           )}
                       </div>

                       <div className={`text-slate-400 group-hover:${activeColors.text} transition-all duration-500 group-hover:scale-150 group-hover:rotate-12`}>
                          <svg className={`w-6 h-6 ${isSensitive ? 'text-red-400' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                       </div>
                    </div>
                    <h4 className={`text-sm font-black line-clamp-2 mb-8 uppercase tracking-tight leading-relaxed transition-colors font-stylish-bn group-hover:text-indigo-500 relative z-10 ${isDark ? 'text-white' : 'text-slate-800'}`}>{item.fileName}</h4>
                    <div className="mt-auto pt-6 border-t border-slate-100/50 flex items-center justify-between relative z-10">
                       <div className="flex flex-col group/info-date"><span className="text-[9px] font-black opacity-40 uppercase tracking-widest mb-1.5 group-hover/info-date:opacity-100 transition-opacity">{t.historyLabelDate}</span><span className={`text-[11px] font-black ${isDark ? 'text-white/80' : 'text-slate-600'}`}>{new Date(item.date).toLocaleDateString()}</span></div>
                       <div className="flex flex-col items-end group/info-dur">
                          <span className="text-[9px] font-black opacity-40 uppercase tracking-widest mb-1.5 group-hover/info-dur:opacity-100 transition-opacity">DURATION / TIME</span>
                          <div className="flex items-center gap-1.5">
                              <span className={`text-[11px] font-black ${activeColors.text}`}>{item.duration}</span>
                              <span className={`text-[9px] font-bold opacity-40 ${isDark ? 'text-white' : 'text-slate-600'}`}>({item.timeTaken})</span>
                          </div>
                       </div>
                    </div>
                  </div>

                  {/* Scrollable Popup Overlay on Hover */}
                  {hoveredCardId === item.id && (
                    <div 
                      className={`absolute inset-0 z-20 p-6 backdrop-blur-xl transition-all animate-in fade-in duration-300 overflow-hidden flex flex-col ${isDark ? 'bg-slate-900/95' : 'bg-white/95'}`}
                      onClick={(e) => e.stopPropagation()} // Prevent triggering load when interacting with popup text
                    >
                      <div className="flex items-center justify-between mb-3 shrink-0 border-b border-white/10 pb-2">
                        <span className={`text-[9px] font-black uppercase tracking-widest ${activeColors.text}`}>TRANSCRIPT PREVIEW</span>
                        <div onClick={() => loadHistoryItem(item)} className="cursor-pointer p-1.5 bg-white/10 rounded-full hover:bg-indigo-600 hover:text-white transition-all" title="Open File">
                           <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                        </div>
                      </div>
                      <div className="overflow-y-auto custom-scrollbar flex-1 pr-2">
                        <p className={`text-[11px] font-mono leading-relaxed whitespace-pre-wrap ${isDark ? 'text-white/80' : 'text-slate-700'}`}>
                          {(() => {
                             const textContent = item.transcript || "No transcript content...";
                             if (!sensitiveMatch) return textContent;

                             const regex = new RegExp(`(${sensitiveMatch})`, 'gi');
                             return textContent.split(regex).map((part: string, i: number) => 
                               part.toLowerCase() === sensitiveMatch.toLowerCase() ? (
                                 <mark key={i} className="bg-red-500 text-white px-1 rounded-sm font-bold mx-0.5 animate-pulse">
                                   {part}
                                 </mark>
                               ) : part
                             );
                          })()}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              );
              })}
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

