          <div ref={scrollContainerRef} onScroll={handleScroll} className="h-full w-full overflow-y-auto custom-scrollbar p-6 md:p-8 lg:p-16 xl:p-24 scroll-smooth relative z-10 animate-in slide-in-from-bottom-8 duration-700">
            <div className="max-w-6xl mx-auto">
              <div className={`p-6 md:p-10 lg:p-20 rounded-[2rem] md:rounded-[3rem] border shadow-[0_25px_60px_-15px_rgba(0,0,0,0.15)] transition-all duration-700 group/content backdrop-blur-xl ${isDark ? 'bg-slate-900/60 border-white/10' : 'bg-white/80 border-white/40'}`}>
