                      </div>

                      <div className="max-w-md">
                          <h4 className={`text-lg font-black uppercase mb-2 ${isDark ? 'text-white' : 'text-slate-800'}`}>Manual Data Sync</h4>
                          <p className={`text-xs font-medium leading-relaxed ${isDark ? 'text-white/60' : 'text-slate-500'}`}>
                              {appLang === 'bn' 
                                  ? 'এই বাটনটি চাপলে আপনার লোকাল ডাটাবেস (XAMPP) থেকে সব তথ্য ফায়ারবেজে আপলোড করা হবে। নতুন কাজগুলো অটোমেটিক আপলোড হয়, কিন্তু পুরনো ডাটা পাঠাতে এটি ব্যবহার করুন।'
                                  : 'Clicking this button will push all data from your Local Database (XAMPP) to Firebase. New data syncs automatically, use this for older data.'}
                          </p>
                      </div>

                      {isSyncing && (
                          <div className="w-full max-w-sm space-y-2">
                              <div className="h-2 bg-slate-200 dark:bg-white/10 rounded-full overflow-hidden">
                                  <div className="h-full bg-indigo-600 transition-all duration-300" style={{ width: `${syncProgress}%` }}></div>
                              </div>
                              <p className="text-[10px] font-black uppercase tracking-widest opacity-60">{syncStatus}</p>
                          </div>
                      )}

                      <button 
                          onClick={handleStartSync}
                          disabled={isSyncing}
                          className={`px-10 py-4 ${activeColors.primary} text-white rounded-2xl text-xs font-black uppercase tracking-[0.2em] shadow-xl hover:scale-105 active:scale-95 transition-all disabled:opacity-50 disabled:scale-100`}
                      >
                          {isSyncing ? 'SYNCING...' : (appLang === 'bn' ? 'সিঙ্ক শুরু করুন' : 'START FULL SYNC')}
                      </button>
                  </div>
              </div>
          )}
        </div>

        {!isMaximized && (
            <div 
            onMouseDown={startResizing}
            className="absolute bottom-2 right-2 w-10 h-10 cursor-nwse-resize flex items-center justify-center opacity-20 hover:opacity-100 transition-opacity z-[200]"
            >
            <svg className="w-6 h-6 text-slate-400 rotate-90" fill="currentColor" viewBox="0 0 24 24">
                <path d="M22 22h-2v-2h2v2zm0-4h-2v-2h2v2zm-4 4h-2v-2h2v2zm0-4h-2v-2h2v2zm-4 4h-2v-2h2v2zm8-8h-2v-2h2v2zm-12 8h-2v-2h2v2z"/>
            </svg>
            </div>
        )}
      </div>
      </div>
    </>
  );
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
