                                      <span className="block text-[9px] opacity-50 font-bold">Local &rarr; Cloud</span>
                                  </div>
                              </button>

                              {/* Sync DOWN (Download/Restore) */}
                              <button 
                                  onClick={() => handleStartSync('down')}
                                  className={`p-6 rounded-3xl border flex flex-col items-center gap-3 transition-all hover:scale-105 active:scale-95 group ${isDark ? 'bg-white/5 border-white/10 hover:bg-white/10' : 'bg-slate-50 border-slate-200 hover:bg-white hover:shadow-xl'}`}
                              >
                                  <div className="w-10 h-10 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center group-hover:bg-orange-500 group-hover:text-white transition-colors">
                                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg>
                                  </div>
                                  <div className="text-center">
                                      <span className="block text-xs font-black uppercase tracking-widest mb-1">{appLang === 'bn' ? 'রিস্টোর' : 'PULL / RESTORE'}</span>
                                      <span className="block text-[9px] opacity-50 font-bold">Cloud &rarr; Local</span>
                                  </div>
                              </button>
                          </div>
                      )}
                  </div>
              </div>
          )}
        </div>

        {!isMaximized && (
            <div 
            onMouseDown={startResizing}
            className="absolute bottom-2 right-2 w-10 h-10 cursor-nwse-resize flex items-center justify-center opacity-20 hover:opacity-100 transition-opacity z-[200]"
            >
            <svg className="w-6 h-6 text-slate-400 rotate-90" fill="currentColor" viewBox="0 0 24 24">
                <path d="M22 22h-2v-2h2v2zm0-4h-2v-2h2v2zm-4 4h-2v-2h2v2zm0-4h-2v-2h2v2zm-4 4h-2v-2h2v2zm8-8h-2v-2h2v2zm-12 8h-2v-2h2v2z"/>
            </svg>
            </div>
        )}
      </div>
      </div>
    </>
  );
};

import { getAllFromStore, addToStore, deleteFromStore, STORES } from './db.ts';

const ACTIVE_KEY_ID_STORAGE = 'manual_active_key_id';

// Define the Key Structure
export interface UserApiKey {
  id: string;
  key: string;
  label: string;
  addedAt: string;
}

// 1. Get the currently selected provider
export const getActiveProvider = async (): Promise<{ key: string, model: string, source: string } | null> => {
  const activeId = localStorage.getItem(ACTIVE_KEY_ID_STORAGE);

  if (!activeId) return null;

  try {
    // Fetch all keys from DB
    const allKeys = await getAllFromStore(STORES.API_KEYS);
    const selectedKey = allKeys.find((k: any) => k.id === activeId);

    if (selectedKey) {
      return {
        key: selectedKey.key,
        model: 'gemini-3-flash-preview', // Fixed model as per requirement
        source: selectedKey.label || 'Manual Selection'
      };
    }
  } catch (e) {
    console.error("Error fetching active key:", e);
  }

  return null;
};

// 2. Add a new Key
export const addUserApiKey = async (key: string, label: string) => {
  const newKey: UserApiKey = {
    id: Date.now().toString(),
    key: key.trim(),
    label: label.trim() || `Key ${new Date().toLocaleTimeString()}`,
    addedAt: new Date().toISOString()
  };

  await addToStore(STORES.API_KEYS, newKey);

  // If it's the first key, auto-select it for convenience (optional, but good UX)
  const allKeys = await getAllFromStore(STORES.API_KEYS);
  if (allKeys.length === 1) {
      localStorage.setItem(ACTIVE_KEY_ID_STORAGE, newKey.id);
  }

  return newKey;
};

// 3. Get All Keys
export const getAllApiKeys = async (): Promise<UserApiKey[]> => {
  const keys = await getAllFromStore(STORES.API_KEYS);
  return keys.sort((a: any, b: any) => new Date(b.addedAt).getTime() - new Date(a.addedAt).getTime());
};

// 4. Set Active Key
export const setActiveApiKey = (id: string) => {
  localStorage.setItem(ACTIVE_KEY_ID_STORAGE, id);
};

// 5. Delete Key
export const deleteApiKey = async (id: string) => {
  await deleteFromStore(STORES.API_KEYS, id);
  // If active key is deleted, clear selection
  if (localStorage.getItem(ACTIVE_KEY_ID_STORAGE) === id) {
    localStorage.removeItem(ACTIVE_KEY_ID_STORAGE);
  }
};

// 6. Get Active Key ID (Synchronous for UI check)
export const getActiveKeyId = () => {
  return localStorage.getItem(ACTIVE_KEY_ID_STORAGE);
};

