                      )}

                      <div className="absolute inset-0 bg-red-600/95 z-[250] rounded-[4rem] flex items-center justify-around px-12 animate-in fade-in duration-300 shadow-2xl" style={{display: deletingId === item.id ? 'flex' : 'none'}}>
