                          <div className="flex gap-6">
                            <button onClick={(e) => {e.stopPropagation(); setDeletingId(null);}} className="text-white bg-white/10 px-12 py-5 rounded-[1.5rem] text-[12px] font-black uppercase border border-white/20 hover:bg-white/20 transition-all">বাতিল</button>
                            <button onClick={(e) => confirmDelete(e, item.id)} className="text-red-600 bg-white px-12 py-5 rounded-[1.5rem] text-[12px] font-black uppercase shadow-[0_20px_40px_rgba(0,0,0,0.3)] hover:scale-110 active:scale-90 transition-all">ডিলিট</button>
                          </div>
                      </div>

                      <div className="flex items-center justify-between gap-12">
                        <div className="flex-1">
                          <div className="flex items-center gap-6 mb-6">
                             <div className="flex items-center gap-2">
                               <div className={`w-2 h-8 rounded-full ${activeColors?.primary || 'bg-indigo-600'}`}></div>
                               <span className={`px-6 py-2.5 rounded-2xl ${activeColors?.primary || 'bg-indigo-600'} text-white text-[13px] font-black uppercase tracking-widest shadow-xl`}>{item.searchTerm}</span>
                             </div>
