                                <span className="text-[12px] font-black uppercase tracking-[0.1em]">{item.matchCount}টি ম্যাচ</span>
                             </div>
                             <div className="flex items-center gap-2">
                               <div className={`w-2 h-2 rounded-full ${item.sentiment === 'pending' ? 'bg-slate-400' : item.sentiment === 'positive' ? 'bg-emerald-500' : item.sentiment === 'negative' ? 'bg-rose-500' : 'bg-indigo-400'}`}></div>
                               <span className="text-[10px] font-black uppercase tracking-widest">{getSentimentLabel(item.sentiment)}</span>
                             </div>
