          <div className={`p-8 border-t ${isDark ? 'border-white/10 bg-black/20' : 'border-slate-100 bg-slate-50/50'} shrink-0`}>
            <div className="relative flex items-center bg-white dark:bg-white/5 rounded-[1.8rem] border border-slate-200 dark:border-white/10 p-1.5 shadow-2xl focus-within:ring-4 focus-within:ring-indigo-500/10 transition-all duration-300">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                placeholder={appLang === 'bn' ? 'এখানে মেসেজ লিখুন...' : 'Type your message...'}
                className="bg-transparent border-none outline-none focus:ring-0 text-sm font-bold px-5 py-3.5 flex-1 placeholder:opacity-30 placeholder:uppercase placeholder:text-[10px]"
              />
              <button 
                onClick={handleSendMessage}
                disabled={!input.trim() || isTyping}
                className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all shadow-xl shrink-0 group/send ${input.trim() ? activeColors.primary + ' text-white hover:scale-105 active:scale-95' : 'bg-slate-100 text-slate-300'}`}
              >
                <svg className="w-5 h-5 transform rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M2 21l21-9L2 3v7l15 2-15 2v7z"/></svg>
              </button>
            </div>
          </div>
        </div>
      )}

      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-18 h-18 rounded-full flex items-center justify-center shadow-[0_25px_60px_-15px_rgba(0,0,0,0.6)] transition-all active:scale-90 group relative overflow-hidden ring-4 ring-white/10 z-[110] ${isOpen ? 'bg-slate-950 scale-110' : 'bg-white hover:scale-110'}`}
        style={{ width: '72px', height: '72px' }}
      >
        {!isOpen ? (
          <>
            <div className="absolute inset-0 bg-indigo-600 opacity-0 group-hover:opacity-10 transition-opacity"></div>
            <div className="w-12 h-12 flex items-center justify-center relative z-10 p-1 animate-in zoom-in duration-700">
              {!imgError ? (
                <img 
                  src={ASSISTANT_LOGO_URL} 
                  alt="Assistant" 
                  className="w-full h-full object-contain"
                  onError={() => setImgError(true)}
                />
              ) : <FallbackIcon />}
            </div>
            <div className="absolute top-1 right-1 w-5 h-5 bg-indigo-600 rounded-full border-4 border-white animate-pulse shadow-lg flex items-center justify-center">
               <div className="w-1.5 h-1.5 bg-white rounded-full"></div>
            </div>
          </>
        ) : (
          <svg className="w-10 h-10 text-white animate-in zoom-in duration-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
          </svg>
        )}
      </button>
    </div>
  );
};

import { getAllFromStore, addToStore, deleteFromStore, STORES } from './db.ts';

const ACTIVE_KEY_ID_STORAGE = 'manual_active_key_id';

// Define the Key Structure
export interface UserApiKey {
  id: string;
  key: string;
  label: string;
  addedAt: string;
}

export interface ApiCallLog {
  id: string;
  timestamp: string;
  source: string;
  model: string;
  status: 'success' | 'error';
  latency?: number;
}

// 1. Get the currently selected provider
export const getActiveProvider = async (): Promise<{ key: string, model: string, source: string } | null> => {
  const activeId = localStorage.getItem(ACTIVE_KEY_ID_STORAGE);

  if (!activeId) return null;

  try {
    // Fetch all keys from DB
    const allKeys = await getAllFromStore(STORES.API_KEYS);
    const selectedKey = allKeys.find((k: any) => k.id === activeId);

    if (selectedKey) {
      return {
        key: selectedKey.key,
        model: 'gemini-3-flash-preview', // Fixed model as per requirement
        source: selectedKey.label || 'Manual Selection'
      };
    }
  } catch (e) {
    console.error("Error fetching active key:", e);
  }

  return null;
};

// 2. Add a new Key
export const addUserApiKey = async (key: string, label: string) => {
  const newKey: UserApiKey = {
    id: Date.now().toString(),
    key: key.trim(),
    label: label.trim() || `Key ${new Date().toLocaleTimeString()}`,
    addedAt: new Date().toISOString()
  };

  await addToStore(STORES.API_KEYS, newKey);

  // If it's the first key, auto-select it for convenience (optional, but good UX)
  const allKeys = await getAllFromStore(STORES.API_KEYS);
  if (allKeys.length === 1) {
      localStorage.setItem(ACTIVE_KEY_ID_STORAGE, newKey.id);
  }

  return newKey;
};

// 3. Get All Keys
export const getAllApiKeys = async (): Promise<UserApiKey[]> => {
  const keys = await getAllFromStore(STORES.API_KEYS);
  return keys.sort((a: any, b: any) => new Date(b.addedAt).getTime() - new Date(a.addedAt).getTime());
};

// 4. Set Active Key
export const setActiveApiKey = (id: string) => {
  localStorage.setItem(ACTIVE_KEY_ID_STORAGE, id);
};

// 5. Delete Key
export const deleteApiKey = async (id: string) => {
  await deleteFromStore(STORES.API_KEYS, id);
  // If active key is deleted, clear selection
  if (localStorage.getItem(ACTIVE_KEY_ID_STORAGE) === id) {
    localStorage.removeItem(ACTIVE_KEY_ID_STORAGE);
  }
};

// 6. Get Active Key ID (Synchronous for UI check)
export const getActiveKeyId = () => {
  return localStorage.getItem(ACTIVE_KEY_ID_STORAGE);
};

