  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleSeek = (timeStr: string) => {
    if (!audioRef.current || !timeStr) return;
    const [m, s] = timeStr.split(':').map(Number);
    const totalSecs = (m * 60) + s;
    audioRef.current.currentTime = Math.max(0, totalSecs - 3);
    audioRef.current.play();
  };

  const transformTranscript = async (type: 'translate' | 'encoding') => {
    if (!transcript || transformingType) return;
    setTransformingType(type);
    setIsAiLoading(true);

    const executeCall = async () => {
      let provider = await getActiveProvider();

      if (!provider) {
          throw new Error("No Active API Key Selected. Please select one in Settings.");
      }

      setActiveApiKeySource(provider.source);
      setActiveModelName(provider.model);

      const ai = new GoogleGenAI({ apiKey: provider.key });
      const prompt = type === 'translate' 
        ? `Translate this transcript between Bengali and English. Keep speakers/timestamps: \n\n${transcript}`
        : `Convert Bengali text between Unicode and Bijoy: \n\n${transcript}`;

      const response: GenerateContentResponse = await ai.models.generateContent({ 
        model: provider.model, 
        contents: prompt 
      });
      const calls = await incrementTotalCalls();
      setTotalApiCalls(calls);
      return response.text;
    };

    try {
      const result = await executeCall();
      if (result) {
        setTranscript(result);
        addToast(appLang === 'bn' ? "সফলভাবে রূপান্তর করা হয়েছে" : "Transformed successfully", 'success');
      }
    } catch (e: any) {
      console.error(e);
      addToast(e.message || "Failed", 'error');
    } finally {
      setTransformingType(null);
      setIsAiLoading(false);
      updateApiKeyInfo();
    }
  };

  const resetAll = () => {
    setFileUrl(null);
    setSourceBlob(null); 
    setTranscript('');
    setStatus('idle');
    setFileMeta({ name: '', size: '', ext: '', duration: '' });
    setActiveTranscriptSourceMeta(null);
    setActiveHistoryId(null);
    setError('');
    setProgress(0);
    setSeconds(0);
    setEstimatedSeconds(0);
    setMatchCount(0);
    setCurrentMatchIndex(0);
    setSearchTerm('');
    setFileIconError(false); 

    setIsRecording(false);
    setRecordingTime(0);
    audioChunksRef.current = [];
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
    }

    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const processTranscription = async (overrideBlob?: Blob, overrideMeta?: any) => {
    const blobToUse = overrideBlob || sourceBlob;
    const metaToUse = overrideMeta || fileMeta;

    if (!blobToUse) {
        addToast(appLang === 'bn' ? "কোনো অডিও ফাইল পাওয়া যায়নি।" : "No audio source found.", 'error');
        return;
    }

    let fileName = metaToUse.name || "audio_file";

    // Check API Key
    const checkProvider = await getActiveProvider();
    if (!checkProvider || !checkProvider.key) {
        setError(appLang === 'bn' ? "সেটিংস থেকে একটি API Key সিলেক্ট করুন।" : "Please select an API Key in Settings.");
        setStatus('error');
        setIsSettingsOpen(true); 
        return;
    }

    setStatus('processing');
    setIsAiLoading(true);
    setProgress(10);
    setSeconds(0);

    let durationSecs = 60;
    const durStr = metaToUse.duration;
    if (durStr && durStr !== '...') {
        const parts = durStr.split(':').map(Number);
        if (parts.length === 3) durationSecs = parts[0] * 3600 + parts[1] * 60 + parts[2];
        else if (parts.length === 2) durationSecs = parts[0] * 60 + parts[1];
    }
    const estimatedProcTime = Math.max(10, Math.ceil(durationSecs * 0.2));
    setEstimatedSeconds(estimatedProcTime);

    const startTime = Date.now();
    timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);

    progressTimerRef.current = window.setInterval(() => {
        setProgress(prev => {
            if (prev >= 90) return 90;
            return prev + (prev < 50 ? 5 : 1);
        });
    }, 500);

    try {
        setCurrentStage(appLang === 'bn' ? "ফাইল প্রসেসিং হচ্ছে..." : "Processing file...");

        const reader = new FileReader();
        const base64Promise = new Promise<string>((resolve, reject) => {
            reader.onload = () => {
                if (typeof reader.result === 'string') {
                    const base64 = reader.result.split(',')[1];
                    resolve(base64);
                } else {
                    reject(new Error("File read failed"));
                }
            };
            reader.onerror = reject;
            reader.readAsDataURL(blobToUse);
        });

        const base64Data = await base64Promise;

        setCurrentStage(appLang === 'bn' ? "এআই জেনারেট করছে..." : "AI Generating...");
        const mimeType = blobToUse.type || 'audio/mp3';

        const ai = new GoogleGenAI({ apiKey: checkProvider.key });
        const response: GenerateContentResponse = await ai.models.generateContent({
            model: checkProvider.model || 'gemini-3-flash-preview', 
            contents: { 
                parts: [
                    { inlineData: { mimeType: mimeType, data: base64Data } }, 
                    { text: "Transcribe the audio verbatim. STRICT FORMAT: Start every new minute or speaker change with a timestamp [MM:SS]. Example: [00:00] **Speaker 1:** Hello. If no speech detected, output [Silence]." }
                ] 
            },
            config: {
                temperature: 0.1, 
                safetySettings: [
                    { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                    { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                    { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                    { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                ]
            }
        });

        await incrementTotalCalls();
        const text = response.text || "[Error: Model returned empty response]";

        finishTranscription(text, fileName, metaToUse, startTime);

    } catch (e: any) {
      if (progressTimerRef.current) clearInterval(progressTimerRef.current);
      if (timerRef.current) clearInterval(timerRef.current);

      console.error(e);
      let userMsg = e.message || 'Error occurred.';

      if (e.message?.includes('400') || e.message?.includes('403') || e.message?.includes('API key')) {
          userMsg = appLang === 'bn' 
            ? "API Key সমস্যা। দয়া করে সেটিংসে গিয়ে অন্য একটি কি সিলেক্ট করুন।" 
            : "API Key Error. Please select a different key in Settings.";
      } else if (e.message?.includes('429')) {
          userMsg = appLang === 'bn' 
            ? "কোটা শেষ (Quota Exceeded)। সেটিংসে গিয়ে অন্য কি ব্যবহার করুন।" 
            : "Quota exceeded. Change Key in Settings.";
      }

      setError(userMsg);
      setStatus('error');
      logSystemActivity('TRANSCRIPTION', 'ERROR', 'Transcription Failed', `File: ${fileName}, Error: ${e.message}`);
      setIsAiLoading(false);
      updateApiKeyInfo();
    }
  };

  const finishTranscription = async (text: string, fileName: string, metaToUse: any, startTime: number) => {
      if (progressTimerRef.current) clearInterval(progressTimerRef.current);
      if (timerRef.current) clearInterval(timerRef.current);

      const actualElapsedSeconds = Math.round((Date.now() - startTime) / 1000);
      const finalTimeStr = formatTime(actualElapsedSeconds);
      setFinalTimeDisplay(finalTimeStr);
      setProgress(100);

      setTranscript(text && text.trim().length > 0 ? text : '[No Content Generated]');
      setStatus('completed');
      setShowCompletionModal(true);

      const newHistoryItem = { 
        id: Date.now().toString(), 
        fileName: fileName, 
        transcript: text || '', 
        date: new Date().toISOString(), 
        timeTaken: finalTimeStr, 
        size: metaToUse.size, 
        duration: metaToUse.duration || '00:00',
        extension: metaToUse.ext 
      };

      setActiveTranscriptSourceMeta({
          name: fileName,
          size: metaToUse.size,
          duration: metaToUse.duration
      });
      setActiveHistoryId(newHistoryItem.id);

      await saveHistory(newHistoryItem);
      logSystemActivity('TRANSCRIPTION', 'SUCCESS', 'Transcription Completed', `File: ${fileName}, Duration: ${finalTimeStr}`);

      setIsAiLoading(false);
      updateApiKeyInfo();
  };

  const handleFileChange = async (e: any, autoStart: boolean = false) => {
    const file = e.target.files?.[0];
    if (!file) return;

    resetAll();

    const url = URL.createObjectURL(file);
    setFileUrl(url);
    const sizeStr = (file.size / 1e6).toFixed(2) + ' MB';
    const ext = file.name.split('.').pop() || '';
    const name = file.name;

    const getDuration = (srcUrl: string): Promise<string> => {
        return new Promise((resolve) => {
            const audio = new Audio(srcUrl);
            audio.onloadedmetadata = () => {
                if (audio.duration === Infinity || isNaN(audio.duration)) {
                    resolve('...');
                } else {
                    const mins = Math.floor(audio.duration / 60);
                    const secs = Math.floor(audio.duration % 60);
                    resolve(`${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`);
                }
            };
            audio.onerror = () => resolve('...');
            setTimeout(() => resolve('...'), 2000);
        });
    };

    const durationStr = await getDuration(url);

    const finalMeta = { name, size: sizeStr, ext, duration: durationStr };
    setFileMeta(finalMeta);
    setSourceBlob(file);

    if (autoStart) {
         processTranscription(file, finalMeta);
    }
  };

  const handleStartRecording = async () => {
     try {
         resetAll();
         const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
         const mimeType = 'audio/webm;codecs=opus';
         const options = MediaRecorder.isTypeSupported(mimeType) ? { mimeType, audioBitsPerSecond: 16000 } : { audioBitsPerSecond: 16000 };
         const recorder = new MediaRecorder(stream, options);
         mediaRecorderRef.current = recorder;
         audioChunksRef.current = [];
         recorder.ondataavailable = (e) => {
             if (e.data.size > 0) audioChunksRef.current.push(e.data);
         };
         recorder.onstop = () => {
             const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
             setSourceBlob(audioBlob);
             const url = URL.createObjectURL(audioBlob);
             setFileUrl(url);
             const now = new Date();
             const timestamp = `${now.getHours()}-${now.getMinutes()}-${now.getSeconds()}`;
             const generatedName = `Record_${timestamp}.webm`;
             const sizeStr = (audioBlob.size / 1e6).toFixed(2) + ' MB';
             const recordedDur = formatTime(recordingTime);
             const finalMeta = { name: generatedName, size: sizeStr, ext: 'webm', duration: recordedDur };
             setFileMeta(finalMeta);
             stream.getTracks().forEach(track => track.stop());
         };
         recorder.start();
         setIsRecording(true);
         setRecordingTime(0);
         recordingTimerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
         addToast(appLang === 'bn' ? "রেকর্ডিং শুরু হয়েছে..." : "Recording started...", 'info');
     } catch (err) {
         console.error("Failed to start recording", err);
         addToast(appLang === 'bn' ? "মাইক্রোফোন অ্যাক্সেস পাওয়া যায়নি" : "Microphone access denied", 'error');
     }
  };

  const handleStopRecording = () => {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
          mediaRecorderRef.current.stop();
          setIsRecording(false);
          if (recordingTimerRef.current) clearInterval(recordingTimerRef.current);
          addToast(appLang === 'bn' ? "রেকর্ডিং সম্পন্ন হয়েছে" : "Recording completed", 'success');
      }
  };

  useEffect(() => {
    if (!searchTerm || !transcript) {
      setMatchCount(0);
      return;
    }
    const matches = transcript.match(new RegExp(searchTerm, 'gi'));
    setMatchCount(matches ? matches.length : 0);
  }, [searchTerm, transcript]);

  const goToNextMatch = () => {
    if (matchCount === 0) return;
    const nextIdx = (currentMatchIndex + 1) % matchCount;
    setCurrentMatchIndex(nextIdx);
    const el = document.getElementById(`match-${nextIdx}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const goToPrevMatch = () => {
    if (matchCount === 0) return;
    const prevIdx = (currentMatchIndex - 1 + matchCount) % matchCount;
    setCurrentMatchIndex(prevIdx);
    const el = document.getElementById(`match-${prevIdx}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const handleScroll = () => {
    if (!scrollContainerRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
    const totalScrollable = scrollHeight - clientHeight;
    setScrollPercent(totalScrollable > 0 ? Math.round((scrollTop / totalScrollable) * 100) : 0);
    setShowScrollTop(scrollTop > 200);
    setShowScrollBottom(scrollHeight - scrollTop - clientHeight > 200);
  };

  const renderFormattedTranscript = useCallback((text: string) => {
    if (!text) return null;
    let localMatchIndex = 0;
    return text.split('\n').map((line, i) => {
      const parts = line.split(/(\*\*.*?\*\*)/g);
      return (
        <div key={i} className="mb-2 min-h-[1.5em] leading-relaxed">
           {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                  return <strong key={j} className={isDark ? 'text-indigo-400' : 'text-indigo-700'}>{part.slice(2, -2)}</strong>;
              }
              if (!searchTerm) return <span key={j}>{part}</span>;
              const escapedTerm = searchTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
              const regex = new RegExp(`(${escapedTerm})`, 'gi');
              const subParts = part.split(regex);
              return (
                <span key={j}>
                  {subParts.map((sub, k) => {
                    if (sub.toLowerCase() === searchTerm.toLowerCase()) {
                      const currentId = `match-${localMatchIndex}`;
                      const isCurrent = localMatchIndex === currentMatchIndex;
                      localMatchIndex++;
                      return (
                        <mark key={k} id={currentId} className={`${isCurrent ? 'bg-orange-500 text-white' : 'bg-yellow-400 text-black'} font-bold px-0.5 rounded transition-all duration-300`}>{sub}</mark>
                      );
                    }
                    return sub;
                  })}
                </span>
              );
           })}
        </div>
      );
    });
  }, [isDark, searchTerm, currentMatchIndex]);

  const filteredHistory = useMemo(() => {
    if (!history) return [];
    return history.filter(item => {
        const matchesSearch = !histSearch || (item.fileName?.toLowerCase() || '').includes(histSearch.toLowerCase()) || (item.transcript?.toLowerCase() || '').includes(histSearch.toLowerCase());
        const matchesDate = !histDateFilter || item.date.startsWith(histDateFilter);
        return matchesSearch && matchesDate;
    });
  }, [history, histSearch, histDateFilter]);

  return (
    <div className={`flex flex-col h-screen ${bgColor} ${textColor} overflow-hidden font-sans transition-all duration-500`}>
      <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[100] flex flex-col items-center gap-4 pointer-events-none w-full max-w-sm px-4">
        {toasts.map(toast => (
          <div key={toast.id} className={`pointer-events-auto flex items-center gap-4 px-8 py-5 rounded-[2.5rem] shadow-2xl border backdrop-blur-3xl animate-in slide-in-from-top-6 fade-in duration-500 w-full ${toast.type === 'success' ? 'bg-emerald-500/30 border-emerald-500/50 text-emerald-100' : toast.type === 'error' ? 'bg-rose-500/30 border-rose-500/50 text-rose-100' : toast.type === 'warning' ? 'bg-amber-500/30 border-amber-500/50 text-amber-100' : 'bg-indigo-500/30 border-indigo-500/50 text-indigo-100'}`}>
            <div className={`w-3 h-3 rounded-full animate-pulse shrink-0 ${toast.type === 'success' ? 'bg-emerald-400' : toast.type === 'error' ? 'bg-rose-400' : toast.type === 'warning' ? 'bg-amber-400' : 'bg-indigo-400'}`}></div>
            <span className="text-[13px] font-black uppercase tracking-[0.15em] font-stylish-bn flex-1 text-center leading-tight">{toast.message}</span>
            <button onClick={() => setToasts(prev => prev.filter(t => t.id !== toast.id))} className="ml-2 opacity-40 hover:opacity-100 p-1.5 hover:bg-white/10 rounded-full"><svg className="w-4.5 h-4.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M6 18L18 6M6 6l12 12" /></svg></button>
          </div>
        ))}
      </div>

      <Header 
        t={t} status={status} 
        isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen} 
        isInformationOpen={isInformationOpen} setIsInformationOpen={setIsInformationOpen}
        isActivityLogOpen={isActivityLogOpen} setIsActivityLogOpen={setIsActivityLogOpen}
        isDark={isDark} setTheme={setTheme} appLang={appLang} setAppLang={setAppLang} activeColors={activeColors} 
        setActiveTool={setActiveTool}
        setIsReportOpen={setIsReportOpen}
      />
      <main className={`flex-1 flex overflow-hidden relative ${sidebarSide === 'right' ? 'flex-row-reverse' : 'flex-row'}`}>
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className={`hidden md:flex fixed top-1/2 -translate-y-1/2 z-[45] w-7 h-20 ${activeColors.primary} text-white items-center justify-center shadow-2xl transition-all duration-700 ${sidebarSide === 'left' ? (isSidebarOpen ? 'left-[400px]' : 'left-0') : (isSidebarOpen ? 'right-[400px]' : 'right-0')} rounded-full hover:scale-110 active:scale-95 border border-white/20 hover:brightness-110`}><svg className={`w-5 h-5 transition-transform duration-700 ${sidebarSide === 'left' ? (isSidebarOpen ? 'rotate-180' : 'rotate-0') : (isSidebarOpen ? 'rotate-0' : 'rotate-180')}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3.5" d="M9 5l7 7-7 7" /></svg></button>
        <Sidebar 
          t={t} isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen} sidebarSide={sidebarSide} bgColor={bgColor} activeColors={activeColors} cardBg={cardBg} cardBorder={cardBorder} isDark={isDark} subTextColor={subTextColor} fileInputRef={fileInputRef} handleFileChange={handleFileChange} fileUrl={fileUrl} resetAll={resetAll} fileMeta={fileMeta} audioRef={audioRef} processTranscription={() => processTranscription()} status={status} history={history} setIsHistoryFullscreen={setIsHistoryFullscreen} 
          groupHistory={(items) => {
            const groups: any = {};
            items.forEach(item => {
              const date = new Date(item.date).toLocaleDateString(appLang === 'bn' ? 'bn-BD' : 'en-US', {
                year: 'numeric', month: 'long', day: 'numeric'
              });
              if (!groups[date]) groups[date] = [];
              groups[date].push(item);
            });
            return groups;
          }} 
          loadHistoryItem={(h) => { 
            setTranscript(h.transcript); 
            setStatus('completed'); 
            setIsSidebarOpen(false); 
            setActiveTranscriptSourceMeta({
                name: h.fileName,
                size: h.size,
                duration: h.duration
            });
            setActiveHistoryId(h.id);
            addToast(appLang === 'bn' ? "হিস্টোরি লোড হয়েছে" : "History loaded", 'info'); 
          }} 
          appLang={appLang} 
          isRecording={isRecording}
          recordingTime={recordingTime}
          onStartRecording={handleStartRecording}
          onStopRecording={handleStopRecording}
          activeHistoryId={activeHistoryId}
          onDeleteHistoryItem={deleteHistoryItem}
        />
        <div className="flex-1 flex flex-col relative overflow-hidden">
          <SpiderWebBackground opacity={isDark ? "opacity-[0.05]" : "opacity-[0.09]"} />
          <TranscriptOutput 
            t={t} status={status} isSearchExpanded={false} setIsSearchExpanded={() => {}} 
            transcriptSearchInputRef={transcriptSearchInputRef} searchTerm={searchTerm} 
            handleSearchChange={(e) => setSearchTerm(e.target.value)} activeColors={activeColors} 
            downloadText={() => {}} setStatus={setStatus} setTranscript={setTranscript} 
            mainBgColor={mainBgColor} fileUrl={fileUrl} textColor={textColor} isDark={isDark} 
            setIsSidebarOpen={setIsSidebarOpen} fileMeta={fileMeta} processTranscription={() => processTranscription()} 
            scrollContainerRef={scrollContainerRef} handleScroll={handleScroll} transcriptCardBg={transcriptCardBg} 
            cardBorder={cardBorder} renderFormattedTranscript={renderFormattedTranscript} transcript={transcript} 
            showScrollTop={showScrollTop} scrollToTop={() => scrollContainerRef.current?.scrollTo({top:0, behavior:'smooth'})} 
            showScrollBottom={showScrollBottom} scrollToBottom={() => scrollContainerRef.current?.scrollTo({top:scrollContainerRef.current.scrollHeight, behavior:'smooth'})}
            fontSize={fontSize} setFontSize={setFontSize} matchCount={matchCount} currentMatchIndex={currentMatchIndex}
            goToNextMatch={goToNextMatch} goToPrevMatch={goToPrevMatch} errorMessage={error}
            transformTranscript={transformTranscript} transformingType={transformingType} scrollPercent={scrollPercent}
            addToast={addToast} appLang={appLang} history={history} onSeek={handleSeek} onModelUpdate={updateApiKeyInfo} setIsAiLoading={setIsAiLoading}
            audioCurrentTime={audioCurrentTime}
            activeTranscriptSourceMeta={activeTranscriptSourceMeta}
            progress={progress} currentStage={currentStage} elapsedSeconds={seconds} estimatedSeconds={estimatedSeconds}
            setActiveHistoryId={setActiveHistoryId}
          />
        </div>
      </main>
      {isHistoryFullscreen && <ExpandedHistory t={t} isDark={isDark} setIsHistoryFullscreen={setIsHistoryFullscreen} histSearch={histSearch} setHistSearch={setHistSearch} histDateFilter={histDateFilter} setHistDateFilter={setHistDateFilter} filteredHistory={filteredHistory} loadHistoryItem={(h) => { 
          setTranscript(h.transcript); 
          setStatus('completed'); 
          setIsHistoryFullscreen(false); 
          setActiveTranscriptSourceMeta({
              name: h.fileName,
              size: h.size,
              duration: h.duration
          });
          setActiveHistoryId(h.id);
          addToast(appLang === 'bn' ? "হিস্টোরি লোড হয়েছে" : "History loaded", 'info'); 
      }} activeColors={activeColors} />}
      {showCompletionModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-300"><div className="bg-slate-900 border border-white/10 rounded-[2.5rem] p-10 max-w-sm w-full shadow-2xl text-center animate-in zoom-in-95 duration-500"><div className="w-24 h-24 bg-green-500/20 text-green-400 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-inner ring-1 ring-green-400/20"><svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg></div><h2 className="text-2xl font-black text-white uppercase tracking-tight mb-4 font-stylish-bn">{t.completionTitle}</h2><div className="bg-white/5 rounded-2xl p-6 mb-8 border border-white/5"><p className="text-[10px] font-black text-white/40 uppercase tracking-widest mb-2">{t.timeTakenLabel}</p><p className="text-3xl font-black text-white tabular-nums">{finalTimeDisplay}</p></div><button onClick={() => setShowCompletionModal(false)} className={`w-full py-4 ${activeColors.primary} text-white rounded-2xl text-xs font-black uppercase tracking-[0.2em] shadow-2xl hover:brightness-110 active:scale-95 transition-all`}>{t.okBtn}</button></div></div>
      )}
      <Footer 
        t={t} 
        activeColors={activeColors} 
        activeApiKeySource={activeApiKeySource} 
        activeModelName={activeModelName} 
        totalApiCalls={totalApiCalls} 
        isAiLoading={isAiLoading}
        onKeyUpdate={updateApiKeyInfo}
        appLang={appLang}
        isDark={isDark}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <InformationModal 
        isOpen={isInformationOpen} 
        onClose={() => setIsInformationOpen(false)} 
        isDark={isDark} 
        activeColors={activeColors} 
        appLang={appLang} 
      />
      <ActivityLogsModal
        isOpen={isActivityLogOpen}
        onClose={() => setIsActivityLogOpen(false)} 
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
      />
      <TranscriberReportModal 
        isOpen={isReportOpen}
        onClose={() => setIsReportOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
      />

      <ToolsModal 
        activeTool={activeTool}
        onClose={() => setActiveTool(null)}
        isMinimized={isToolsMinimized}
        setIsMinimized={setIsToolsMinimized}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
        addToast={addToast}
        onFileSelect={(file) => handleFileChange({target: {files: [file]}}, true)}
      />

      <ShortcutModal 
        isOpen={isShortcutHelpOpen}
        onClose={() => setIsShortcutHelpOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
      />

      <SettingsModal
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
        addToast={addToast}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { getAllFromStore, STORES } from '../../services/db';

declare var html2pdf: any;

interface TranscriberReportModalProps {
  isOpen: boolean;
  onClose: () => void;
  isDark: boolean;
  activeColors: any;
  appLang: 'bn' | 'en';
}

interface ReportRow {
  date: string;
  method: string;
  fileType: string;
  qty: number;
  durationSecs: number;
}

export const TranscriberReportModal: React.FC<TranscriberReportModalProps> = ({ 
  isOpen, onClose, isDark, activeColors, appLang 
}) => {
  const [history, setHistory] = useState<any[]>([]);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [reportData, setReportData] = useState<ReportRow[]>([]);

  // Initialize dates to current month
  useEffect(() => {
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    setFromDate(firstDay.toISOString().split('T')[0]);
    setToDate(lastDay.toISOString().split('T')[0]);
  }, []);

  useEffect(() => {
    if (isOpen) {
      loadHistory();
    }
  }, [isOpen]);

  const loadHistory = async () => {
    const data = await getAllFromStore(STORES.HISTORY);
    setHistory(data);
  };

  // Helper to convert time string (HH:MM:SS or MM:SS) to seconds
  const parseDurationToSeconds = (dur: string) => {
    if (!dur) return 0;
    const parts = dur.split(':').map(Number);
    if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
    if (parts.length === 2) return parts[0] * 60 + parts[1];
    return 0;
  };

  // Helper to format seconds to "XX Hrs YY Min"
  const formatSecondsToHrsMin = (totalSecs: number) => {
    const hrs = Math.floor(totalSecs / 3600);
    const mins = Math.floor((totalSecs % 3600) / 60);
    return `${hrs.toString().padStart(2, '0')} Hrs ${mins.toString().padStart(2, '0')} Min`;
  };

  // Process Data based on filters
  useEffect(() => {
    if (!history.length) return;

    const start = new Date(fromDate);
    start.setHours(0, 0, 0, 0);
    const end = new Date(toDate);
    end.setHours(23, 59, 59, 999);

    const filtered = history.filter(item => {
      const itemDate = new Date(item.date);
      return itemDate >= start && itemDate <= end;
    });

    // Group by Date + Type
    const grouped: Record<string, ReportRow> = {};

    filtered.forEach(item => {
      const dateKey = new Date(item.date).toLocaleDateString('en-GB'); // DD/MM/YYYY
      const isVideo = ['mp4', 'mkv', 'webm', 'avi', 'mov'].includes((item.extension || '').toLowerCase());
      const fileType = isVideo ? 'Video' : 'Audio';
      // Simple heuristic for method - usually File Upload unless we track source explicitly
      const method = item.fileName.includes('http') ? 'Youtube Link' : 'File Upload'; 

      const key = `${dateKey}-${fileType}`;

      if (!grouped[key]) {
        grouped[key] = {
          date: dateKey,
          method: method,
          fileType: fileType,
          qty: 0,
          durationSecs: 0
        };
      }

      grouped[key].qty += 1;
      grouped[key].durationSecs += parseDurationToSeconds(item.duration);
    });

    // Convert to array and sort by date
    const rows = Object.values(grouped).sort((a, b) => {
        const dateA = a.date.split('/').reverse().join('-');
        const dateB = b.date.split('/').reverse().join('-');
        return dateA.localeCompare(dateB);
    });

    setReportData(rows);

  }, [history, fromDate, toDate]);

  const totalQty = reportData.reduce((acc, curr) => acc + curr.qty, 0);
  const totalDurationSecs = reportData.reduce((acc, curr) => acc + curr.durationSecs, 0);

  const handleDownloadPDF = () => {
    const element = document.getElementById('report-content');
    const opt = {
      margin: 0.5,
      filename: `Transcriber_Report_${fromDate}_to_${toDate}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2 },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };
    html2pdf().from(element).set(opt).save();
  };

  const handleDownloadExcel = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "Sl No,Transcriber Date,Using Method,File Type,Qty,Duration,Remarks\n";

    reportData.forEach((row, index) => {
        const dur = formatSecondsToHrsMin(row.durationSecs);
        csvContent += `${index + 1},${row.date},${row.method},${row.fileType},${row.qty},${dur},\n`;
    });

    csvContent += `,,,Total-,${totalQty},${formatSecondsToHrsMin(totalDurationSecs)},\n`;

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Report_${fromDate}_to_${toDate}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm animate-in fade-in duration-200">
      <div className={`w-full max-w-4xl h-[90vh] rounded-3xl flex flex-col overflow-hidden shadow-2xl ${isDark ? 'bg-slate-900 border border-white/10' : 'bg-white'}`}>

        {/* Header Controls */}
        <div className="p-6 border-b border-gray-200 dark:border-white/10 flex flex-wrap gap-4 items-center justify-between bg-slate-100 dark:bg-black/20">
            <div className="flex items-center gap-4">
                <div className="flex flex-col">
                    <label className="text-[10px] font-bold uppercase opacity-50 mb-1">From Date</label>
                    <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} className="px-3 py-2 rounded-lg border text-sm font-bold bg-white dark:bg-white/5 dark:border-white/10 dark:text-white" />
                </div>
                <div className="flex flex-col">
                    <label className="text-[10px] font-bold uppercase opacity-50 mb-1">To Date</label>
                    <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} className="px-3 py-2 rounded-lg border text-sm font-bold bg-white dark:bg-white/5 dark:border-white/10 dark:text-white" />
                </div>
            </div>

            <div className="flex items-center gap-3">
                <button onClick={handleDownloadExcel} className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-xs font-bold uppercase tracking-wider transition-all">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                    Excel
                </button>
                <button onClick={handleDownloadPDF} className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-bold uppercase tracking-wider transition-all">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                    PDF
                </button>
                <button onClick={onClose} className="p-2 hover:bg-black/10 dark:hover:bg-white/10 rounded-full transition-all">
                    <svg className="w-6 h-6 text-gray-500 dark:text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg>
                </button>
            </div>
        </div>

        {/* Report Preview Area (Paper Look) */}
        <div className="flex-1 overflow-y-auto bg-gray-500/10 p-8 flex justify-center">
            <div id="report-content" className="w-[210mm] min-h-[297mm] bg-white text-black p-10 shadow-lg box-border">

                {/* Report Header */}
                <div className="text-center mb-6">
                    <h1 className="text-xl font-bold text-black mb-1">Transcriber Report- {new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</h1>
                    <h2 className="text-lg font-bold text-black mb-2">BGB LICELL</h2>
                    <div className="flex justify-center gap-8 text-sm font-bold text-red-600">
                        <span>From Date: {new Date(fromDate).toLocaleDateString('en-GB')}</span>
                        <span>To Date: {new Date(toDate).toLocaleDateString('en-GB')}</span>
                    </div>
                    <div className="text-right mt-4 text-xs">
                        Print Date: {new Date().toLocaleDateString('en-GB')}
                    </div>
                </div>

                {/* Data Table */}
                <table className="w-full border-collapse border border-black text-sm">
                    <thead>
                        <tr className="bg-gray-200">
                            <th className="border border-black px-2 py-1 w-12">Sl No</th>
                            <th className="border border-black px-2 py-1">Transcriber Date</th>
                            <th className="border border-black px-2 py-1">Using Method</th>
                            <th className="border border-black px-2 py-1">File Type</th>
                            <th className="border border-black px-2 py-1 w-16">Qty</th>
                            <th className="border border-black px-2 py-1">Duration</th>
                            <th className="border border-black px-2 py-1">Rmks</th>
                        </tr>
                        {/* Sub-header description row as per image */}
                        <tr className="italic text-[10px]">
                            <td className="border border-black px-1 text-center">Serial No</td>
                            <td className="border border-black px-1 text-center">{`{Transcriber date}`}</td>
                            <td className="border border-black px-1">{`{File Upload, Recording, Youtube...}`}</td>
                            <td className="border border-black px-1">{`{Audio or Video}`}</td>
                            <td className="border border-black px-1">{`{Count}`}</td>
                            <td className="border border-black px-1">{`{Total Duration} Min`}</td>
                            <td className="border border-black px-1"></td>
                        </tr>
                    </thead>
                    <tbody>
                        {reportData.map((row, index) => (
                            <tr key={index} className="text-center">
                                <td className="border border-black px-2 py-1">{index + 1}.</td>
                                <td className="border border-black px-2 py-1">{row.date}</td>
                                <td className="border border-black px-2 py-1">{row.method}</td>
                                <td className="border border-black px-2 py-1">{row.fileType}</td>
                                <td className="border border-black px-2 py-1">{row.qty}</td>
                                <td className="border border-black px-2 py-1">{formatSecondsToHrsMin(row.durationSecs)}</td>
                                <td className="border border-black px-2 py-1"></td>
                            </tr>
                        ))}

                        {/* Empty rows filler if needed, or just standard look */}
                        {reportData.length === 0 && (
                            <tr>
                                <td colSpan={7} className="border border-black py-10 text-center italic text-gray-500">No records found for this date range</td>
                            </tr>
                        )}

                        {/* Footer Total */}
                        <tr className="font-bold">
                            <td colSpan={4} className="border border-black px-2 py-1 text-right">Total-</td>
                            <td className="border border-black px-2 py-1 text-center">{totalQty}</td>
                            <td className="border border-black px-2 py-1 text-center">{formatSecondsToHrsMin(totalDurationSecs)}</td>
                            <td className="border border-black px-2 py-1"></td>
                        </tr>
                    </tbody>
                </table>

                {/* Page Footer */}
                <div className="mt-20 text-right text-sm font-medium">
                    Footer: System Generated by OSINT
                </div>

            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
    getAllApiKeys, 
    addUserApiKey, 
    deleteApiKey, 
    setActiveApiKey, 
    getActiveKeyId, 
    UserApiKey 
} from './services/ApiKeyManager';
import { syncAllLocalToCloud, restoreAllCloudToLocal, checkCloudConnection } from './services/api';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  isDark: boolean;
  activeColors: any;
  appLang: 'bn' | 'en';
  addToast: (m: string, t: any) => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, isDark, activeColors, appLang, addToast }) => {
  const [activeTab, setActiveTab] = useState<'keys' | 'sync'>('keys');

  // API Key Management State
  const [keyList, setKeyList] = useState<UserApiKey[]>([]);
  const [activeKeyId, setActiveKeyId] = useState<string | null>(null);
  const [newKeyInput, setNewKeyInput] = useState('');
  const [newKeyLabel, setNewKeyLabel] = useState('');
  const [isAddingKey, setIsAddingKey] = useState(false);

  // Sync State
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncProgress, setSyncProgress] = useState(0);
  const [syncStatus, setSyncStatus] = useState('Idle');
  const [syncMode, setSyncMode] = useState<'up' | 'down'>('up');
  const [cloudConnection, setCloudConnection] = useState<string>('Checking...');

  // Window State
  const [isMinimized, setIsMinimized] = useState(false);
  const [isMaximized, setIsMaximized] = useState(false);
  const [size, setSize] = useState({ width: 700, height: 600 });
  const isResizing = useRef(false);

  const refreshKeys = async () => {
      const keys = await getAllApiKeys();
      setKeyList(keys);
      setActiveKeyId(getActiveKeyId());
  };

  useEffect(() => {
    if (isOpen) {
        refreshKeys();
        setIsMinimized(false); 
        checkCloudConnection().then(res => setCloudConnection(res.status === 'online' ? 'Online & Authenticated' : res.message));
    }
  }, [isOpen, activeTab]);

  const handleAddKey = async () => {
      if (!newKeyInput.trim()) {
          addToast(appLang === 'bn' ? 'দয়া করে এপিআই কি দিন' : 'Please enter API Key', 'error');
          return;
      }
      setIsAddingKey(true);
      try {
          await addUserApiKey(newKeyInput, newKeyLabel || `Key ${keyList.length + 1}`);
          setNewKeyInput('');
          setNewKeyLabel('');
          await refreshKeys();
          addToast(appLang === 'bn' ? 'কি যুক্ত করা হয়েছে' : 'Key added successfully', 'success');
      } catch (e) {
          console.error(e);
          addToast('Failed to add key', 'error');
      } finally {
          setIsAddingKey(false);
      }
  };

  const handleSelectKey = (id: string) => {
      setActiveApiKey(id);
      setActiveKeyId(id);
      addToast(appLang === 'bn' ? 'এপিআই কি সিলেক্ট করা হয়েছে' : 'API Key Selected', 'success');
  };

  const handleDeleteKey = async (id: string) => {
      if (confirm(appLang === 'bn' ? 'আপনি কি নিশ্চিত?' : 'Are you sure?')) {
          await deleteApiKey(id);
          await refreshKeys();
          addToast(appLang === 'bn' ? 'কি ডিলিট করা হয়েছে' : 'Key deleted', 'warning');
      }
  };

  // Sync Logic
  const handleStartSync = async (mode: 'up' | 'down') => {
      if (isSyncing) return;
      setIsSyncing(true);
      setSyncMode(mode);
      setSyncStatus(mode === 'up' ? 'Starting Upload...' : 'Starting Download...');

      try {
          if (mode === 'up') {
              await syncAllLocalToCloud((msg, pct) => {
                  setSyncStatus(msg);
                  setSyncProgress(pct);
              });
              addToast(appLang === 'bn' ? 'ডাটা আপলোড সম্পন্ন হয়েছে' : 'Data Upload Complete', 'success');
          } else {
              await restoreAllCloudToLocal((msg, pct) => {
                  setSyncStatus(msg);
                  setSyncProgress(pct);
              });
              addToast(appLang === 'bn' ? 'ডাটা রিস্টোর সম্পন্ন হয়েছে' : 'Data Restore Complete', 'success');
          }
      } catch (e: any) {
          setSyncStatus('Failed: ' + e.message);
          addToast(appLang === 'bn' ? 'অপারেশন ব্যর্থ হয়েছে' : 'Operation Failed', 'error');
      } finally {
          setIsSyncing(false);
      }
  };

  // --- Resizing Logic ---
  const startResizing = (e: React.MouseEvent) => {
    e.preventDefault();
    isResizing.current = true;
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', stopResizing);
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (!isResizing.current) return;
    const modalElement = document.getElementById('settings-modal-container');
    if (modalElement) {
      const rect = modalElement.getBoundingClientRect();
      setSize({
        width: Math.max(400, e.clientX - rect.left),
        height: Math.max(400, e.clientY - rect.top)
      });
    }
  };

  const stopResizing = () => {
    isResizing.current = false;
    window.removeEventListener('mousemove', handleMouseMove);
    window.removeEventListener('mouseup', stopResizing);
  };

  if (!isOpen) return null;

  return (
    <>
      {/* Minimized Floating Widget */}
      <div className={`fixed bottom-24 right-20 z-[120] animate-in slide-in-from-bottom-10 fade-in duration-300 ${isMinimized ? 'block' : 'hidden'}`}>
         <div 
           onClick={() => setIsMinimized(false)}
