  const refreshHistory = async () => {
    try {
      const data = await getAllFromStore(STORES.HISTORY);
      if (data && Array.isArray(data)) {
         data.sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime());
         setHistory(data);
      }
    } catch (err) {
      console.error("DB Refresh Error:", err);
    }
  };

  useEffect(() => {
    const startApp = async () => {
      try {
        await initDB();
        await refreshHistory();
        const total = await getTotalCalls();
        setTotalApiCalls(total);
        updateApiKeyInfo();
      } catch (e) {
        addToast(appLang === 'bn' ? "সিস্টেম লোড ব্যর্থ হয়েছে।" : "System loading failed.", 'error');
      }
    };
    startApp();
  }, [appLang, addToast, updateApiKeyInfo]);

  const saveHistory = async (item: HistoryItem) => {
    try {
      await addToStore(STORES.HISTORY, item);
      await refreshHistory(); 
    } catch (err) {
      console.error("Save Error:", err);
      addToast(appLang === 'bn' ? "হিস্টোরি সেভ করা যায়নি।" : "Failed to save history.", 'error');
