// Using 127.0.0.1 is more reliable on Windows XAMPP than localhost due to IPv6 issues
export const DEFAULT_API_URL = 'http://127.0.0.1/licell_api';

export const getApiBaseUrl = () => {
  return localStorage.getItem('api_base_url') || DEFAULT_API_URL;
};

export const setApiBaseUrl = (url: string) => {
  const cleanUrl = url.replace(/\/$/, '');
  localStorage.setItem('api_base_url', cleanUrl);
};

export const getApiUrl = (endpoint: string) => {
  const base = getApiBaseUrl();
  return `${base}/${endpoint}`;
};

/**
 * CHECK FIREBASE CONNECTION STATUS
 * Diagnostic tool to help user understand why sync might be failing.
 */
export const checkCloudConnection = async (): Promise<{ status: 'online' | 'offline' | 'auth-error', message: string }> => {
    try {
        await auth.authStateReady();
        if (!auth.currentUser) {
            return { status: 'auth-error', message: 'Auth Disabled' };
        }
        // If we are here, at least we reached Firebase servers and Auth is working
        return { status: 'online', message: 'Connected' };
    } catch (e: any) {
        return { status: 'offline', message: e.code || 'Unreachable' };
    }
};

/**
 * FORCE SYNC LOCAL -> CLOUD
 * Reads all data from XAMPP and pushes missing/updated items to Firestore.
 */
export const syncAllLocalToCloud = async (onProgress: (msg: string, pct: number) => void) => {
    try {
        await auth.authStateReady();
        if (!auth.currentUser) throw new Error("Firebase Auth not ready");

        const stores = FIREBASE_SYNCED_STORES;
        const totalStores = stores.length;

        for (let i = 0; i < totalStores; i++) {
            const store = stores[i];
            const displayStoreName = store.replace('studio_', '').toUpperCase();
            onProgress(`Uploading ${displayStoreName}...`, (i / totalStores) * 100);

            // 1. Get Local Data
            const localUrl = getApiUrl(`api.php?action=get&store=${store}`);
            const res = await fetch(localUrl);

            if (!res.ok) {
                console.warn(`Skipping ${store}: Local API error`);
                continue;
            }

            const localData = await res.json();
            if (!Array.isArray(localData) || localData.length === 0) {
                continue;
            }

            // 2. Batch write to Firestore
            // Firestore limits batches to 500 operations. We use 400 to be safe.
            const batchSize = 400; 
            const chunks = [];
            for (let k = 0; k < localData.length; k += batchSize) {
                chunks.push(localData.slice(k, k + batchSize));
            }

            let chunkIdx = 0;
            for (const chunk of chunks) {
                const batch = writeBatch(db);
                chunk.forEach((item: any) => {
                    // Ensure ID is string
                    const docId = String(item.id);
                    const docRef = doc(db, store, docId);
                    batch.set(docRef, item, { merge: true }); // Merge prevents overwriting fields if they exist
                });

                await batch.commit();
                chunkIdx++;
                // Update progress slightly for chunks
                const subProgress = ((i / totalStores) * 100) + ((chunkIdx / chunks.length) * (100 / totalStores));
                onProgress(`Uploading ${displayStoreName} (${chunkIdx}/${chunks.length})...`, subProgress);
            }
        }
        onProgress("Sync Complete", 100);
        return true;
    } catch (e: any) {
        console.error("Sync Failed:", e);
        throw e;
    }
};

/**
 * FORCE RESTORE CLOUD -> LOCAL
 * Reads all data from Firebase and saves to XAMPP.
 */
export const restoreAllCloudToLocal = async (onProgress: (msg: string, pct: number) => void) => {
    try {
        await auth.authStateReady();
        if (!auth.currentUser) throw new Error("Firebase Auth not ready");

        const stores = FIREBASE_SYNCED_STORES;
        const totalStores = stores.length;

        for (let i = 0; i < totalStores; i++) {
            const store = stores[i];
            const displayStoreName = store.replace('studio_', '').toUpperCase();
            onProgress(`Downloading ${displayStoreName}...`, (i / totalStores) * 100);

            // 1. Get Cloud Data
            const querySnapshot = await getDocs(collection(db, store));
            const cloudData = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

            if (cloudData.length === 0) continue;

            // 2. Save to Local XAMPP one by one (Parallel requests)
            const savePromises = cloudData.map(async (item: any) => {
                try {
                    const url = getApiUrl(`api.php?action=save&store=${store}`);
                    await fetch(url, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(item)
                    });
                } catch (e) {
                    console.error(`Failed to save item ${item.id} locally`, e);
                }
            });

            // Wait for all saves in this store to complete
            await Promise.all(savePromises);
        }

        onProgress("Restore Complete", 100);
        return true;
    } catch (e: any) {
        console.error("Restore Failed:", e);
        throw e;
    }
};

/**
 * FETCH STRATEGY (MERGED):
 * 1. Fetch from Local Server (XAMPP).
 * 2. Fetch from Firebase (if synced store).
 * 3. Merge results and remove duplicates by ID.
 * This ensures that if data exists in Cloud but not Locally (e.g. fresh install), it still shows up.
 */
export const fetchDataDual = async (storeName: string) => {
  const promises = [];

  // 1. Local Fetch Promise
  const localFetch = new Promise<any[]>(async (resolve) => {
    try {
      const url = getApiUrl(`api.php?action=get&store=${storeName}`);
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000); // 3s timeout

      const response = await fetch(url, { signal: controller.signal });
      clearTimeout(timeoutId);

      if (response.ok) {
        const data = await response.json();
        if (Array.isArray(data)) {
          resolve(data);
          return;
        }
      }
      resolve([]);
    } catch (e) {
      // console.warn("Local fetch failed or timed out", e);
      resolve([]);
    }
  });
  promises.push(localFetch);

  // 2. Firebase Fetch Promise (Only if synced store)
  if (FIREBASE_SYNCED_STORES.includes(storeName)) {
    const firebaseFetch = new Promise<any[]>(async (resolve) => {
      try {
        await auth.authStateReady(); // Wait for auth
        const querySnapshot = await getDocs(collection(db, storeName));
        const cloudData = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        resolve(cloudData);
      } catch (e) {
        // console.warn("Firebase fetch failed", e);
        resolve([]);
      }
    });
    promises.push(firebaseFetch);
  }

  // 3. Execute Both and Merge
  const results = await Promise.all(promises);

  // Flatten arrays: [ [localData], [cloudData] ] -> [ ...localData, ...cloudData ]
  const allData = results.flat();

  // Deduplicate by ID
  const uniqueDataMap = new Map();
  allData.forEach(item => {
    if (item && item.id) {
      uniqueDataMap.set(item.id, item);
    }
  });

  return Array.from(uniqueDataMap.values());
};

/**
 * SAVE STRATEGY:
 * 1. Save to XAMPP (Local Server).
 * 2. IF store is in FIREBASE_SYNCED_STORES, ALSO save to Firebase.
 */
export const saveDataDual = async (storeName: string, data: any) => {
  const id = data.id || Date.now().toString();
  const payload = { ...data, id }; // Ensure ID exists

  const promises = [];

  // 1. Local Save (Always)
  const localSave = new Promise(async (resolve, reject) => {
    try {
      const url = getApiUrl(`api.php?action=save&store=${storeName}`);
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
          throw new Error("Local server returned error");
      }

      const result = await response.json();
      if (result.error) reject(result.error);
      else resolve("Local Success");
    } catch (e) {
      // console.warn(`[Save] Local save failed for ${storeName}`, e);
      resolve("Local Failed"); // Resolve so Promise.all doesn't fail globally
    }
  });
  promises.push(localSave);

  // 2. Firebase Save (Conditional)
  if (FIREBASE_SYNCED_STORES.includes(storeName)) {
      const firebaseSave = new Promise(async (resolve, reject) => {
        try {
          await auth.authStateReady(); // Wait for auth
          await setDoc(doc(db, storeName, id), payload);
          resolve("Cloud Success");
        } catch (e: any) {
          if (e.code === 'permission-denied') {
             console.error("Firebase Permission Denied: Check Firestore Rules");
             resolve("Cloud Permission Denied");
          } else {
             console.error(`[Save] Firebase save failed for ${storeName}`, e);
             resolve("Cloud Failed");
          }
        }
      });
      promises.push(firebaseSave);
  }

  await Promise.all(promises);
  return true;
};

/**
 * DELETE STRATEGY:
 * 1. Delete from XAMPP.
 * 2. IF store is in FIREBASE_SYNCED_STORES, ALSO delete from Firebase.
 */
export const deleteDataDual = async (storeName: string, id: string) => {
  const promises = [];

  // 1. Local Delete
  const localDelete = new Promise(async (resolve) => {
    try {
      const url = getApiUrl(`api.php?action=delete&store=${storeName}&id=${id}`);
      await fetch(url);
      resolve("Local Deleted");
    } catch (e) {
      // console.warn(`[Delete] Local delete failed`, e);
      resolve("Local Fail");
    }
  });
  promises.push(localDelete);

  // 2. Firebase Delete (Conditional)
  if (FIREBASE_SYNCED_STORES.includes(storeName)) {
      const firebaseDelete = new Promise(async (resolve) => {
        try {
          await auth.authStateReady(); // Wait for auth
          await deleteDoc(doc(db, storeName, id));
          resolve("Cloud Deleted");
        } catch (e: any) {
           if (e.code === 'permission-denied') {
             resolve("Cloud Permission Denied");
           } else {
             console.warn(`[Delete] Cloud delete failed`, e);
             resolve("Cloud Fail");
           }
        }
      });
      promises.push(firebaseDelete);
  }

  await Promise.all(promises);
  return true;
};

// Helper for fetching single config document (like API Key)
export const fetchConfigDual = async (docName: string) => {
    // 1. Try PHP
    try {
        const url = getApiUrl(`${docName}.php`);
        const res = await fetch(url);
        if (res.ok) {
            return await res.json();
        }
    } catch (e) { /* Ignore */ }

    // 2. Fallback to Firebase
    try {
        await auth.authStateReady(); // Wait for auth
        const docRef = doc(db, "config", docName);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            return docSnap.data();
        }
    } catch (e: any) {
        if (e.code !== 'permission-denied') {
            console.error("Config fetch failed", e);
        }
    }
    return null;
};

import { fetchDataDual, saveDataDual, deleteDataDual } from './api.ts';

export const DB_NAME = 'LiCellStudioDB_v5_Final'; 
export const DB_VERSION = 1;

// These keys MUST match the SQL Table names exactly
export const STORES = {
  HISTORY: 'studio_history',
  REPORTS: 'studio_reports',
  SEARCH_ANALYSIS: 'studio_analysis',
  API_KEYS: 'user_api_keys',
  MASTER_KEYS: 'system_master_keys', // Matches SQL table
  SYSTEM_ACTIVITY_LOGS: 'activity_logs',
  API_CALL_LOGS: 'gemini_call_logs',
  STATS: 'global_stats',
  CHAT_HISTORY: 'assistant_chat_history'
};

// List of stores that should SYNC to Cloud/Server
export const FIREBASE_SYNCED_STORES = [
  STORES.HISTORY,
  STORES.REPORTS,
  STORES.SEARCH_ANALYSIS,
  STORES.API_KEYS,
  STORES.MASTER_KEYS, // Sync Master keys if needed securely
  STORES.STATS,
  STORES.API_CALL_LOGS,
  STORES.SYSTEM_ACTIVITY_LOGS,
  STORES.CHAT_HISTORY
];

const ALL_STORES = Object.values(STORES);

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => {
        console.error("DB Open Error:", request.error);
        reject(request.error);
    };

    request.onsuccess = () => {
        resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;

      ALL_STORES.forEach(store => {
        if (!db.objectStoreNames.contains(store)) {
          db.createObjectStore(store, { keyPath: 'id' });
        }
      });
    };
  });
};

// --- UNIFIED DB FUNCTIONS ---

export const addToStore = async (storeName: string, data: any) => {
  // If saving API Keys, map 'key' property to 'key_value' for SQL compatibility if needed
  // But usually we handle this in the API layer. Keeping it simple here.
  return saveDataDual(storeName, data);
};

export const getFromStore = async (storeName: string, id: string): Promise<any | undefined> => {
  const all = await fetchDataDual(storeName);
  return all.find((item: any) => item.id === id);
};

export const getAllFromStore = async (storeName: string): Promise<any[]> => {
  return fetchDataDual(storeName);
};

export const deleteFromStore = async (storeName: string, id: string) => {
  return deleteDataDual(storeName, id);
};

export const clearStore = async (storeName: string) => {
    // Local clear only
    const db = await initDB();
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.clear();
        request.onsuccess = () => resolve(true);
        request.onerror = () => reject(request.error);
    });
};

