import { GoogleGenAI } from "@google/genai";
import { getApiUrl } from './api';
import { getAllFromStore, addToStore, deleteFromStore, STORES } from './db';

const ACTIVE_KEY_ID_STORAGE = 'manual_active_key_id';
const DEFAULT_MODEL = 'gemini-3-flash-preview';

// Define the Key Structure
export interface UserApiKey {
  id: string;
  key: string;
  label: string;
  addedAt: string;
}

export interface ApiCallLog {
  id: string;
  timestamp: string;
  source: string;
  model: string;
  status: 'success' | 'error';
  latency?: number;
}

// 1. Get the currently selected provider
export const getActiveProvider = async (): Promise<{ key: string, model: string, source: string } | null> => {
  // 1. Try manual selection from local storage first
  const activeId = localStorage.getItem(ACTIVE_KEY_ID_STORAGE);

  if (activeId) {
    try {
      // Fetch all keys from DB
      const allKeys = await getAllFromStore(STORES.API_KEYS);
      const selectedKey = allKeys.find((k: any) => k.id === activeId);

      if (selectedKey) {
        return {
          key: selectedKey.key,
          model: DEFAULT_MODEL, 
          source: selectedKey.label || 'Manual Selection'
        };
      }
    } catch (e) {
      console.error("Error fetching active key:", e);
    }
  }

  // 2. Try Vite Environment Variable
  const env = (import.meta as any).env;
  const envKey = env ? env.VITE_API_KEY_1 : undefined;

  if (envKey && typeof envKey === 'string' && envKey.trim() !== '') {
    return {
      key: envKey.trim(),
      model: DEFAULT_MODEL,
      source: 'Environment (.env)'
    };
  }

  // 3. Fallback for legacy process.env
  if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
     return {
      key: process.env.API_KEY.trim(),
      model: DEFAULT_MODEL,
      source: 'Environment (Process)'
    };
  }

  // 4. Fallback: Check Database for Master Key (Requires XAMPP)
  try {
      const response = await fetch(getApiUrl('get_api_key.php'));
      if (response.ok) {
          const data = await response.json();
          if (data && data.key) {
              return {
                  key: data.key,
                  model: DEFAULT_MODEL,
                  source: 'Server Master Key'
              };
          }
      }
  } catch (e) {
      // Ignore server error, fallback to null
  }

  return null;
};

// 2. Add a new Key
export const addUserApiKey = async (key: string, label: string) => {
  const newKey: UserApiKey = {
    id: Date.now().toString(),
    key: key.trim(),
    label: label.trim() || `Key ${new Date().toLocaleTimeString()}`,
    addedAt: new Date().toISOString()
  };

  await addToStore(STORES.API_KEYS, newKey);

  // If it's the first key, auto-select it for convenience (optional, but good UX)
  const allKeys = await getAllFromStore(STORES.API_KEYS);
  if (allKeys.length === 1) {
      localStorage.setItem(ACTIVE_KEY_ID_STORAGE, newKey.id);
  }

  return newKey;
};

// 3. Get All Keys
export const getAllApiKeys = async (): Promise<UserApiKey[]> => {
  const keys = await getAllFromStore(STORES.API_KEYS);
  return keys.sort((a: any, b: any) => new Date(b.addedAt).getTime() - new Date(a.addedAt).getTime());
};

// 4. Set Active Key
export const setActiveApiKey = (id: string) => {
  localStorage.setItem(ACTIVE_KEY_ID_STORAGE, id);
};

// 5. Delete Key
export const deleteApiKey = async (id: string) => {
  await deleteFromStore(STORES.API_KEYS, id);
  // If active key is deleted, clear selection
  if (localStorage.getItem(ACTIVE_KEY_ID_STORAGE) === id) {
    localStorage.removeItem(ACTIVE_KEY_ID_STORAGE);
  }
};

// 6. Get Active Key ID (Synchronous for UI check)
export const getActiveKeyId = () => {
  return localStorage.getItem(ACTIVE_KEY_ID_STORAGE);
};

// Sync with Server DB (global_stats table)
export const incrementTotalCalls = async (source?: string, model?: string, keySource?: string) => {
  // Optimistic update for UI
  let count = parseInt(localStorage.getItem('simple_api_count') || '0');
  count++;
  localStorage.setItem('simple_api_count', count.toString());

  // Sync with Server
  try {
      // Fetch current server count first to be accurate
      const getRes = await fetch(getApiUrl('api.php?action=get&store=global_stats'));
      if (getRes.ok) {
          const data = await getRes.json();
          // Assuming 'global_stats_counter' is the ID in DB
          const serverRow = data.find((d: any) => d.id === 'global_stats_counter');
          let serverCount = serverRow ? parseInt(serverRow.total_api_calls) : 0;

          serverCount++;

          // Save back to server
          await fetch(getApiUrl('api.php?action=save&store=global_stats'), {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  id: 'global_stats_counter',
                  total_api_calls: serverCount
              })
          });

          return serverCount;
      }
  } catch (e) {
      console.error("Failed to sync stats with server", e);
  }

  return count;
};

export const getTotalCalls = async () => {
  try {
      const response = await fetch(getApiUrl('api.php?action=get&store=global_stats'));
      if (response.ok) {
          const data = await response.json();
          const serverRow = data.find((d: any) => d.id === 'global_stats_counter');
          if (serverRow) {
              const count = parseInt(serverRow.total_api_calls);
              localStorage.setItem('simple_api_count', count.toString()); // Sync local
              return count;
          }
      }
  } catch (e) {
      // Fallback to local
  }
  return parseInt(localStorage.getItem('simple_api_count') || '0');
};

