  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleSeek = (timeStr: string) => {
    if (!audioRef.current || !timeStr) return;
    const [m, s] = timeStr.split(':').map(Number);
    const totalSecs = (m * 60) + s;
    audioRef.current.currentTime = Math.max(0, totalSecs - 3);
    audioRef.current.play();
  };

  const transformTranscript = async (type: 'translate' | 'encoding') => {
    if (!transcript || transformingType) return;
    setTransformingType(type);
    setIsAiLoading(true);

    const executeCall = async () => {
      let provider = await getActiveProvider();

      if (!provider) {
          throw new Error("No Active API Key Selected. Please select one in Settings.");
      }

      setActiveApiKeySource(provider.source);
      setActiveModelName(provider.model);

      const ai = new GoogleGenAI({ apiKey: provider.key });
      const prompt = type === 'translate' 
        ? `Translate this transcript between Bengali and English. Keep speakers/timestamps: \n\n${transcript}`
        : `Convert Bengali text between Unicode and Bijoy: \n\n${transcript}`;

      const response: GenerateContentResponse = await ai.models.generateContent({ 
        model: provider.model, 
        contents: prompt 
      });
      const calls = await incrementTotalCalls('Transcript Transform', provider.model, provider.source);
      setTotalApiCalls(calls);
      return response.text;
    };

    try {
      const result = await executeCall();
      if (result) {
        setTranscript(result);
        addToast(appLang === 'bn' ? "সফলভাবে রূপান্তর করা হয়েছে" : "Transformed successfully", 'success');
      }
