  const [activeTab, setActiveTab] = useState('upload');
  const [playbackRate, setPlaybackRate] = useState(1);

  const SENSITIVE_KEYWORDS = [
    'বিজিবি', 'bgb', 'বিডিআর', 'বিডিয়ার', 'bdr', 'dg bgb', 'dg bdr',
    'বিজিবি মহাপরিচালক', 'সীমান্ত', 'বিজিবি সিও', 'বিজিবি অধিনায়ক',
    'বর্ডার গার্ড', 'বর্ডার গার্ড বাংলাদেশ', 'বিএসএফ', 'বিএসএফ ডিজি', 'বিএসএফ মহাপরিচালক'
  ];

  const getSensitiveMatch = (text) => {
    if (!text) return null;
    const lower = text.toLowerCase();
    return SENSITIVE_KEYWORDS.find(kw => lower.includes(kw));
  };

  const formatTime = (s) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleYouTubeSuccess = (blob, fileName, mode) => {
      // 1. Trigger Download to PC (Always fallback to client download)
      try {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
      } catch (e) {
        console.error("Download failed", e);
      }

      // 2. Trigger Auto Transcription ONLY if mode is 'transcribe'
      if (mode === 'transcribe') {
          const file = new File([blob], fileName, { type: blob.type || 'audio/mp3' });
          handleFileChange({ target: { files: [file] } }, true);
      }
  };

  const changePlaybackRate = (rate) => {
    if (audioRef.current) {
        audioRef.current.playbackRate = rate;
    }
    setPlaybackRate(rate);
  };

  const skipTime = (seconds) => {
    if (audioRef.current) {
        audioRef.current.currentTime += seconds;
    }
  };

