            className={`p-2 md:p-3 bg-red-500/10 text-red-500 rounded-full hover:bg-red-600 hover:text-white transition-all border border-red-500/20 active:scale-90 shadow-sm shrink-0 group flex items-center justify-center disabled:opacity-30`}
            title="Clear Results"
          >
            <svg className="w-5 h-5 md:w-6 md:h-6 transition-all group-hover:scale-110" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`flex-1 overflow-hidden relative transition-colors duration-700`}>
        {/* BACKGROUND IMAGE LAYER - ABSOLUTE */}
        <div className="absolute inset-0 z-0">
            <img 
                src={BACKGROUND_IMAGE_URL}
