    { id: 'video_cut', label: appLang === 'bn' ? 'ভিডিও টুলস' : 'Video Tools', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"/> },
    { id: 'audio_cut', label: appLang === 'bn' ? 'অডিও টুলস' : 'Audio Tools', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3"/> }
  ];

  const isMediaTool = currentTab === 'video_cut' || currentTab === 'audio_cut';

  useEffect(() => {
    if (activeTool) {
      setCurrentTab(activeTool);
    }
  }, [activeTool]);

  // --- Simulated Progress ---
  useEffect(() => {
    if (isProcessing) {
        setProcessProgress(0);
        const interval = setInterval(() => {
            setProcessProgress(prev => {
                if (prev >= 90) return prev; // Stall at 90%
                // Faster at start, slower at end
                const increment = prev < 50 ? 5 : prev < 80 ? 2 : 0.5;
                return prev + increment;
            });
        }, 300);
        return () => clearInterval(interval);
    } else {
        setProcessProgress(0);
    }
  }, [isProcessing]);

  // --- SYNC PLAYER WITH TIME INPUTS ---
  const timeToSeconds = (timeStr) => {
    const parts = timeStr.split(':').map(Number);
    if (parts.length !== 3) return 0;
    return (parts[0] || 0) * 3600 + (parts[1] || 0) * 60 + (parts[2] || 0);
  };

  useEffect(() => {
    if (mediaRef.current && startTime && cutMode === 'manual') {
        mediaRef.current.currentTime = timeToSeconds(startTime);
    }
  }, [startTime, cutMode]);

  useEffect(() => {
    if (mediaRef.current && endTime && cutMode === 'manual') {
        mediaRef.current.currentTime = timeToSeconds(endTime);
    }
  }, [endTime, cutMode]);

  const handleMetadataLoaded = () => {
      if (mediaRef.current) {
          setMediaDuration(mediaRef.current.duration);
      }
  };

  // --- RESIZING LOGIC ---
  const startResizing = (e) => {
    e.preventDefault();
    isResizing.current = true;
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', stopResizing);
  };

  const handleMouseMove = (e) => {
    if (!isResizing.current) return;
    const modalElement = document.getElementById('tools-modal-container');
    if (modalElement) {
      const rect = modalElement.getBoundingClientRect();
      setModalSize({
        width: Math.max(600, e.clientX - rect.left),
        height: Math.max(500, e.clientY - rect.top)
      });
    }
  };

  const stopResizing = () => {
    isResizing.current = false;
    window.removeEventListener('mousemove', handleMouseMove);
    window.removeEventListener('mouseup', stopResizing);
  };

  if (!activeTool) return null;

  // --- CLEAR FUNCTIONS ---
  const clearConverterFile = (e) => {
      e.stopPropagation();
      setConvertFile(null);
      setConvertedResult(null);
      if (convertFileInputRef.current) convertFileInputRef.current.value = '';
  };

  const clearCutFile = (e) => {
      e.stopPropagation();
      setCutFile(null);
      setSplitResults([]);
      if (previewUrl) {
          URL.revokeObjectURL(previewUrl);
          setPreviewUrl(null);
      }
      if (cutFileInputRef.current) cutFileInputRef.current.value = '';
  };

  const clearJoinFiles = () => {
      setJoinFiles([]);
      if (joinFileInputRef.current) joinFileInputRef.current.value = '';
  };

  const handleDownloadSuccess = async (blob, fileName) => {
    setProcessProgress(100); // Complete visual progress
    try {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      addToast(appLang === 'bn' ? "ডাউনলোড শুরু হয়েছে" : "Download Started", "success");
    } catch (err) {
      console.log('Save cancelled or failed', err);
    }
  };

  const handleCutFileChange = (e) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          setCutFile(file);
          setSplitResults([]);
          if (previewUrl) URL.revokeObjectURL(previewUrl);
          setPreviewUrl(URL.createObjectURL(file));
      }
  };

  const handleResetTime = () => {
      setStartTime('00:00:00');
      setEndTime('00:00:10');
      addToast(appLang === 'bn' ? "সময় রিসেট হয়েছে" : "Time Reset", "info");
  };

  const secondsToTimestamp = (totalSeconds) => {
      const h = Math.floor(totalSeconds / 3600);
      const m = Math.floor((totalSeconds % 3600) / 60);
      const s = totalSeconds % 60;
      const hh = h.toString().padStart(2, '0');
      const mm = m.toString().padStart(2, '0');
      const ss = Math.floor(s).toString().padStart(2, '0');
      const ms = Math.round((s - Math.floor(s)) * 1000).toString().padStart(3, '0');
      return `${hh}:${mm}:${ss}.${ms}`;
  };

  const processCut = async () => {
      if (!cutFile) {
          addToast(appLang === 'bn' ? "ফাইল সিলেক্ট করুন" : "Select a file", 'error');
          return;
      }

      setIsProcessing(true);
      setSplitResults([]);

      try {
          if (cutMode === 'manual') {
              if (!startTime.match(/^\d{2}:\d{2}:\d{2}$/) || !endTime.match(/^\d{2}:\d{2}:\d{2}$/)) {
                  addToast(appLang === 'bn' ? "সঠিক সময় দিন (HH:MM:SS)" : "Invalid time format", 'error');
                  setIsProcessing(false);
                  return;
              }

              const formData = new FormData();
              formData.append('file', cutFile);
              formData.append('start', startTime);
              formData.append('end', endTime);

              const response = await fetch(getApiUrl('cut_media.php'), { method: 'POST', body: formData });

              if (!response.ok) {
                  throw new Error(`Server connection failed: ${response.status}`);
              }

              const text = await response.text();
              let result;
              try {
                  result = JSON.parse(text);
              } catch (e) {
                  throw new Error(`Server Error (Raw): ${text.substring(0, 100)}...`);
              }

              if (result.error) throw new Error(result.error);

              if (result.base64) {
                  const byteCharacters = atob(result.base64);
                  const byteNumbers = new Array(byteCharacters.length);
                  for (let i = 0; i < byteCharacters.length; i++) {
                      byteNumbers[i] = byteCharacters.charCodeAt(i);
                  }
                  const byteArray = new Uint8Array(byteNumbers);
                  const blob = new Blob([byteArray], { type: `video/${result.format}` });

                  await handleDownloadSuccess(blob, result.filename);
              }
          } else {
              if (!mediaDuration || mediaDuration <= 0) {
                  throw new Error("Invalid media duration");
              }

              const segmentDuration = mediaDuration / splitCount;
              const generatedFiles = [];

              for (let i = 0; i < splitCount; i++) {
                  setProcessingStatus(appLang === 'bn' ? `প্রসেসিং পার্ট ${i+1}/${splitCount}...` : `Processing Part ${i+1}/${splitCount}...`);

                  const startSec = i * segmentDuration;
                  const endSec = (i + 1) * segmentDuration;
                  const startStr = secondsToTimestamp(startSec);
                  const endStr = secondsToTimestamp(endSec);

                  const formData = new FormData();
                  formData.append('file', cutFile);
                  formData.append('start', startStr);
                  formData.append('end', endStr);

                  const response = await fetch(getApiUrl('cut_media.php'), { method: 'POST', body: formData });
                  if (!response.ok) throw new Error(`Server connection failed: ${response.status}`);

                  const text = await response.text();
                  let result;
                  try {
                      result = JSON.parse(text);
                  } catch (e) {
                      throw new Error(`Server Part Error: ${text.substring(0, 100)}...`);
                  }

                  if (result.error) throw new Error(`Part ${i+1} Failed: ${result.error}`);

                  if (result.base64) {
                      const byteCharacters = atob(result.base64);
                      const byteNumbers = new Array(byteCharacters.length);
                      for (let i = 0; i < byteCharacters.length; i++) {
                          byteNumbers[i] = byteCharacters.charCodeAt(i);
                      }
                      const byteArray = new Uint8Array(byteNumbers);
                      const blob = new Blob([byteArray], { type: `video/${result.format}` });

                      generatedFiles.push({
                          name: `Part_${i+1}_of_${splitCount}_${cutFile.name}`,
                          blob: blob
                      });
                  }
              }
              setSplitResults(generatedFiles);
              addToast(appLang === 'bn' ? "স্প্লিট সম্পন্ন হয়েছে" : "Split completed", 'success');
          }

      } catch (e) {
          console.error(e);
          addToast(appLang === 'bn' ? `ব্যর্থ: ${e.message}` : `Failed: ${e.message}`, 'error');
      } finally {
          setIsProcessing(false);
          setProcessingStatus('');
      }
  };

  const handleTranscribePart = (part) => {
      if (onFileSelect) {
          const file = new File([part.blob], part.name, { type: part.blob.type });
          onFileSelect(file);
          setIsMinimized(true);
          addToast(appLang === 'bn' ? "ট্রান্সক্রিপশন শুরু হচ্ছে... (টুলস মিনিমাইজড)" : "Starting transcription... (Tools Minimized)", 'info');
      }
  };

  const handleJoinFileChange = (e) => {
      if (e.target.files && e.target.files.length > 0) {
          setJoinFiles(prev => [...prev, ...Array.from(e.target.files || [])]);
      }
  };

  const removeJoinFile = (index) => {
      setJoinFiles(prev => prev.filter((_, i) => i !== index));
  };

  const processJoin = async () => {
      if (joinFiles.length < 2) {
          addToast(appLang === 'bn' ? "কমপক্ষে ২টি ফাইল প্রয়োজন" : "Need at least 2 files", 'warning');
          return;
      }

      setIsProcessing(true);
      const formData = new FormData();
      joinFiles.forEach((file) => {
          formData.append('files[]', file);
      });

      try {
          const response = await fetch(getApiUrl('join_media.php'), {
              method: 'POST',
              body: formData
          });
          if (!response.ok) throw new Error(`Server connection failed: ${response.status}`);

          const text = await response.text();
          let result;
          try {
              result = JSON.parse(text);
          } catch (e) {
              throw new Error(`Server Error: ${text.substring(0, 100)}...`);
          }

          if (result.error) throw new Error(result.error);

          if (result.base64) {
              const byteCharacters = atob(result.base64);
              const byteNumbers = new Array(byteCharacters.length);
              for (let i = 0; i < byteCharacters.length; i++) {
                  byteNumbers[i] = byteCharacters.charCodeAt(i);
              }
              const byteArray = new Uint8Array(byteNumbers);
              const blob = new Blob([byteArray], { type: `video/${result.format}` });

              await handleDownloadSuccess(blob, result.filename);
              setJoinFiles([]); 
          }
      } catch (e) {
          console.error(e);
          addToast(appLang === 'bn' ? `জয়েনিং ব্যর্থ: ${e.message}` : `Joining failed: ${e.message}`, 'error');
      } finally {
          setIsProcessing(false);
      }
  };

  const handleConverterFileChange = (e) => {
      if (e.target.files && e.target.files[0]) {
          setConvertFile(e.target.files[0]);
          setConvertedResult(null); // Reset previous result
      }
  };

  const processConvert = async () => {
      if (!convertFile) {
          addToast(appLang === 'bn' ? "ফাইল সিলেক্ট করুন" : "Select a file", 'error');
          return;
      }

      setIsProcessing(true);
      setConvertedResult(null);

      const formData = new FormData();
      formData.append('file', convertFile);
      formData.append('format', targetFormat);
      formData.append('bitrate', audioBitrate);
      formData.append('channels', audioChannels);

      try {
          const response = await fetch(getApiUrl('convert_media.php'), {
              method: 'POST',
              body: formData
          });
          if (!response.ok) throw new Error(`Server connection failed: ${response.status}`);

          const text = await response.text();
          let result;
          try {
              result = JSON.parse(text);
          } catch (e) {
              throw new Error(`Server Error: ${text.substring(0, 100)}...`);
          }

          if (result.error) throw new Error(result.error);

          if (result.base64) {
              const byteCharacters = atob(result.base64);
              const byteNumbers = new Array(byteCharacters.length);
              for (let i = 0; i < byteCharacters.length; i++) {
                  byteNumbers[i] = byteCharacters.charCodeAt(i);
              }
              const byteArray = new Uint8Array(byteNumbers);

              let mime = 'application/octet-stream';
              if (['mp3', 'wav', 'ogg', 'm4a', 'aac', 'opus'].includes(result.format)) mime = `audio/${result.format}`;
              else if (['mp4', 'webm', 'mkv', 'avi'].includes(result.format)) mime = `video/${result.format}`;

              const blob = new Blob([byteArray], { type: mime });

              setConvertedResult({blob, name: result.filename});
              await handleDownloadSuccess(blob, result.filename);
              addToast(appLang === 'bn' ? "কনভার্ট সফল হয়েছে" : "Conversion successful", 'success');
          }
      } catch (e) {
          console.error(e);
          addToast(appLang === 'bn' ? `কনভার্ট ব্যর্থ: ${e.message}` : `Conversion failed: ${e.message}`, 'error');
      } finally {
          setIsProcessing(false);
      }
  };

  // Reusable Processing UI
  const renderProcessingState = (status) => (
      <div className="w-full flex flex-col gap-3 animate-in fade-in zoom-in duration-300">
          <div className="h-10 bg-slate-100 dark:bg-black/20 rounded-xl overflow-hidden relative shadow-inner border border-slate-200 dark:border-white/10">
              <div 
                  className={`h-full ${activeColors.primary} transition-all duration-300 relative`}
                  style={{ width: `${processProgress}%` }}
              >
                  <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite]"></div>
              </div>
              <div className="absolute inset-0 flex items-center justify-center">
                  <span className={`text-[10px] font-black uppercase tracking-widest ${isDark ? 'text-white' : 'text-slate-800'} drop-shadow-md`}>
                      {status} {Math.round(processProgress)}%
                  </span>
              </div>
          </div>
          <p className="text-center text-[9px] opacity-50 font-bold uppercase animate-pulse">
              {appLang === 'bn' ? 'দয়া করে অপেক্ষা করুন, সার্ভারে কাজ চলছে...' : 'Please wait, processing on server...'}
          </p>
      </div>
  );

  return (
    <>
      {/* Minimized Floating Widget - Visible ONLY when isMinimized is true */}
      <div className={`fixed bottom-24 right-20 z-[100] animate-in slide-in-from-bottom-10 fade-in duration-300 ${isMinimized ? 'block' : 'hidden'}`}>
