  const transcriptSearchInputRef = useRef<HTMLInputElement>(null);

  // UI Customization
  const [fontSize, setFontSize] = useState(16);
  const [scrollPercent, setScrollPercent] = useState(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Recorder
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordIntervalRef = useRef<number | null>(null);

  // API Stats
  const [totalApiCalls, setTotalApiCalls] = useState(0);
  const [activeApiKeySource, setActiveApiKeySource] = useState('Checking...');
  const [activeModelName, setActiveModelName] = useState('Loading...');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Processing View
  const [progress, setProgress] = useState(0);
  const [currentStage, setCurrentStage] = useState('');
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [estimatedSeconds, setEstimatedSeconds] = useState(0);

  // Derived
  const isDark = theme === 'soft-dark';
  const t = translations[appLang];

  const activeColors = isDark ? {
    primary: 'bg-indigo-600',
    text: 'text-indigo-400',
    border: 'border-indigo-500/50',
    soft: 'bg-indigo-900/20',
    ring: 'ring-indigo-500'
  } : {
    primary: 'bg-indigo-600',
    text: 'text-indigo-600',
    border: 'border-indigo-200',
    soft: 'bg-indigo-50',
    ring: 'ring-indigo-200'
  };

  const mainBgColor = isDark ? 'bg-slate-900' : 'bg-slate-50';
  const textColor = isDark ? 'text-white' : 'text-slate-800';
  const cardBg = isDark ? 'bg-white/5 backdrop-blur-md' : 'bg-white';
  const cardBorder = isDark ? 'border-white/10' : 'border-slate-100';
  const subTextColor = isDark ? 'text-slate-400' : 'text-slate-500';

  useEffect(() => {
    loadHistory();
    updateApiStats();

    const handleTimeUpdate = () => {
      if (audioRef.current) {
        setAudioCurrentTime(audioRef.current.currentTime);
      }
    };
    const audioEl = audioRef.current;
    if (audioEl) {
      audioEl.addEventListener('timeupdate', handleTimeUpdate);
    }
    return () => {
      if (audioEl) audioEl.removeEventListener('timeupdate', handleTimeUpdate);
    };
  }, [fileUrl]);

  const loadHistory = async () => {
    const data = await getAllFromStore(STORES.HISTORY);
    setHistory(data.sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };

  const updateApiStats = async () => {
    const calls = await getTotalCalls();
    setTotalApiCalls(calls);
    const provider = await getActiveProvider();
    if (provider) {
      setActiveApiKeySource(provider.source);
      setActiveModelName(provider.model);
    } else {
      setActiveApiKeySource('None');
      setActiveModelName('None');
    }
  };

  const handleFileChange = async (e: any, autoStart = false) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    setFile(selectedFile);
    const url = URL.createObjectURL(selectedFile);
    setFileUrl(url);

    const audio = new Audio(url);
    audio.onloadedmetadata = () => {
      const duration = audio.duration;
      const mins = Math.floor(duration / 60);
      const secs = Math.floor(duration % 60);
      setFileMeta({
        name: selectedFile.name,
        size: (selectedFile.size / 1024 / 1024).toFixed(2) + ' MB',
        duration: `${mins}:${secs.toString().padStart(2, '0')}`,
        type: selectedFile.type
      });
      if (autoStart) {
        processTranscription(selectedFile);
      }
    };
  };

  const resetAll = () => {
    setFile(null);
    setFileUrl(null);
    setFileMeta({});
    setTranscript('');
    setStatus('idle');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const fileInputRef = useRef<HTMLInputElement>(null);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/mp3' });
        const file = new File([blob], `Recording_${new Date().toLocaleTimeString()}.mp3`, { type: 'audio/mp3' });
        handleFileChange({ target: { files: [file] } });
        setIsRecording(false);
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      recordIntervalRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (e) {
      console.error("Mic Access Error", e);
      addToast(appLang === 'bn' ? "মাইক্রোফোন এক্সেস পাওয়া যায়নি" : "Microphone access denied", 'error');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      if (recordIntervalRef.current) clearInterval(recordIntervalRef.current);
    }
  };

  const processTranscription = async (inputFile = file) => {
    if (!inputFile) return;
    setStatus('processing');
    setProgress(0);
    setElapsedSeconds(0);
    setEstimatedSeconds(30);
    setCurrentStage(appLang === 'bn' ? 'অডিও প্রসেসিং হচ্ছে...' : 'Processing Audio...');

    const timer = setInterval(() => {
      setElapsedSeconds(s => s + 1);
      setProgress(p => Math.min(p + (100 / 30), 95));
    }, 1000);

    try {
      const base64Data = await fileToBase64(inputFile);
      const checkProvider = await getActiveProvider();

      if (!checkProvider) {
        throw new Error("No API Key configured. Please add one in Settings.");
      }

      setCurrentStage(appLang === 'bn' ? 'এআই জেনারেশন চলছে...' : 'AI Generation...');

      const ai = new GoogleGenAI({ apiKey: checkProvider.key });
      const mimeType = inputFile.type || 'audio/mp3';

      const response = await ai.models.generateContent({
          model: checkProvider.model || 'gemini-3-flash-preview', 
          contents: { 
              role: 'user',
              parts: [
                  { inlineData: { mimeType: mimeType, data: base64Data as string } }, 
                  { text: "Listen to the audio carefully. Regardless of the spoken language (English, Hindi, Urdu, etc.), transcribe and translate the content directly into standard Bengali (Bangla) script. The final output MUST be in Bangla. STRICT FORMAT: Start every new minute or speaker change with a timestamp [MM:SS]. Example: [00:00] **Speaker 1:** বাংলা টেক্সট... If no speech detected, output [Silence]." }
              ] 
          },
          config: {
              temperature: 0.1, 
              safetySettings: [
                  { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_NONE' },
                  { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_NONE' },
                  { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_NONE' },
                  { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_NONE' },
              ]
          }
      });

      await incrementTotalCalls('Transcription', checkProvider.model || 'gemini-3-flash-preview', checkProvider.source);
      updateApiStats();

      const text = response.text;
      if (!text) throw new Error("Empty response from AI");

      setTranscript(text);
      setStatus('completed');

      const historyItem = {
        id: Date.now().toString(),
        fileName: inputFile.name,
        date: new Date().toISOString(),
        duration: fileMeta.duration || '00:00',
        transcript: text,
        extension: inputFile.name.split('.').pop(),
        timeTaken: `${elapsedSeconds}s`
      };
      await addToStore(STORES.HISTORY, historyItem);
      loadHistory();
      logSystemActivity('TRANSCRIPTION', 'SUCCESS', 'File Transcribed', `File: ${inputFile.name}`);

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      setErrorMessage(error.message || "Unknown error occurred");
      logSystemActivity('TRANSCRIPTION', 'ERROR', 'Failed', error.message);
    } finally {
      clearInterval(timer);
      setProgress(100);
    }
  };

  const addToast = (msg: string, type: 'success' | 'error' | 'info' | 'warning') => {
    // Basic implementation
    console.log(`[${type.toUpperCase()}] ${msg}`);
    if (type === 'error') alert(msg);
  };

  const handleScroll = () => {
    if (scrollContainerRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
      const percent = Math.round((scrollTop / (scrollHeight - clientHeight)) * 100);
      setScrollPercent(percent);
    }
  };

  const scrollToTop = () => scrollContainerRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  const scrollToBottom = () => scrollContainerRef.current?.scrollTo({ top: scrollContainerRef.current.scrollHeight, behavior: 'smooth' });

  return (
    <div className={`flex h-screen overflow-hidden ${mainBgColor} ${textColor} font-sans selection:bg-indigo-500/30`}>
      <SpiderWebBackground opacity={isDark ? "opacity-[0.09]" : "opacity-[0.05]"} />

      <Sidebar 
        t={t}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
        sidebarSide="left"
        bgColor={isDark ? 'bg-slate-900/50 backdrop-blur-xl' : 'bg-white/80 backdrop-blur-xl'}
        activeColors={activeColors}
        cardBg={cardBg}
        cardBorder={cardBorder}
        isDark={isDark}
        subTextColor={subTextColor}
        fileInputRef={fileInputRef}
        handleFileChange={handleFileChange}
        fileUrl={fileUrl}
        resetAll={resetAll}
        fileMeta={fileMeta}
        audioRef={audioRef}
        processTranscription={() => processTranscription(file)}
        status={status}
        history={history}
        setIsHistoryFullscreen={setIsHistoryFullscreen}
        groupHistory={(items) => {
           const groups: any = {};
           items.forEach(item => {
             const d = new Date(item.date).toLocaleDateString();
             if (!groups[d]) groups[d] = [];
             groups[d].push(item);
           });
           return groups;
        }}
        loadHistoryItem={(item) => {
           setTranscript(item.transcript);
           setStatus('completed');
           setFileMeta({ name: item.fileName, duration: item.duration });
           setFileUrl(null); 
        }}
        appLang={appLang}
        isRecording={isRecording}
        recordingTime={recordingTime}
        onStartRecording={startRecording}
        onStopRecording={stopRecording}
      />

      <div className="flex-1 flex flex-col min-w-0 relative z-10 transition-all duration-300">
        <Header 
          t={t}
          status={status}
          isSidebarOpen={isSidebarOpen}
          setIsSidebarOpen={setIsSidebarOpen}
          isInformationOpen={isInformationOpen}
          setIsInformationOpen={setIsInformationOpen}
          isActivityLogOpen={isActivityLogOpen}
          setIsActivityLogOpen={setIsActivityLogOpen}
          isDark={isDark}
          setTheme={(v) => setTheme(typeof v === 'function' ? v(theme) : v)}
          appLang={appLang}
          setAppLang={(v) => setAppLang(typeof v === 'function' ? v(appLang) : v)}
          activeColors={activeColors}
          setActiveTool={setActiveTool}
          setIsReportOpen={setIsReportOpen}
        />

        <TranscriptOutput 
          t={t}
          status={status}
          isSearchExpanded={true}
          setIsSearchExpanded={() => {}}
          transcriptSearchInputRef={transcriptSearchInputRef}
          searchTerm={searchTerm}
          handleSearchChange={(e) => setSearchTerm(e.target.value)}
          activeColors={activeColors}
          downloadText={() => {}}
          setStatus={setStatus}
          setTranscript={setTranscript}
          mainBgColor={mainBgColor}
          fileUrl={fileUrl}
          textColor={textColor}
          isDark={isDark}
          setIsSidebarOpen={setIsSidebarOpen}
          fileMeta={fileMeta}
          processTranscription={() => processTranscription(file)}
          scrollContainerRef={scrollContainerRef}
          handleScroll={handleScroll}
          transcriptCardBg={cardBg}
          cardBorder={cardBorder}
          renderFormattedTranscript={(text) => text}
          transcript={transcript}
          showScrollTop={scrollPercent > 5}
          scrollToTop={scrollToTop}
          showScrollBottom={scrollPercent < 95}
          scrollToBottom={scrollToBottom}
          fontSize={fontSize}
          setFontSize={setFontSize}
          matchCount={matchCount}
          currentMatchIndex={currentMatchIndex}
          goToNextMatch={() => {}}
          goToPrevMatch={() => {}}
          errorMessage={errorMessage}
          addToast={addToast}
          appLang={appLang}
          history={history}
          progress={progress}
          currentStage={currentStage}
          elapsedSeconds={elapsedSeconds}
          estimatedSeconds={estimatedSeconds}
