        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
      />

      {/* 
      <ChatBot 
        activeColors={activeColors}
        isDark={isDark}
        appLang={appLang}
        addToast={addToast}
      /> 
      */}
    </div>
  );
};

