    subTitle: "অ্যাডভান্সড এআই ট্রান্সক্রিপশন",
    openMenu: "মেনু খুলুন",
    busy: "ব্যস্ত",
    online: "অনলাইন",
    systemStatus: "সিস্টেম স্ট্যাটাস",
    toggleTheme: "থিম পরিবর্তন",
    outputTranscript: "ট্রান্সক্রিপ্ট আউটপুট",
    searchPlaceholder: "ট্রান্সক্রিপ্টে খুঁজুন...",
    translateBtn: "অনুবাদ",
    convertBtn: "কনভার্ট",
    download: "ডাউনলোড",
    audioVideoFile: "অডিও/ভিডিও ফাইল",
    clickToUpload: "আপলোড করতে ক্লিক করুন",
    fileInfo: "ফাইল ইনফো",
    nameLabel: "নাম",
    sizeLabel: "সাইজ",
    durationLabel: "স্থিতিকাল",
    processingTranscribe: "প্রসেসিং...",
    startTranscribe: "ট্রান্সক্রাইব শুরু করুন",
