    expand: "বড় করুন",
    empty: "খালি",
    historyLabelDate: "তারিখ",
    noMedia: "কোনো মিডিয়া নেই",
    noMediaDesc: "শুরু করতে ফাইল আপলোড বা রেকর্ড করুন",
    fileReady: "ফাইল রেডি",
    processingHeader: "প্রসেসিং",
    proMode: "প্রো মোড সক্রিয়",
    itemsLogged: "আইটেম সেভড",
