                  <div className="flex-1 flex flex-col justify-center items-center text-center space-y-8">
                      <div className={`w-28 h-28 rounded-full flex items-center justify-center ${isSyncing ? 'bg-indigo-600 animate-pulse' : 'bg-slate-200 dark:bg-white/10'}`}>
