import React, { useState, useEffect, useRef } from 'react';
import { getApiUrl } from '../../services/api.ts';

interface YouTubeInputProps {
  onSuccess: (blob: Blob, fileName: string, mode: 'download' | 'transcribe') => void;
  isDark: boolean;
  activeColors: any;
  appLang: string;
  platform?: 'youtube' | 'facebook';
  onFolderOpen?: () => void;
  allowVideo?: boolean;
  showFormats?: boolean; // New prop to control visibility of dropdown
}

export const YouTubeInput: React.FC<YouTubeInputProps> = ({ 
  onSuccess, isDark, activeColors, appLang, platform = 'youtube', 
  onFolderOpen, allowVideo = false, showFormats = true 
}) => {
  const [url, setUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingMode, setLoadingMode] = useState<'download' | 'transcribe' | null>(null);
  const [error, setError] = useState('');
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [totalTimeTaken, setTotalTimeTaken] = useState<string | null>(null);

  // Quality selection state
  const [quality, setQuality] = useState('audio'); 

  const timerRef = useRef<number | null>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (loading) {
      setElapsedSeconds(0);
      setTotalTimeTaken(null);
      timerRef.current = window.setInterval(() => {
        setElapsedSeconds(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [loading]);

  const formatTime = (totalSeconds: number) => {
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${mins}m ${secs}s`;
  };

  const handleCancel = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setLoading(false);
    setLoadingMode(null);
    setError(appLang === 'bn' ? 'কনভার্সন বাতিল করা হয়েছে' : 'Conversion cancelled');
    if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
    }
  };

  const processYouTube = async (mode: 'download' | 'transcribe') => {
    const isValid = url.includes('youtube.com') || url.includes('youtu.be') || url.includes('facebook.com') || url.includes('fb.watch');

    if (!url || !isValid) {
      setError(appLang === 'bn' ? 'সঠিক ইউটিউব বা ফেসবুক লিংক দিন' : 'Invalid Video URL');
      return;
    }

    setLoading(true);
    setLoadingMode(mode);
    setError('');
    setTotalTimeTaken(null);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const apiUrl = getApiUrl('youtube.php');

      const bodyPayload = { 
          url, 
          // If showFormats is false, force 'audio' (optimized for transcription)
          quality: showFormats ? quality : 'audio' 
      };

      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(bodyPayload),
        signal: controller.signal
      });

      const text = await response.text();
      let result;
      try {
        result = JSON.parse(text);
      } catch (e) {
        console.error("Server Raw Response:", text);
        throw new Error(appLang === 'bn' ? "সার্ভার এরর (JSON Parse Failed)" : "Server returned invalid data");
      }

      if (result.error) {
        throw new Error(result.error);
      }

      if (result.base64 && result.filename) {
        const byteCharacters = atob(result.base64);
        const byteNumbers = new Array(byteCharacters.length);
        for (let i = 0; i < byteCharacters.length; i++) {
          byteNumbers[i] = byteCharacters.charCodeAt(i);
        }
        const byteArray = new Uint8Array(byteNumbers);

        let mimeType = 'audio/mp3'; // Default fallback
        const ext = result.format?.toLowerCase() || 'mp3';

        if (ext === 'm4a') mimeType = 'audio/mp4';
        else if (ext === 'wav') mimeType = 'audio/wav';
        else if (ext === 'opus' || ext === 'ogg') mimeType = 'audio/ogg';
        else if (ext === 'webm') mimeType = 'video/webm';
        else if (ext === 'mp4') mimeType = 'video/mp4';
        else if (ext === 'aac') mimeType = 'audio/aac';

        const blob = new Blob([byteArray], { type: mimeType });

        const finalTime = formatTime(elapsedSeconds);
        setTotalTimeTaken(finalTime); 

        onSuccess(blob, result.filename, mode);
        setUrl('');
      } else {
        throw new Error('Invalid response structure');
      }

    } catch (e: any) {
      if (e.name === 'AbortError') {
          console.log('Fetch aborted');
          return;
      }
      console.error(e);
      let msg = e.message || (appLang === 'bn' ? 'প্রসেসিং এরর হয়েছে' : 'Processing error');

      if (msg.includes('Failed to fetch')) {
        msg = appLang === 'bn' 
            ? 'সার্ভার কানেকশন সমস্যা (CORS/Timeout)। XAMPP চালু আছে কিনা দেখুন।' 
            : 'Connection Failed (CORS/Timeout). Check if XAMPP is running.';
      }

      setError(msg);
      setTotalTimeTaken(null);
    } finally {
      setLoading(false);
      setLoadingMode(null);
      abortControllerRef.current = null;
    }
  };

  const placeholderText = platform === 'facebook' 
    ? (appLang === 'bn' ? 'ফেসবুক লিংক পেস্ট করুন' : 'Paste Facebook Link')
    : (appLang === 'bn' ? 'ইউটিউব লিংক পেস্ট করুন' : 'Paste YouTube Link');

  return (
    <div className={`p-4 rounded-2xl ${isDark ? 'bg-black/20 border border-white/5' : 'bg-slate-50 border border-slate-100'}`}>
      <div className="relative mb-3 flex flex-col gap-3">
        <div className="relative w-full">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <svg className={`w-4 h-4 ${platform === 'facebook' ? 'text-blue-500' : 'text-red-500'}`} fill="currentColor" viewBox="0 0 24 24">
                {platform === 'facebook' 
                    ? <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/>
                    : <path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 3.993-8 4.007z"/>
                }
            </svg>
            </div>
            <input 
            type="text" 
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            placeholder={placeholderText}
            disabled={loading}
            className={`w-full pl-10 pr-12 py-3 rounded-xl text-xs font-bold border outline-none focus:ring-2 focus:ring-opacity-20 transition-all ${platform === 'facebook' ? 'focus:ring-blue-500' : 'focus:ring-red-500'} ${isDark ? 'bg-white/5 border-white/10 text-white placeholder:text-white/30' : 'bg-white border-slate-200 text-slate-800'} ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
            />
            {loading && (
                <button 
                    onClick={handleCancel}
                    className="absolute right-1 top-1.5 w-8 h-8 bg-red-500 hover:bg-red-600 text-white rounded-lg flex items-center justify-center shadow-lg active:scale-95 transition-all z-10"
                    title={appLang === 'bn' ? 'বাতিল করুন' : 'Cancel'}
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
            )}
        </div>

        {/* Action Buttons Row */}
        <div className="flex gap-2">
            {showFormats && (
                <select 
                    value={quality} 
                    onChange={(e) => setQuality(e.target.value)}
                    disabled={loading}
                    className={`w-28 px-3 py-3 rounded-xl text-xs font-bold outline-none border appearance-none cursor-pointer focus:ring-2 transition-all ${
                        isDark 
                        ? 'bg-white/5 border-white/10 text-white focus:ring-white/20 [&>option]:bg-slate-800 [&>option]:text-white' 
                        : 'bg-white border-slate-200 text-slate-800 focus:ring-indigo-300'
                    }`}
                >
                    <optgroup label="Audio Only">
                        <option value="audio">Opus 16k (Fast)</option>
                        <option value="audio_best">Best Audio</option>
                    </optgroup>
                    {allowVideo && (
                        <optgroup label="Video Quality">
                            <option value="best">Best Available</option>
                            <option value="720">720p HD</option>
                            <option value="480">480p SD</option>
                            <option value="360">360p Low</option>
                            <option value="240">240p Mobile</option>
                        </optgroup>
                    )}
                </select>
            )}

            {/* Download Only Button */}
            <button 
                onClick={() => processYouTube('download')}
                disabled={loading || !url}
                className={`flex-1 py-3 bg-slate-700 hover:bg-slate-800 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50`}
            >
                {loading && loadingMode === 'download' ? (
                    <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                )}
                <span className="hidden sm:inline">{appLang === 'bn' ? 'শুধু ডাউনলোড' : 'DL ONLY'}</span>
            </button>

            {/* Transcribe Button */}
            <button 
                onClick={() => processYouTube('transcribe')}
                disabled={loading || !url}
                className={`flex-1 py-3 ${platform === 'facebook' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-red-600 hover:bg-red-700'} text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50`}
            >
                {loading && loadingMode === 'transcribe' ? (
                    <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : (
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                )}
                <span>{appLang === 'bn' ? 'ট্রান্সক্রাইব' : 'TRANSCRIBE'}</span>
            </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-3">
           <p className="text-[10px] text-red-500 font-bold break-words leading-relaxed whitespace-pre-wrap">{error}</p>
        </div>
      )}

      {/* Time Display */}
      {(loading || totalTimeTaken) && (
        <div className="mt-4 flex justify-center animate-in fade-in bg-black/5 rounded-lg py-2 border border-black/5 dark:bg-white/5 dark:border-white/5">
           <span className={`text-[10px] font-black uppercase tracking-widest ${loading ? 'text-amber-500 animate-pulse' : 'text-emerald-500'}`}>
              {loading 
                 ? `${appLang === 'bn' ? 'সময় অতিবাহিত' : 'Time Elapsed'}: ${formatTime(elapsedSeconds)}` 
                 : `${appLang === 'bn' ? 'মোট সময় লেগেছে' : 'Total Time'}: ${totalTimeTaken}`
              }
           </span>
        </div>
      )}

      {!loading && !totalTimeTaken && (
        <p className="text-[9px] text-center mt-2 opacity-40 font-bold uppercase tracking-wide">
          D:/audio • HIGH SPEED
        </p>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';

interface HeaderProps {
  t: any;
  status: string;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (v: boolean) => void;
  isInformationOpen: boolean;
  setIsInformationOpen: (v: boolean) => void;
  isActivityLogOpen?: boolean;
  setIsActivityLogOpen?: (v: boolean) => void;
  isDark: boolean;
  setTheme: (f: (p: any) => any) => void;
  appLang: string;
  setAppLang: (f: (p: any) => any) => void;
  activeColors: any;
  setActiveTool?: (tool: string) => void;
  setIsReportOpen?: (v: boolean) => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  t, status, isSidebarOpen, setIsSidebarOpen, 
  isInformationOpen, setIsInformationOpen,
  isActivityLogOpen, setIsActivityLogOpen,
  isDark, setTheme,
  appLang, setAppLang, activeColors, setActiveTool, setIsReportOpen 
}) => {
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showToolsMenu, setShowToolsMenu] = useState(false);

  useEffect(() => {
    const handleFullScreenChange = () => {
      setIsFullScreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullScreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullScreenChange);
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
      }
    }
  };

  const handleToolClick = (toolId: string) => {
    if (setActiveTool) setActiveTool(toolId);
    setShowToolsMenu(false);
  };

  return (
    <header className="px-4 md:px-8 py-4 md:py-5 bg-gradient-to-r from-slate-950 via-slate-900 to-slate-800 border-b border-white/10 flex items-center justify-between z-40 shadow-sm shrink-0">
      <div className="flex items-center space-x-3 md:space-x-4">
        <button 
          type="button"
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className={`p-2 md:p-2.5 rounded-xl transition-all border border-white/10 group ${isSidebarOpen ? activeColors.primary + ' text-white border-white/20' : 'bg-white/5 text-white/60 hover:text-white hover:bg-white/10'}`}
          title={t.openMenu}
        >
          <svg className="w-5 h-5 md:w-6 md:h-6 transition-transform duration-300 group-hover:scale-125 group-hover:rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16m-7 6h7" />
          </svg>
        </button>
        <div className="bg-white p-2 md:p-2.5 rounded-xl shadow-lg shadow-black/20 group cursor-default hidden sm:block">
          <svg className={`w-5 h-5 md:w-6 md:h-6 ${activeColors.text} transition-all duration-500 group-hover:scale-125 group-hover:rotate-12`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
        </div>
        <div>
          <h1 className="text-lg md:text-xl font-bold tracking-tight text-white leading-tight">LI CELL <span className={`font-black ${isDark ? 'text-indigo-400' : activeColors.text} hidden sm:inline`}>{t.studio}</span></h1>
          <p className="text-[8px] md:text-[9px] text-white/50 font-black uppercase tracking-widest leading-none mt-0.5 md:mt-1 hidden sm:block">{t.subTitle}</p>
        </div>
      </div>

      <div className="flex items-center space-x-2 md:space-x-3">
        {/* Full Screen Button */}
        <button 
          type="button"
