          className={`p-2 md:p-2.5 rounded-xl transition-all border border-white/10 bg-white/5 hover:bg-white/10 text-white/60 hover:text-white group hidden sm:block`}
          title={isFullScreen ? (appLang === 'bn' ? 'ছোট স্ক্রিন' : 'Exit Full Screen') : (appLang === 'bn' ? 'ফুল স্ক্রিন' : 'Full Screen')}
        >
          {isFullScreen ? (
            <svg className="w-5 h-5 md:w-6 md:h-6 transition-transform duration-500 group-hover:scale-110" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 9L4 4m0 0l5 0m-5 0l0 5M15 9l5-5m0 0l-5 0m5 0l0 5M9 15l-5 5m0 0l5 0m-5 0l0-5M15 15l5 5m0 0l-5 0m5 0l0-5" />
            </svg>
          ) : (
            <svg className="w-5 h-5 md:w-6 md:h-6 transition-transform duration-500 group-hover:scale-110" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
            </svg>
          )}
        </button>

        {/* Tools Menu Button */}
        <div className="relative">
          <button 
            type="button"
            onClick={() => setShowToolsMenu(!showToolsMenu)}
            className={`p-2 md:p-2.5 rounded-xl transition-all border border-white/10 bg-white/5 hover:bg-white/10 text-white/60 hover:text-white group ${showToolsMenu ? 'bg-white/20 text-white ring-2 ring-indigo-500/50' : ''}`}
