import React, { useState, useEffect, useRef, useCallback } from 'react';
import { YouTubeInput } from './YouTubeInput.tsx';
import { getApiUrl } from '../../services/api.ts';

const TimeKnob = ({ value, max, onChange, label, activeColors, isDark }) => {
  const knobRef = useRef(null);
  const [isDragging, setIsDragging] = useState(false);

  const calculateValue = useCallback((e) => {
    if (!knobRef.current) return;
    const rect = knobRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;

    // Calculate angle in degrees
    const x = e.clientX - centerX;
    const y = e.clientY - centerY;
    let angle = Math.atan2(y, x) * (180 / Math.PI);
    angle = angle + 90; // Offset to make top 0
    if (angle < 0) angle += 360;

    // Map angle to value
    const newValue = Math.round((angle / 360) * max) % max;
    onChange(newValue);
  }, [max, onChange]);

  const handleMouseDown = (e) => {
    setIsDragging(true);
    calculateValue(e);
  };

  const handleWheel = (e) => {
    e.stopPropagation();
    const direction = e.deltaY < 0 ? 1 : -1;
    let newValue = value + direction;
    if (newValue >= max) newValue = 0;
    if (newValue < 0) newValue = max - 1;
    onChange(newValue);
  };

  useEffect(() => {
    const handleMouseMove = (e) => {
      if (isDragging) {
        e.preventDefault(); 
        calculateValue(e);
      }
    };
    const handleMouseUp = () => setIsDragging(false);

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, calculateValue]);

  const rotation = (value / max) * 360;

  return (
    <div className="flex flex-col items-center gap-1" onWheel={handleWheel}>
      <div 
        ref={knobRef}
        onMouseDown={handleMouseDown}
        className={`w-12 h-12 rounded-full border-2 relative cursor-pointer shadow-lg transition-transform active:scale-95 ${isDark ? 'bg-slate-800 border-slate-600' : 'bg-slate-100 border-slate-300'}`}
        style={{ transform: `rotate(${rotation}deg)` }}
        title="Drag or Scroll to adjust"
      >
        <div className={`absolute top-1 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full ${activeColors.primary} shadow-[0_0_8px_currentColor]`}></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 rounded-full bg-slate-400/20 shadow-inner"></div>
      </div>
      <span className="text-[9px] font-black uppercase tracking-wider opacity-60 select-none">{label}</span>
      <span className={`text-[10px] font-mono font-bold select-none ${isDark ? 'text-white' : 'text-slate-900'}`}>
        {value.toString().padStart(2, '0')}
      </span>
    </div>
  );
};

const TimeSelector = ({ timeStr, onChange, label, isDark, activeColors }) => {
  const parseTime = (t) => {
    const parts = t.split(':').map(Number);
    return { h: parts[0] || 0, m: parts[1] || 0, s: parts[2] || 0 };
  };

  const { h, m, s } = parseTime(timeStr);

  const updateTime = (unit, val) => {
    let newH = h, newM = m, newS = s;
    if (unit === 'h') newH = val;
    if (unit === 'm') newM = val;
    if (unit === 's') newS = val;

    const formatted = `${newH.toString().padStart(2,'0')}:${newM.toString().padStart(2,'0')}:${newS.toString().padStart(2,'0')}`;
    onChange(formatted);
  };

  return (
    <div className={`p-4 rounded-2xl border ${isDark ? 'bg-black/20 border-white/5' : 'bg-white border-slate-200'} flex flex-col items-center gap-3 w-full`}>
      <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-50">{label}</span>
      <input 
        type="text" 
        value={timeStr} 
        onChange={(e) => onChange(e.target.value)} 
        className={`w-full text-center text-2xl font-mono font-bold bg-transparent outline-none border-b ${isDark ? 'border-white/10 text-white focus:border-white/30' : 'border-slate-200 text-slate-800 focus:border-slate-400'} py-2 mb-2`} 
      />
      <div className="flex gap-4 justify-center">
        <TimeKnob value={h} max={24} onChange={(v) => updateTime('h', v)} label="HR" isDark={isDark} activeColors={activeColors} />
        <TimeKnob value={m} max={60} onChange={(v) => updateTime('m', v)} label="MIN" isDark={isDark} activeColors={activeColors} />
        <TimeKnob value={s} max={60} onChange={(v) => updateTime('s', v)} label="SEC" isDark={isDark} activeColors={activeColors} />
      </div>
    </div>
  );
};

export const ToolsModal = ({ 
  activeTool, onClose, isMinimized, setIsMinimized, isDark, activeColors, appLang, addToast, onFileSelect
}) => {
  const [currentTab, setCurrentTab] = useState('youtube');

  // Cutter State
  const [subMode, setSubMode] = useState('cut');
  const [cutMode, setCutMode] = useState('manual'); 
  const [splitCount, setSplitCount] = useState(2); 
  const [splitResults, setSplitResults] = useState([]); 

  const [cutFile, setCutFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [startTime, setStartTime] = useState('00:00:00');
  const [endTime, setEndTime] = useState('00:00:10');
  const [mediaDuration, setMediaDuration] = useState(0); 
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [processProgress, setProcessProgress] = useState(0); // Visual Progress Bar

  // Joiner State
  const [joinFiles, setJoinFiles] = useState([]);

  // Converter State
  const [convertFile, setConvertFile] = useState(null);
  const [targetFormat, setTargetFormat] = useState('mp3');
  const [audioBitrate, setAudioBitrate] = useState('128k');
  const [audioChannels, setAudioChannels] = useState('2');
  const [convertedResult, setConvertedResult] = useState(null); // New state for result

  // Resizing State
  const [modalSize, setModalSize] = useState({ width: 1100, height: 850 });
  const [isMaximized, setIsMaximized] = useState(false);
  const isResizing = useRef(false);

  const cutFileInputRef = useRef(null);
  const joinFileInputRef = useRef(null);
  const convertFileInputRef = useRef(null);

  const mediaRef = useRef(null);

  const tabs = [
    { id: 'youtube', label: appLang === 'bn' ? 'ইউটিউব' : 'YouTube', icon: <path d="M19.615 3.184c-3.604-.246-11.631-.245-15.23 0-3.897.266-4.356 2.62-4.385 8.816.029 6.185.484 8.549 4.385 8.816 3.6.245 11.626.246 15.23 0 3.897-.266 4.356-2.62 4.385-8.816-.029-6.185-.484-8.549-4.385-8.816zm-10.615 12.816v-8l8 3.993-8 4.007z"/> },
    { id: 'facebook', label: appLang === 'bn' ? 'ফেসবুক' : 'Facebook', icon: <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z"/> },
    { id: 'converter', label: appLang === 'bn' ? 'কনভার্টার' : 'Converter', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" /> },
    { id: 'video_cut', label: appLang === 'bn' ? 'ভিডিও টুলস' : 'Video Tools', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"/> },
    { id: 'audio_cut', label: appLang === 'bn' ? 'অডিও টুলস' : 'Audio Tools', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3"/> }
  ];

  const isMediaTool = currentTab === 'video_cut' || currentTab === 'audio_cut';

  useEffect(() => {
    if (activeTool) {
      setCurrentTab(activeTool);
    }
  }, [activeTool]);

  // --- Simulated Progress ---
  useEffect(() => {
    if (isProcessing) {
        setProcessProgress(0);
        const interval = setInterval(() => {
            setProcessProgress(prev => {
                if (prev >= 90) return prev; // Stall at 90%
                // Faster at start, slower at end
                const increment = prev < 50 ? 5 : prev < 80 ? 2 : 0.5;
                return prev + increment;
            });
        }, 300);
        return () => clearInterval(interval);
    } else {
        setProcessProgress(0);
    }
  }, [isProcessing]);

  // --- SYNC PLAYER WITH TIME INPUTS ---
  const timeToSeconds = (timeStr) => {
    const parts = timeStr.split(':').map(Number);
    if (parts.length !== 3) return 0;
    return (parts[0] || 0) * 3600 + (parts[1] || 0) * 60 + (parts[2] || 0);
  };

  useEffect(() => {
    if (mediaRef.current && startTime && cutMode === 'manual') {
        mediaRef.current.currentTime = timeToSeconds(startTime);
    }
  }, [startTime, cutMode]);

  useEffect(() => {
    if (mediaRef.current && endTime && cutMode === 'manual') {
        mediaRef.current.currentTime = timeToSeconds(endTime);
    }
  }, [endTime, cutMode]);

  const handleMetadataLoaded = () => {
      if (mediaRef.current) {
          setMediaDuration(mediaRef.current.duration);
      }
  };

  // --- RESIZING LOGIC ---
  const startResizing = (e) => {
    e.preventDefault();
    isResizing.current = true;
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', stopResizing);
  };

  const handleMouseMove = (e) => {
    if (!isResizing.current) return;
    const modalElement = document.getElementById('tools-modal-container');
    if (modalElement) {
      const rect = modalElement.getBoundingClientRect();
      setModalSize({
        width: Math.max(600, e.clientX - rect.left),
        height: Math.max(500, e.clientY - rect.top)
      });
    }
  };

  const stopResizing = () => {
    isResizing.current = false;
    window.removeEventListener('mousemove', handleMouseMove);
    window.removeEventListener('mouseup', stopResizing);
  };

  if (!activeTool) return null;

  // --- CLEAR FUNCTIONS ---
  const clearConverterFile = (e) => {
      e.stopPropagation();
      setConvertFile(null);
      setConvertedResult(null);
      if (convertFileInputRef.current) convertFileInputRef.current.value = '';
  };

  const clearCutFile = (e) => {
      e.stopPropagation();
      setCutFile(null);
      setSplitResults([]);
      if (previewUrl) {
          URL.revokeObjectURL(previewUrl);
          setPreviewUrl(null);
      }
      if (cutFileInputRef.current) cutFileInputRef.current.value = '';
  };

  const clearJoinFiles = () => {
      setJoinFiles([]);
      if (joinFileInputRef.current) joinFileInputRef.current.value = '';
  };

  const handleDownloadSuccess = async (blob, fileName) => {
    setProcessProgress(100); // Complete visual progress
    try {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      addToast(appLang === 'bn' ? "ডাউনলোড শুরু হয়েছে" : "Download Started", "success");
    } catch (err) {
      console.log('Save cancelled or failed', err);
    }
  };

  const handleCutFileChange = (e) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          setCutFile(file);
          setSplitResults([]);
          if (previewUrl) URL.revokeObjectURL(previewUrl);
          setPreviewUrl(URL.createObjectURL(file));
      }
  };

  const handleResetTime = () => {
      setStartTime('00:00:00');
      setEndTime('00:00:10');
      addToast(appLang === 'bn' ? "সময় রিসেট হয়েছে" : "Time Reset", "info");
  };

  const secondsToTimestamp = (totalSeconds) => {
      const h = Math.floor(totalSeconds / 3600);
      const m = Math.floor((totalSeconds % 3600) / 60);
      const s = totalSeconds % 60;
      const hh = h.toString().padStart(2, '0');
      const mm = m.toString().padStart(2, '0');
      const ss = Math.floor(s).toString().padStart(2, '0');
      const ms = Math.round((s - Math.floor(s)) * 1000).toString().padStart(3, '0');
      return `${hh}:${mm}:${ss}.${ms}`;
  };

  const processCut = async () => {
      if (!cutFile) {
          addToast(appLang === 'bn' ? "ফাইল সিলেক্ট করুন" : "Select a file", 'error');
          return;
      }

      setIsProcessing(true);
      setSplitResults([]);

      try {
          if (cutMode === 'manual') {
              if (!startTime.match(/^\d{2}:\d{2}:\d{2}$/) || !endTime.match(/^\d{2}:\d{2}:\d{2}$/)) {
                  addToast(appLang === 'bn' ? "সঠিক সময় দিন (HH:MM:SS)" : "Invalid time format", 'error');
                  setIsProcessing(false);
                  return;
              }

              const formData = new FormData();
              formData.append('file', cutFile);
              formData.append('start', startTime);
              formData.append('end', endTime);

              const response = await fetch(getApiUrl('cut_media.php'), { method: 'POST', body: formData });

              if (!response.ok) {
                  throw new Error(`Server connection failed: ${response.status}`);
              }

              const text = await response.text();
              let result;
              try {
                  result = JSON.parse(text);
              } catch (e) {
                  throw new Error(`Server Error (Raw): ${text.substring(0, 100)}...`);
              }

              if (result.error) throw new Error(result.error);

              if (result.base64) {
                  const byteCharacters = atob(result.base64);
                  const byteNumbers = new Array(byteCharacters.length);
                  for (let i = 0; i < byteCharacters.length; i++) {
                      byteNumbers[i] = byteCharacters.charCodeAt(i);
                  }
                  const byteArray = new Uint8Array(byteNumbers);
                  const blob = new Blob([byteArray], { type: `video/${result.format}` });

                  await handleDownloadSuccess(blob, result.filename);
              }
          } else {
              if (!mediaDuration || mediaDuration <= 0) {
                  throw new Error("Invalid media duration");
              }

              const segmentDuration = mediaDuration / splitCount;
              const generatedFiles = [];

              for (let i = 0; i < splitCount; i++) {
                  setProcessingStatus(appLang === 'bn' ? `প্রসেসিং পার্ট ${i+1}/${splitCount}...` : `Processing Part ${i+1}/${splitCount}...`);

                  const startSec = i * segmentDuration;
                  const endSec = (i + 1) * segmentDuration;
                  const startStr = secondsToTimestamp(startSec);
                  const endStr = secondsToTimestamp(endSec);

                  const formData = new FormData();
                  formData.append('file', cutFile);
                  formData.append('start', startStr);
                  formData.append('end', endStr);

                  const response = await fetch(getApiUrl('cut_media.php'), { method: 'POST', body: formData });
                  if (!response.ok) throw new Error(`Server connection failed: ${response.status}`);

                  const text = await response.text();
                  let result;
                  try {
                      result = JSON.parse(text);
                  } catch (e) {
                      throw new Error(`Server Part Error: ${text.substring(0, 100)}...`);
                  }

                  if (result.error) throw new Error(`Part ${i+1} Failed: ${result.error}`);

                  if (result.base64) {
                      const byteCharacters = atob(result.base64);
                      const byteNumbers = new Array(byteCharacters.length);
                      for (let i = 0; i < byteCharacters.length; i++) {
                          byteNumbers[i] = byteCharacters.charCodeAt(i);
                      }
                      const byteArray = new Uint8Array(byteNumbers);
                      const blob = new Blob([byteArray], { type: `video/${result.format}` });

                      generatedFiles.push({
                          name: `Part_${i+1}_of_${splitCount}_${cutFile.name}`,
                          blob: blob
                      });
                  }
              }
              setSplitResults(generatedFiles);
              addToast(appLang === 'bn' ? "স্প্লিট সম্পন্ন হয়েছে" : "Split completed", 'success');
          }

      } catch (e) {
          console.error(e);
          addToast(appLang === 'bn' ? `ব্যর্থ: ${e.message}` : `Failed: ${e.message}`, 'error');
      } finally {
          setIsProcessing(false);
          setProcessingStatus('');
      }
  };

  const handleTranscribePart = (part) => {
      if (onFileSelect) {
          const file = new File([part.blob], part.name, { type: part.blob.type });
          onFileSelect(file);
          setIsMinimized(true);
          addToast(appLang === 'bn' ? "ট্রান্সক্রিপশন শুরু হচ্ছে... (টুলস মিনিমাইজড)" : "Starting transcription... (Tools Minimized)", 'info');
      }
  };

  const handleJoinFileChange = (e) => {
      if (e.target.files && e.target.files.length > 0) {
          setJoinFiles(prev => [...prev, ...Array.from(e.target.files || [])]);
      }
  };

  const removeJoinFile = (index) => {
      setJoinFiles(prev => prev.filter((_, i) => i !== index));
  };

  const processJoin = async () => {
      if (joinFiles.length < 2) {
          addToast(appLang === 'bn' ? "কমপক্ষে ২টি ফাইল প্রয়োজন" : "Need at least 2 files", 'warning');
          return;
      }

      setIsProcessing(true);
      const formData = new FormData();
      joinFiles.forEach((file) => {
          formData.append('files[]', file);
      });

      try {
          const response = await fetch(getApiUrl('join_media.php'), {
              method: 'POST',
              body: formData
          });
          if (!response.ok) throw new Error(`Server connection failed: ${response.status}`);

          const text = await response.text();
          let result;
          try {
              result = JSON.parse(text);
          } catch (e) {
              throw new Error(`Server Error: ${text.substring(0, 100)}...`);
          }

          if (result.error) throw new Error(result.error);

          if (result.base64) {
              const byteCharacters = atob(result.base64);
              const byteNumbers = new Array(byteCharacters.length);
              for (let i = 0; i < byteCharacters.length; i++) {
                  byteNumbers[i] = byteCharacters.charCodeAt(i);
              }
              const byteArray = new Uint8Array(byteNumbers);
              const blob = new Blob([byteArray], { type: `video/${result.format}` });

              await handleDownloadSuccess(blob, result.filename);
              setJoinFiles([]); 
          }
      } catch (e) {
          console.error(e);
          addToast(appLang === 'bn' ? `জয়েনিং ব্যর্থ: ${e.message}` : `Joining failed: ${e.message}`, 'error');
      } finally {
          setIsProcessing(false);
      }
  };

  const handleConverterFileChange = (e) => {
      if (e.target.files && e.target.files[0]) {
          setConvertFile(e.target.files[0]);
          setConvertedResult(null); // Reset previous result
      }
  };

  const processConvert = async () => {
      if (!convertFile) {
          addToast(appLang === 'bn' ? "ফাইল সিলেক্ট করুন" : "Select a file", 'error');
          return;
      }

      setIsProcessing(true);
      setConvertedResult(null);

      const formData = new FormData();
      formData.append('file', convertFile);
      formData.append('format', targetFormat);
      formData.append('bitrate', audioBitrate);
      formData.append('channels', audioChannels);

      try {
          const response = await fetch(getApiUrl('convert_media.php'), {
              method: 'POST',
              body: formData
          });
          if (!response.ok) throw new Error(`Server connection failed: ${response.status}`);

          const text = await response.text();
          let result;
          try {
              result = JSON.parse(text);
          } catch (e) {
              throw new Error(`Server Error: ${text.substring(0, 100)}...`);
          }

          if (result.error) throw new Error(result.error);

          if (result.base64) {
              const byteCharacters = atob(result.base64);
              const byteNumbers = new Array(byteCharacters.length);
              for (let i = 0; i < byteCharacters.length; i++) {
                  byteNumbers[i] = byteCharacters.charCodeAt(i);
              }
              const byteArray = new Uint8Array(byteNumbers);

              let mime = 'application/octet-stream';
              if (['mp3', 'wav', 'ogg', 'm4a', 'aac', 'opus'].includes(result.format)) mime = `audio/${result.format}`;
              else if (['mp4', 'webm', 'mkv', 'avi'].includes(result.format)) mime = `video/${result.format}`;

              const blob = new Blob([byteArray], { type: mime });

              setConvertedResult({blob, name: result.filename});
              await handleDownloadSuccess(blob, result.filename);
              addToast(appLang === 'bn' ? "কনভার্ট সফল হয়েছে" : "Conversion successful", 'success');
          }
      } catch (e) {
          console.error(e);
          addToast(appLang === 'bn' ? `কনভার্ট ব্যর্থ: ${e.message}` : `Conversion failed: ${e.message}`, 'error');
      } finally {
          setIsProcessing(false);
      }
  };

  // Reusable Processing UI
  const renderProcessingState = (status) => (
      <div className="w-full flex flex-col gap-3 animate-in fade-in zoom-in duration-300">
          <div className="h-10 bg-slate-100 dark:bg-black/20 rounded-xl overflow-hidden relative shadow-inner border border-slate-200 dark:border-white/10">
              <div 
                  className={`h-full ${activeColors.primary} transition-all duration-300 relative`}
                  style={{ width: `${processProgress}%` }}
              >
                  <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite]"></div>
              </div>
              <div className="absolute inset-0 flex items-center justify-center">
                  <span className={`text-[10px] font-black uppercase tracking-widest ${isDark ? 'text-white' : 'text-slate-800'} drop-shadow-md`}>
                      {status} {Math.round(processProgress)}%
                  </span>
              </div>
          </div>
          <p className="text-center text-[9px] opacity-50 font-bold uppercase animate-pulse">
              {appLang === 'bn' ? 'দয়া করে অপেক্ষা করুন, সার্ভারে কাজ চলছে...' : 'Please wait, processing on server...'}
          </p>
      </div>
  );

  return (
    <>
      {/* Minimized Floating Widget - Visible ONLY when isMinimized is true */}
      <div className={`fixed bottom-24 right-20 z-[100] animate-in slide-in-from-bottom-10 fade-in duration-300 ${isMinimized ? 'block' : 'hidden'}`}>
           <div 
             onClick={() => setIsMinimized(false)}
             className={`flex items-center gap-4 px-6 py-4 rounded-2xl shadow-2xl border cursor-pointer hover:scale-105 transition-transform group ${isDark ? 'bg-slate-900 border-white/20 text-white' : 'bg-white border-slate-200 text-slate-900'}`}
           >
              <div className={`w-10 h-10 rounded-xl ${activeColors.primary} flex items-center justify-center text-white shadow-lg animate-pulse`}>
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
              </div>
              <div className="flex flex-col">
                 <span className="text-[10px] font-black uppercase tracking-widest opacity-60">{appLang === 'bn' ? 'টুলস মিনিমাইজড' : 'TOOLS ACTIVE'}</span>
                 <span className="text-xs font-bold">{appLang === 'bn' ? 'ক্লিক করে খুলুন' : 'Click to Maximize'}</span>
              </div>
              <div className="w-8 h-8 rounded-full bg-black/10 flex items-center justify-center ml-2">
