                                disabled={isProcessing}
                                className={`w-full py-4 ${activeColors.primary} text-white rounded-xl text-xs font-black uppercase tracking-[0.2em] shadow-xl hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50`}
                                >
                                <span>{appLang === 'bn' ? 'প্রসেস শুরু করুন' : 'START PROCESS'}</span>
                                </button>
                            )}
