                    )}

                    {subMode === 'join' && (
                        <div className="space-y-6">
                            <input type="file" ref={joinFileInputRef} onChange={handleJoinFileChange} className="hidden" multiple accept={currentTab === 'video_cut' ? 'video/*' : 'audio/*'} />
                            <div className="space-y-3">
                                <div className="flex justify-between items-center mb-2">
                                    <div className="flex items-center gap-3">
                                        <label className="text-[10px] font-black uppercase tracking-widest opacity-50">{appLang === 'bn' ? 'ফাইল লিস্ট' : 'File List'}</label>
                                        {joinFiles.length > 0 && (
                                            <button 
                                              onClick={clearJoinFiles}
                                              className="text-[9px] font-bold text-red-500 hover:text-red-600 uppercase flex items-center gap-1"
                                            >
                                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                                                CLEAR ALL
                                            </button>
                                        )}
                                    </div>
                                    <button onClick={() => joinFileInputRef.current?.click()} className="px-3 py-1.5 bg-indigo-600 text-white rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-indigo-700">+ {appLang === 'bn' ? 'যোগ করুন' : 'ADD FILES'}</button>
                                </div>
                                <div className={`min-h-[120px] max-h-[300px] overflow-y-auto custom-scrollbar rounded-2xl border ${isDark ? 'bg-black/20 border-white/10' : 'bg-white border-slate-200'} p-2 space-y-2`}>
                                    {joinFiles.length === 0 ? (
                                        <div className="h-full flex flex-col items-center justify-center opacity-30 min-h-[120px]"><p className="text-[10px] font-bold uppercase">NO FILES SELECTED</p></div>
                                    ) : (
                                        joinFiles.map((file, idx) => (
                                            <div key={idx} className={`p-3 rounded-xl flex items-center justify-between group ${isDark ? 'bg-white/5 hover:bg-white/10' : 'bg-slate-50 hover:bg-slate-100'}`}>
                                                <div className="flex items-center gap-3 overflow-hidden">
                                                    <div className="w-5 h-5 bg-indigo-500 rounded-full flex items-center justify-center text-[10px] text-white font-bold shrink-0">{idx + 1}</div>
                                                    <span className="text-xs font-bold truncate max-w-[200px]">{file.name}</span>
                                                </div>
                                                <button onClick={() => removeJoinFile(idx)} className="text-red-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"/></svg></button>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </div>
                            {isProcessing ? renderProcessingState(appLang === 'bn' ? 'মার্জ হচ্ছে...' : 'MERGING FILES...') : (
                                <button onClick={processJoin} disabled={isProcessing || joinFiles.length < 2} className={`w-full py-4 ${activeColors.primary} text-white rounded-xl text-xs font-black uppercase tracking-[0.2em] shadow-xl hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50`}>
                                {appLang === 'bn' ? 'মার্জ শুরু করুন' : 'MERGE FILES'}
                                </button>
                            )}
                        </div>
                    )}
                 </div>
              </div>
            )}
          </div>
        </div>
        {!isMaximized && (
            <div onMouseDown={startResizing} className="absolute bottom-2 right-2 w-10 h-10 cursor-nwse-resize flex items-center justify-center opacity-20 hover:opacity-100 transition-opacity z-[200]"><svg className="w-6 h-6 text-slate-400 rotate-90" fill="currentColor" viewBox="0 0 24 24"><path d="M22 22h-2v-2h2v2zm0-4h-2v-2h2v2zm-4 4h-2v-2h2v2zm0-4h-2v-2h2v2zm-4 4h-2v-2h2v2zm8-8h-2v-2h2v2zm-12 8h-2v-2h2v2z"/></svg></div>
        )}
      </div>
      </div>
    </>
  );
};

