interface Toast {
  id: number;
  msg: string;
  type: 'success' | 'error' | 'info' | 'warning';
}

const App: React.FC = () => {
  // State definitions
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isInformationOpen, setIsInformationOpen] = useState(false);
  const [isActivityLogOpen, setIsActivityLogOpen] = useState(false);
  const [isReportOpen, setIsReportOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeTool, setActiveTool] = useState<string | null>(null);

  const [theme, setTheme] = useState('default'); // 'default' or 'soft-dark'
  const [appLang, setAppLang] = useState<'bn' | 'en'>('bn');

  const [status, setStatus] = useState<'idle' | 'processing' | 'completed' | 'error'>('idle');
  const [transcript, setTranscript] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  const [file, setFile] = useState<File | null>(null);
  const [fileUrl, setFileUrl] = useState<string | null>(null);
  const [fileMeta, setFileMeta] = useState<any>({});

  const [history, setHistory] = useState<any[]>([]);
  const [isHistoryFullscreen, setIsHistoryFullscreen] = useState(false);
  const [activeHistoryId, setActiveHistoryId] = useState<string | null>(null);

  // History Search & Filter
  const [histSearch, setHistSearch] = useState('');
  const [histDateFilter, setHistDateFilter] = useState('');

  // Audio Player & Sync
  const audioRef = useRef<HTMLAudioElement>(null);
  const [audioCurrentTime, setAudioCurrentTime] = useState(0);

  // Search within transcript
  const [searchTerm, setSearchTerm] = useState('');
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [matchCount, setMatchCount] = useState(0);
  const transcriptSearchInputRef = useRef<HTMLInputElement>(null);

  // UI Customization
  const [fontSize, setFontSize] = useState(16);
  const [scrollPercent, setScrollPercent] = useState(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Recorder
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordIntervalRef = useRef<number | null>(null);

  // API Stats
  const [totalApiCalls, setTotalApiCalls] = useState(0);
  const [activeApiKeySource, setActiveApiKeySource] = useState('Checking...');
  const [activeModelName, setActiveModelName] = useState('Loading...');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Processing View
  const [progress, setProgress] = useState(0);
  const [currentStage, setCurrentStage] = useState('');
  const [elapsedSeconds, setElapsedSeconds] = useState(0);
  const [estimatedSeconds, setEstimatedSeconds] = useState(0);

  // Transformations
  const [transformingType, setTransformingType] = useState<'translate' | 'encoding' | null>(null);

  // Toast State
  const [toasts, setToasts] = useState<Toast[]>([]);

  // Derived
  const isDark = theme === 'soft-dark';
  const t = translations[appLang];

  const activeColors = isDark ? {
    primary: 'bg-indigo-600',
    text: 'text-indigo-400',
    border: 'border-indigo-500/50',
    soft: 'bg-indigo-900/20',
    ring: 'ring-indigo-500'
  } : {
    primary: 'bg-indigo-600',
    text: 'text-indigo-600',
    border: 'border-indigo-200',
    soft: 'bg-indigo-50',
    ring: 'ring-indigo-200'
  };

  const mainBgColor = isDark ? 'bg-slate-900' : 'bg-slate-50';
  const textColor = isDark ? 'text-white' : 'text-slate-800';
  const cardBg = isDark ? 'bg-white/5 backdrop-blur-md' : 'bg-white';
  const cardBorder = isDark ? 'border-white/10' : 'border-slate-100';
  const subTextColor = isDark ? 'text-slate-400' : 'text-slate-500';

  useEffect(() => {
    loadHistory();
    updateApiStats();

    const handleTimeUpdate = () => {
      if (audioRef.current) {
        setAudioCurrentTime(audioRef.current.currentTime);
      }
    };
    const audioEl = audioRef.current;
    if (audioEl) {
      audioEl.addEventListener('timeupdate', handleTimeUpdate);
    }
    return () => {
      if (audioEl) audioEl.removeEventListener('timeupdate', handleTimeUpdate);
    };
  }, [fileUrl]);

  const loadHistory = async () => {
    const data = await getAllFromStore(STORES.HISTORY);
    setHistory(data.sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };

  const updateApiStats = async () => {
    const calls = await getTotalCalls();
    setTotalApiCalls(calls);
    const provider = await getActiveProvider();
    if (provider) {
      setActiveApiKeySource(provider.source);
      setActiveModelName(provider.model);
    } else {
      setActiveApiKeySource('None');
      setActiveModelName('None');
    }
  };

  const handleFileChange = async (e: any, autoStart = false) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    setFile(selectedFile);
    const url = URL.createObjectURL(selectedFile);
    setFileUrl(url);
    setActiveHistoryId(null);

    const audio = new Audio(url);
    audio.onloadedmetadata = () => {
      const duration = audio.duration;
      const mins = Math.floor(duration / 60);
      const secs = Math.floor(duration % 60);
      setFileMeta({
        name: selectedFile.name,
        size: (selectedFile.size / 1024 / 1024).toFixed(2) + ' MB',
        duration: `${mins}:${secs.toString().padStart(2, '0')}`,
        type: selectedFile.type
      });
      if (autoStart) {
        processTranscription(selectedFile);
      }
    };
  };

  const resetAll = () => {
    setFile(null);
    setFileUrl(null);
    setFileMeta({});
    setTranscript('');
    setStatus('idle');
    setActiveHistoryId(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const fileInputRef = useRef<HTMLInputElement>(null);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      const chunks: BlobPart[] = [];

      mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/mp3' });
        const file = new File([blob], `Recording_${new Date().toLocaleTimeString()}.mp3`, { type: 'audio/mp3' });
        handleFileChange({ target: { files: [file] } });
        setIsRecording(false);
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      recordIntervalRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (e) {
      console.error("Mic Access Error", e);
      addToast(appLang === 'bn' ? "মাইক্রোফোন এক্সেস পাওয়া যায়নি" : "Microphone access denied", 'error');
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      if (recordIntervalRef.current) clearInterval(recordIntervalRef.current);
    }
  };

  const processTranscription = async (inputFile = file) => {
    if (!inputFile) return;
    setStatus('processing');
    setProgress(0);
    setElapsedSeconds(0);
    setEstimatedSeconds(30);
    setCurrentStage(appLang === 'bn' ? 'অডিও প্রসেসিং হচ্ছে...' : 'Processing Audio...');

    const timer = setInterval(() => {
      setElapsedSeconds(s => s + 1);
      setProgress(p => Math.min(p + (100 / 30), 95));
    }, 1000);

    try {
      const base64Data = await fileToBase64(inputFile);
      const checkProvider = await getActiveProvider();

      if (!checkProvider) {
        throw new Error("No API Key configured. Please add one in Settings.");
      }

      setCurrentStage(appLang === 'bn' ? 'এআই জেনারেশন চলছে...' : 'AI Generation...');

      const ai = new GoogleGenAI({ apiKey: checkProvider.key });
      const mimeType = inputFile.type || 'audio/mp3';

      const response = await ai.models.generateContent({
          model: checkProvider.model || 'gemini-3-flash-preview', 
          contents: { 
              role: 'user',
              parts: [
                  { inlineData: { mimeType: mimeType, data: base64Data as string } }, 
                  { text: "Listen to the audio carefully. Regardless of the spoken language (English, Hindi, Urdu, etc.), transcribe and translate the content directly into standard Bengali (Bangla) script. The final output MUST be in Bangla. STRICT FORMAT: Start every new minute or speaker change with a timestamp [MM:SS]. Example: [00:00] **Speaker 1:** বাংলা টেক্সট... If no speech detected, output [Silence]." }
              ] 
          },
          config: {
              temperature: 0.1, 
              safetySettings: [
                  { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_NONE' },
                  { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_NONE' },
                  { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_NONE' },
                  { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_NONE' },
              ]
          }
      });

      await incrementTotalCalls('Transcription', checkProvider.model || 'gemini-3-flash-preview', checkProvider.source);
      updateApiStats();

      const text = response.text;
      if (!text) throw new Error("Empty response from AI");

      setTranscript(text);
      setStatus('completed');

      const historyItem = {
        id: Date.now().toString(),
        fileName: inputFile.name,
        date: new Date().toISOString(),
        duration: fileMeta.duration || '00:00',
        transcript: text,
        extension: inputFile.name.split('.').pop(),
        timeTaken: `${elapsedSeconds}s`
      };
      await addToStore(STORES.HISTORY, historyItem);
      loadHistory();
      logSystemActivity('TRANSCRIPTION', 'SUCCESS', 'File Transcribed', `File: ${inputFile.name}`);

    } catch (error: any) {
      console.error(error);
      setStatus('error');
      setErrorMessage(error.message || "Unknown error occurred");
      logSystemActivity('TRANSCRIPTION', 'ERROR', 'Failed', error.message);
    } finally {
      clearInterval(timer);
      setProgress(100);
    }
  };

  const addToast = (msg: string, type: 'success' | 'error' | 'info' | 'warning') => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, msg, type }]);

    // Auto dismiss
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  const removeToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const handleScroll = () => {
    if (scrollContainerRef.current) {
      const { scrollTop, scrollHeight, clientHeight } = scrollContainerRef.current;
      const percent = Math.round((scrollTop / (scrollHeight - clientHeight)) * 100);
      setScrollPercent(percent);
    }
  };

  const scrollToTop = () => scrollContainerRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
  const scrollToBottom = () => scrollContainerRef.current?.scrollTo({ top: scrollContainerRef.current.scrollHeight, behavior: 'smooth' });

  const handleDeleteHistoryItem = async (id: string) => {
    await deleteFromStore(STORES.HISTORY, id);
    if (activeHistoryId === id) {
        setActiveHistoryId(null);
        setTranscript('');
        setStatus('idle');
    }
    loadHistory();
    addToast(appLang === 'bn' ? 'ডিলিট করা হয়েছে' : 'Deleted', 'warning');
  };

  const handleSeek = (time: string) => {
    if (!audioRef.current) return;
    const parts = time.split(/[-:]/).map(s => s.trim()).filter(s => s);
    // Simple check if it matches MM:SS or HH:MM:SS, taking first part if range
    const target = parts.length > 0 ? parts.slice(0, 3).join(':') : "00:00"; 

    // Convert target to seconds
    const tParts = target.split(':').map(Number);
    let seconds = 0;
    if (tParts.length === 2) seconds = tParts[0] * 60 + tParts[1];
    else if (tParts.length === 3) seconds = tParts[0] * 3600 + tParts[1] * 60 + tParts[2];

    audioRef.current.currentTime = seconds;
    audioRef.current.play();
  };

  const handleTransformTranscript = async (type: 'translate' | 'encoding') => {
    if (!transcript) return;
    setTransformingType(type);

    try {
        const provider = await getActiveProvider();
        if (!provider) throw new Error("No API Key");

        const ai = new GoogleGenAI({ apiKey: provider.key });
        let prompt = "";

        if (type === 'translate') {
            prompt = `Translate the following text to ${appLang === 'bn' ? 'English' : 'Bengali'}. Maintain original formatting and timestamps.\n\n${transcript}`;
        } else {
            prompt = `Convert the following text to Bijoy encoding if it is Unicode, or Unicode if it is Bijoy. Maintain timestamps.\n\n${transcript}`;
        }

        const response = await ai.models.generateContent({
            model: provider.model,
            contents: prompt
        });

        await incrementTotalCalls('Transformation', provider.model, provider.source);
        updateApiStats();

        if (response.text) {
            setTranscript(response.text);
            addToast("Transformation Complete", "success");
        }
    } catch (e: any) {
        addToast("Transformation Failed", "error");
    } finally {
        setTransformingType(null);
    }
  };

  // Filter History for Expanded View
  const filteredHistory = history.filter(item => {
    const matchesSearch = (item.fileName || '').toLowerCase().includes(histSearch.toLowerCase()) || 
                          (item.transcript || '').toLowerCase().includes(histSearch.toLowerCase());
    const matchesDate = histDateFilter ? item.date.startsWith(histDateFilter) : true;
    return matchesSearch && matchesDate;
  });

  return (
    <div className={`flex h-screen overflow-hidden ${mainBgColor} ${textColor} font-sans selection:bg-indigo-500/30`}>
      <SpiderWebBackground opacity={isDark ? "opacity-[0.09]" : "opacity-[0.05]"} />

      {/* Toast Container */}
      <div className="fixed top-24 right-5 z-[250] flex flex-col gap-3 pointer-events-none">
        {toasts.map(toast => (
          <div 
            key={toast.id} 
            className={`pointer-events-auto px-6 py-4 rounded-xl shadow-2xl border backdrop-blur-md animate-in slide-in-from-right-10 fade-in duration-300 flex items-center gap-4 min-w-[300px] ${
              toast.type === 'success' ? 'bg-emerald-500/90 border-emerald-400 text-white' :
              toast.type === 'error' ? 'bg-red-500/90 border-red-400 text-white' :
              toast.type === 'warning' ? 'bg-amber-500/90 border-amber-400 text-white' :
              'bg-blue-500/90 border-blue-400 text-white'
            }`}
          >
            <div className="bg-white/20 p-2 rounded-full">
              {toast.type === 'success' && <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"/></svg>}
              {toast.type === 'error' && <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12"/></svg>}
              {toast.type === 'warning' && <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>}
              {toast.type === 'info' && <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>}
            </div>
            <div className="flex-1">
              <p className="text-sm font-black uppercase tracking-wide">{toast.type}</p>
              <p className="text-xs font-medium opacity-90">{toast.msg}</p>
            </div>
            <button onClick={() => removeToast(toast.id)} className="hover:bg-white/20 p-1 rounded-lg transition-colors">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
            </button>
          </div>
        ))}
      </div>

      <Sidebar 
        t={t}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
        sidebarSide="left"
        bgColor={isDark ? 'bg-slate-900/50 backdrop-blur-xl' : 'bg-white/80 backdrop-blur-xl'}
        activeColors={activeColors}
        cardBg={cardBg}
        cardBorder={cardBorder}
        isDark={isDark}
        subTextColor={subTextColor}
        fileInputRef={fileInputRef}
        handleFileChange={handleFileChange}
        fileUrl={fileUrl}
        resetAll={resetAll}
        fileMeta={fileMeta}
        audioRef={audioRef}
        processTranscription={() => processTranscription(file)}
        status={status}
        history={history}
        setIsHistoryFullscreen={setIsHistoryFullscreen}
        groupHistory={(items) => {
           const groups: any = {};
           items.forEach(item => {
             const d = new Date(item.date).toLocaleDateString();
             if (!groups[d]) groups[d] = [];
             groups[d].push(item);
           });
           return groups;
        }}
        loadHistoryItem={(item) => {
           setTranscript(item.transcript);
           setStatus('completed');
           setFileMeta({ name: item.fileName, duration: item.duration });
           setFileUrl(null); 
           setActiveHistoryId(item.id);
        }}
        appLang={appLang}
        isRecording={isRecording}
        recordingTime={recordingTime}
        onStartRecording={startRecording}
        onStopRecording={stopRecording}
        activeHistoryId={activeHistoryId}
        onDeleteHistoryItem={handleDeleteHistoryItem}
