          setActiveTool={setActiveTool}
          setIsReportOpen={setIsReportOpen}
        />

        <TranscriptOutput 
          t={t}
          status={status}
          isSearchExpanded={true}
          setIsSearchExpanded={() => {}}
          transcriptSearchInputRef={transcriptSearchInputRef}
          searchTerm={searchTerm}
          handleSearchChange={(e) => setSearchTerm(e.target.value)}
          activeColors={activeColors}
          downloadText={() => {}}
          setStatus={setStatus}
          setTranscript={setTranscript}
          mainBgColor={mainBgColor}
          fileUrl={fileUrl}
          textColor={textColor}
          isDark={isDark}
          setIsSidebarOpen={setIsSidebarOpen}
          fileMeta={fileMeta}
          processTranscription={() => processTranscription(file)}
          scrollContainerRef={scrollContainerRef}
          handleScroll={handleScroll}
          transcriptCardBg={cardBg}
          cardBorder={cardBorder}
          renderFormattedTranscript={(text) => text}
          transcript={transcript}
          showScrollTop={scrollPercent > 5}
          scrollToTop={scrollToTop}
          showScrollBottom={scrollPercent < 95}
          scrollToBottom={scrollToBottom}
          fontSize={fontSize}
          setFontSize={setFontSize}
          matchCount={matchCount}
          currentMatchIndex={currentMatchIndex}
          goToNextMatch={() => {}}
          goToPrevMatch={() => {}}
          errorMessage={errorMessage}
          addToast={addToast}
          appLang={appLang}
          history={history}
          progress={progress}
          currentStage={currentStage}
          elapsedSeconds={elapsedSeconds}
          estimatedSeconds={estimatedSeconds}
          audioCurrentTime={audioCurrentTime}
          activeTranscriptSourceMeta={fileMeta}
          transformTranscript={handleTransformTranscript}
          transformingType={transformingType}
          onSeek={handleSeek}
          onModelUpdate={updateApiStats}
          setIsAiLoading={setIsAiLoading}
          setActiveHistoryId={setActiveHistoryId}
        />

        <Footer 
          t={t}
          activeColors={activeColors}
          activeApiKeySource={activeApiKeySource}
          activeModelName={activeModelName}
          totalApiCalls={totalApiCalls}
          isAiLoading={isAiLoading}
          appLang={appLang}
          isDark={isDark}
          onOpenSettings={() => setIsSettingsOpen(true)}
        />
      </div>

      {isHistoryFullscreen && (
        <ExpandedHistory 
          t={t}
          isDark={isDark}
          setIsHistoryFullscreen={setIsHistoryFullscreen}
          histSearch={histSearch}
          setHistSearch={setHistSearch}
          histDateFilter={histDateFilter}
          setHistDateFilter={setHistDateFilter}
          filteredHistory={filteredHistory}
          loadHistoryItem={(item) => {
             setTranscript(item.transcript);
             setStatus('completed');
             setFileMeta({ name: item.fileName, duration: item.duration });
             setFileUrl(null); 
             setActiveHistoryId(item.id);
             setIsHistoryFullscreen(false);
          }}
          activeColors={activeColors}
        />
