      <InformationModal 
        isOpen={isInformationOpen}
        onClose={() => setIsInformationOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
        addToast={addToast}
      />

      <ToolsModal 
        activeTool={activeTool}
        onClose={() => setActiveTool(null)}
        isMinimized={false}
        setIsMinimized={() => {}}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
        addToast={addToast}
        onFileSelect={(f) => handleFileChange({ target: { files: [f] } }, true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
        addToast={addToast}
      />

      <ActivityLogsModal 
        isOpen={isActivityLogOpen}
        onClose={() => setIsActivityLogOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
      />

      <TranscriberReportModal 
        isOpen={isReportOpen}
        onClose={() => setIsReportOpen(false)}
        isDark={isDark}
        activeColors={activeColors}
        appLang={appLang}
      />

      {/* 
      <ChatBot 
        activeColors={activeColors}
        isDark={isDark}
        appLang={appLang}
        addToast={addToast}
      /> 
      */}
    </div>
  );
};

