import React, { useState, useMemo, useEffect } from 'react';
import { DownloadMenu } from '../../components/common/DownloadMenu.tsx';
import { SummaryModal } from '../../SummaryModal.tsx';
import { ReportModal } from '../../ReportModal.tsx';
import { FullscreenAnalysis } from '../../FullscreenAnalysis.tsx';
import { ProcessingView } from './ProcessingView.tsx';

export const TranscriptOutput = ({
  t, status, isSearchExpanded, setIsSearchExpanded, transcriptSearchInputRef, searchTerm,
  handleSearchChange, activeColors, downloadText, setStatus, setTranscript,
  mainBgColor, fileUrl, textColor, isDark, setIsSidebarOpen, fileMeta, processTranscription,
  scrollContainerRef, handleScroll, transcriptCardBg, cardBorder, renderFormattedTranscript, transcript,
  showScrollTop, scrollToTop, showScrollBottom, scrollToBottom, fontSize, setFontSize,
  matchCount, currentMatchIndex, goToNextMatch, goToPrevMatch, errorMessage, 
  transformTranscript, transformingType, scrollPercent = 0, addToast, appLang, history, onSeek, onModelUpdate, setIsAiLoading,
  audioCurrentTime = 0, activeTranscriptSourceMeta,
  progress = 0, currentStage = '', elapsedSeconds = 0, estimatedSeconds = 0,
  setActiveHistoryId
}) => {
  const [isSummaryOpen, setIsSummaryOpen] = useState(false);
  const [isReportOpen, setIsReportOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [isKaraokeEnabled, setIsKaraokeEnabled] = useState(true);

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && searchTerm) {
      e.preventDefault();
      goToNextMatch();
    }
  };

  const clearSearch = () => {
    handleSearchChange({ target: { value: '' } });
    transcriptSearchInputRef.current?.focus();
  };

  const handleSummaryClick = () => {
    setIsSummaryOpen(true);
  };

  const isDisabled = status !== 'completed';

  // --- SYNCED HIGHLIGHTING LOGIC ---

  const isSynced = useMemo(() => {
    if (!fileUrl || !transcript || !activeTranscriptSourceMeta) return false;
    return fileMeta.name === activeTranscriptSourceMeta.name && 
           fileMeta.size === activeTranscriptSourceMeta.size;
  }, [fileUrl, transcript, activeTranscriptSourceMeta, fileMeta]);

  const transcriptSegments = useMemo(() => {
    if (!transcript || !isSynced) return [];

    const regex = /\[(\d{1,2}):(\d{2})\]/g;
    const toSeconds = (m, s) => parseInt(m) * 60 + parseInt(s);
    const parts = transcript.split(/(\[\d{1,2}:\d{2}\])/g); 

    const finalSegments = [];

    for (let i = 1; i < parts.length; i += 2) {
        const timeMatch = parts[i].match(/\[(\d{1,2}):(\d{2})\]/);
        if (timeMatch) {
            const time = toSeconds(timeMatch[1], timeMatch[2]);
            const textContent = parts[i+1] || "";

            if (finalSegments.length > 0) {
                finalSegments[finalSegments.length - 1].end = time;
            }

            if (textContent.trim()) {
                finalSegments.push({
                    start: time,
                    end: time + 60, 
                    text: textContent,
                    originalText: parts[i] + textContent
                });
            }
        }
    }
    return finalSegments;
  }, [transcript, isSynced]);

  // Sync scroll to audio
  useEffect(() => {
    if (isSynced && isKaraokeEnabled && status === 'completed') {
        const activeEl = document.getElementById('active-transcript-segment');
        if (activeEl) {
            activeEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    }
  }, [Math.floor(audioCurrentTime), isSynced, status, isKaraokeEnabled]);

  // Sync scroll to Search Match
  useEffect(() => {
    if (matchCount > 0 && searchTerm) {
      const activeId = `match-${currentMatchIndex}`;
      const element = document.getElementById(activeId);
      if (element) {
        element.scrollIntoView({
          behavior: 'smooth',
          block: 'center',
          inline: 'center'
        });
      }
    }
  }, [currentMatchIndex, matchCount, searchTerm]);

  // Robust Regex Escaping
  const escapeRegExp = (string) => {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  };

  const renderSyncedTranscript = () => {
      let karaokeMatchIndex = 0; 

      return (
          <div className="space-y-4">
              {transcriptSegments.map((seg, idx) => {
                  const isActive = audioCurrentTime >= seg.start && audioCurrentTime < seg.end;
                  return (
                      <div 
                        key={idx} 
                        id={isActive ? 'active-transcript-segment' : undefined}
                        className={`transition-all duration-300 rounded-xl p-3 border-l-4 ${
                            isActive 
                            ? (isDark ? 'bg-indigo-500/20 border-indigo-400 shadow-lg scale-[1.01]' : 'bg-yellow-100 border-yellow-500 shadow-md scale-[1.01]') 
                            : 'border-transparent hover:bg-black/5 dark:hover:bg-white/5'
                        }`}
                      >
                          <div style={{ fontSize: `${fontSize}px` }} className="leading-relaxed whitespace-pre-wrap">
                              <span className="opacity-50 text-[0.7em] font-mono mr-2 select-none">
                                  {`[${Math.floor(seg.start / 60).toString().padStart(2, '0')}:${(seg.start % 60).toString().padStart(2, '0')}]`}
                              </span>
                              {seg.text.split(/(\*\*.*?\*\*)/g).map((part, j) => {
                                  if (part.startsWith('**') && part.endsWith('**')) {
                                      return <strong key={j} className={isDark ? 'text-indigo-300' : 'text-indigo-800'}>{part.slice(2, -2)}</strong>;
                                  }

                                  // --- Search Highlighting Logic ---
                                  if (!searchTerm || !searchTerm.trim()) {
                                      return <span key={j} className={isActive ? (isDark ? 'text-white font-medium' : 'text-black font-medium') : ''}>{part}</span>;
                                  }

                                  const escapedSearchTerm = escapeRegExp(searchTerm.trim());
                                  // Use 'gu' for global unicode matching
                                  const regex = new RegExp(`(${escapedSearchTerm})`, 'giu'); 
                                  const subParts = part.split(regex);

                                  return (
                                      <span key={j} className={isActive ? (isDark ? 'text-white font-medium' : 'text-black font-medium') : ''}>
                                          {subParts.map((sub, k) => {
                                              if (sub.toLowerCase() === searchTerm.trim().toLowerCase()) {
                                                  const id = `match-${karaokeMatchIndex}`;
                                                  const isCurrent = karaokeMatchIndex === currentMatchIndex;
                                                  karaokeMatchIndex++;
                                                  return (
                                                      <mark 
                                                        key={k}
                                                        id={id}
                                                        className={`${isCurrent ? 'bg-orange-500 text-white' : 'bg-yellow-400 text-black'} font-bold px-0.5 rounded transition-all duration-300`}
                                                      >
                                                          {sub}
                                                      </mark>
                                                  );
                                              }
                                              return sub;
                                          })}
                                      </span>
                                  );
                                  // --------------------------------
                              })}
                          </div>
                      </div>
                  );
              })}
          </div>
      );
  };

  // Re-implemented renderFormattedTranscript for better search support
  const renderFormattedTranscriptInternal = (text) => {
    if (!text) return null;
    let localMatchIndex = 0;

    return text.split('\n').map((line, i) => {
      const parts = line.split(/(\*\*.*?\*\*)/g);
      return (
        <div key={i} className="mb-2 min-h-[1.5em] leading-relaxed">
           {parts.map((part, j) => {
              if (part.startsWith('**') && part.endsWith('**')) {
                  return <strong key={j} className={isDark ? 'text-indigo-400' : 'text-indigo-700'}>{part.slice(2, -2)}</strong>;
              }

              if (!searchTerm || !searchTerm.trim()) {
                  return <span key={j}>{part}</span>;
              }

              const escapedTerm = escapeRegExp(searchTerm.trim());
              const regex = new RegExp(`(${escapedTerm})`, 'giu');
              const subParts = part.split(regex);

              return (
                <span key={j}>
                  {subParts.map((sub, k) => {
                    if (sub.toLowerCase() === searchTerm.trim().toLowerCase()) {
                      const currentId = `match-${localMatchIndex}`;
                      const isCurrent = localMatchIndex === currentMatchIndex;
                      localMatchIndex++;
                      return (
                        <mark 
                          key={k} 
                          id={currentId}
                          className={`${isCurrent ? 'bg-orange-500 text-white' : 'bg-yellow-400 text-black'} font-bold px-0.5 rounded transition-all duration-300`}
                        >
                          {sub}
                        </mark>
                      );
                    }
                    return sub;
                  })}
                </span>
              );
           })}
        </div>
      );
    });
  };

  // UPDATED: Points to local file in /public/background.jpg
  const BACKGROUND_IMAGE_URL = "/background.jpg";

  return (
    <section className="flex-1 flex flex-col overflow-hidden relative transition-all duration-500 ease-in-out">
      {/* Header */}
      <div className="px-4 md:px-8 py-3 md:py-5 border-b border-white/10 flex flex-wrap md:flex-nowrap items-center justify-between bg-slate-900/95 backdrop-blur-md z-20 shrink-0 gap-3">
        <div className="flex items-center space-x-3 group cursor-default mr-auto">
          <div className={`w-3 h-3 rounded-full transition-all duration-300 group-hover:scale-150 ${status === 'completed' ? 'bg-green-400 shadow-[0_0_12px_rgba(74,222,128,0.8)]' : 'bg-white/20'}`}></div>
          <h2 className="text-lg md:text-xl font-bold text-white tracking-tight transition-colors group-hover:text-white/100 text-white/90">{t.outputTranscript}</h2>

          {isSynced && status === 'completed' && transcriptSegments.length > 0 && (
              <button
                  onClick={() => setIsKaraokeEnabled(!isKaraokeEnabled)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all shadow-lg border active:scale-95 ${
                      isKaraokeEnabled 
                      ? 'bg-indigo-600 text-white border-indigo-500 hover:bg-indigo-500 ring-2 ring-indigo-500/20' 
                      : 'bg-white/5 text-white/40 border-white/10 hover:bg-white/10 hover:text-white'
                  }`}
                  title={isKaraokeEnabled ? "Disable Karaoke Mode" : "Enable Karaoke Mode"}
              >
                  <div className={`w-2 h-2 rounded-full ${isKaraokeEnabled ? 'bg-white animate-pulse' : 'bg-slate-500'}`}></div>
                  {appLang === 'bn' ? 'কারাওকে মুড' : 'KARAOKE MODE'}
              </button>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-2 md:gap-4 flex-1 justify-end w-full md:w-auto">
          {/* Header Buttons */}
          <div className={`flex items-center gap-2`}>
            <button 
              onClick={handleSummaryClick}
              className={`p-2 md:p-3 bg-white/5 border border-white/10 rounded-2xl text-white/60 hover:text-white hover:bg-white/10 transition-all hover:scale-110 active:scale-95 group/tool shadow-xl`}
              title={appLang === 'bn' ? 'সার্চ এনালাইসিস' : 'Search Analysis'}
            >
              <svg className="w-4 h-4 md:w-5 md:h-5 transition-transform group-hover/tool:rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 10h16M4 14h10" />
              </svg>
            </button>
            <button 
              onClick={() => setIsReportOpen(true)}
              className={`p-2 md:p-3 bg-white/5 border border-white/10 rounded-2xl text-white/60 hover:text-white hover:bg-white/10 transition-all hover:scale-110 active:scale-95 group/tool shadow-xl`}
              title={appLang === 'bn' ? 'রিপোর্ট' : 'Report'}
            >
              <svg className="w-4 h-4 md:w-5 md:h-5 transition-transform group-hover/tool:-rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </button>
          </div>

          <div 
            className={`relative flex items-center bg-white/5 rounded-full border border-white/10 p-1 shadow-2xl transition-all duration-300 ring-offset-2 ring-offset-slate-900 focus-within:ring-2 focus-within:ring-white/20 w-full md:max-w-[360px] group order-last md:order-none ${isDisabled ? 'opacity-40 pointer-events-none' : ''}`}
          >
            <div className={`w-8 h-8 md:w-9 md:h-9 flex items-center justify-center transition-all duration-300 shrink-0 group-hover:scale-110 ${searchTerm ? activeColors.text : 'text-white/40'}`}>
              <svg className="w-4 h-4 md:w-5 md:h-5 transition-transform group-hover:rotate-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>

            <input 
              ref={transcriptSearchInputRef} 
              type="text" 
              placeholder={t.searchPlaceholder} 
              value={searchTerm} 
              onChange={handleSearchChange}
              onKeyDown={handleKeyDown}
              disabled={isDisabled}
              className="bg-transparent border-none outline-none focus:outline-none focus:ring-0 text-sm font-bold text-white flex-1 px-2 placeholder:text-white/20 min-w-0" 
            />

            {searchTerm && !isDisabled && (
              <div className="flex items-center gap-1 pr-1 animate-in fade-in duration-300">
                <button 
                  onClick={clearSearch}
                  className="w-7 h-7 md:w-8 md:h-8 flex items-center justify-center text-white/40 hover:text-white hover:bg-white/10 rounded-full transition-all"
                  title="Clear Search"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>

                <div className="flex items-center bg-black/40 rounded-full px-2 py-1 gap-1 border border-white/10 shadow-lg">
                  <span className={`text-[9px] font-black ${activeColors.text} tabular-nums min-w-[24px] md:min-w-[32px] text-center`}>
                    {matchCount > 0 ? `${currentMatchIndex + 1}/${matchCount}` : '0/0'}
                  </span>

                  <div className="flex items-center border-l border-white/10 pl-1 ml-1 gap-0.5">
                    <button 
                      onClick={goToPrevMatch}
                      disabled={matchCount === 0}
                      className="w-6 h-6 md:w-7 md:h-7 flex items-center justify-center text-white/60 hover:text-white hover:bg-white/10 rounded-full transition-all disabled:opacity-30"
                      title="Previous Match"
                    >
                      <svg className="w-3 h-3 md:w-3.5 md:h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 15l7-7 7 7" />
                      </svg>
                    </button>

                    <button 
                      onClick={goToNextMatch}
                      disabled={matchCount === 0}
                      className="w-6 h-6 md:w-7 md:h-7 flex items-center justify-center text-white/60 hover:text-white hover:bg-white/10 rounded-full transition-all disabled:opacity-30"
                      title="Next Match"
