        onModelUpdate={onModelUpdate}
        setIsAiLoading={setIsAiLoading}
      />
      <FullscreenAnalysis 
        isOpen={isAnalysisOpen}
        onClose={() => setIsAnalysisOpen(false)}
        history={history}
        transcript={transcript}
        isDark={isDark}
        activeColors={activeColors}
